/* DAWAH X — ahmad, অধ্যায় 54 · খণ্ড 54 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][54]=[[10601,10601,"","আমার ভাই খুশি হওয়ার দুই মাস পর আমি কথা বলেছি, সে একটা চোর নিয়ে একটা আংটির সাথে দেখা করলো... ছিল, হাঁটতে হবে, না হয় তুমি তার বামে যাচ্ছ।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي قِبْلَةِ الْمَسْجِدِ فَحَكَّهَا بِحَصَاةٍ ثُمَّ ‏ ‏نَهَى أَنْ يَبْصُقَ الرَّجُلُ بَيْنَ يَدَيْهِ وَعَنْ يَمِينِهِ وَقَالَ لِيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ الْيُسْرَى ‏","","",""],[10602,10602,"","আমরা দুই মাস ধরে ঈশ্বরের ভালো বাবার মরুভূমি সম্পর্কে কথা বলেছি যে ঈশ্বরকে নয়, সে নারী সংগীতের বোন।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏اخْتِنَاثِ ‏ ‏الْأَسْقِيَةِ ‏","","",""],[10603,10603,"","আমরা দুজন ছেলের সাথে দুই গ্রীষ্মের কথা বলেছি আমার বাবাকে খুশি আর গান শোনার জন্য একটা গোপন নাম দিয়ে। ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তিনি সবার জন্য ওয়াশিং আপ এর জন্য তাকে দায়ী করেছেন। বলেছে, প্রত্যেক মানুষের খাওয়ার দরকার।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏رِوَايَةً ‏ ‏وَقَالَ ‏ ‏مَرَّةً يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْغُسْلُ يَوْمَ الْجُمُعَةِ قَالَ هُوَ وَاجِبٌ عَلَى كُلِّ ‏ ‏مُحْتَلِمٍ ‏","","",""],[10604,10604,"","আমরা ২ বছর ধরে একটা ছেলেকে মারার চেয়ে ভালো কিছু করার কথা বলেছি, যে কিনা ভালো কিছু করতে পারতো, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তাকে ফুলতে আত্মসমর্পণ করতে হবে। তিনি বলেছিলেন তিনি শুনতে শিখলেন তার বক্তব্যে বলা হয়েছে, ওয়ান ফ্যান্টের দুটি জায়গা আছে, আর আমি আগুনের মধ্যে থাকার ভয় পাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَبَا سَعِيدٍ ‏ ‏هَلْ سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْإِزَارِ ‏ ‏شَيْئًا قَالَ نَعَمْ تَعَلَّمْ سَمِعْتُهُ يَقُولُ ‏ ‏إِزْرَةُ ‏ ‏الْمُؤْمِنِ إِلَى أَنْصَافِ سَاقَيْهِ لَا ‏ ‏جُنَاحَ ‏ ‏فِيمَا بَيْنَهُ وَبَيْنَ الْكَعْبَيْنِ وَمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ هُوَ فِي النَّارِ يَقُولُهَا ثَلَاثَ مَرَّاتٍ ‏","","",""],[10605,10605,"","আমরা দুটো জীবন করেছি, আমি আমার ভাইয়ের খুশির সমাপ্তির কথা বলেছি... পাপী আমি ফিরে এসেছি, আর বলেছি যে ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তাকে উদ্ধার করার জন্য যার কাছে তিনি কয়েক সেকেন্ড পেয়েছেন, কিন্তু একটি মেয়ে আপনাকে বলতে না যে আমি আছি বাবা বলেছিলেন যে, তিনি আপনার সঙ্গে থাকবেন না যে, তিনি খুশি হবেন এবং আমি থাকব । সে-ই হবে সেই লোক যে একজন হবে সে-ই হবে সে একজন যে হবে। ( ১ করিন্থীয় ১৫: ৩৩) তাই, সেই ব্যক্তিই হবেন সেই ব্যক্তি, যিনি তাদের মধ্যে সবচেয়ে অযোগ্য ব্যক্তি । তাকে জিজ্ঞেস করা হয়েছিল, তাকে তিন বার অনুমতি দেওয়া হয়নি।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ خُصَيْفَةَ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ فِي حَلْقَةٍ مِنْ حِلَقِ ‏ ‏الْأَنْصَارِ ‏ ‏فَجَاءَنَا ‏ ‏أَبُو مُوسَى ‏ ‏كَأَنَّهُ مَذْعُورٌ فَقَالَ إِنَّ ‏ ‏عُمَرَ ‏ ‏أَمَرَنِي أَنْ آتِيَهُ فَأَتَيْتُهُ فَاسْتَأْذَنْتُ ثَلَاثًا فَلَمْ يُؤْذَنْ لِي فَرَجَعْتُ وَقَدْ قَالَ ذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اسْتَأْذَنَ ثَلَاثًا فَلَمْ يُؤْذَنْ لَهُ فَلْيَرْجِعْ فَقَالَ لَتَجِيئَنَّ ‏ ‏بِبَيِّنَةٍ ‏ ‏عَلَى الَّذِي تَقُولُ وَإِلَّا أَوْجَعْتُكَ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَأَتَانَا ‏ ‏أَبُو مُوسَى ‏ ‏مَذْعُورًا ‏ ‏أَوْ قَالَ فَزِعًا ‏ ‏فَقَالَ أَسْتَشْهِدُكُمْ فَقَالَ ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏لَا يَقُومُ مَعَكَ إِلَّا أَصْغَرُ الْقَوْمِ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَكُنْتُ أَصْغَرَهُمْ فَقُمْتُ مَعَهُ وَشَهِدْتُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ اسْتَأْذَنَ ثَلَاثًا فَلَمْ يُؤْذَنْ لَهُ فَلْيَرْجِعْ ‏","","",""],[10606,10606,"","আমরা দুজন ছেলে কথা বলেছি, বাবা তার বাবার সাথে কতটা খুশি হবে, সে কথা বলেছে যে তার পঞ্চমবারের মধ্যে বন্ধুত্বের জন্য নয় একজন বন্ধু ।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى بْنِ عُمَارَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏رِوَايَةً فَذَكَرَ فِيهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَيْسَ فِيمَا دُونَ خَمْسِ ‏ ‏أَوَاقٍ ‏ ‏صَدَقَةٌ ‏ ‏وَلَا فِيمَا دُونَ خَمْسِ ‏ ‏ذَوْدٍ ‏ ‏صَدَقَةٌ ‏ ‏وَلَا فِيمَا دُونَ خَمْسِ ‏ ‏أَوْسُقٍ ‏ ‏صَدَقَةٌ ‏","","",""],[10607,10607,"","আমার বাবার ছেলে ঈশ্বরের ভালোর ব্যাপারে দুই বছর ধরে কথা বলার পর থেকে আমরা দুই বছর ধরে কাজ করেছি। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি বলবেন যে তিনি করবেন । জিনের কথা শুনো না, না ভুলে যাও, ওর নামে দুইটা সেলাই হয়েছিল আর আমার ছেলের পিপাসার পরে ঈশ্বরের অনুগ্রহে খুশিতে ছেপেছে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ أَبِي صَعْصَعَةَ عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَكَانَ فِي حُجْرَةٍ فَقَالَ لِي يَا بُنَيَّ إِذَا أَذَّنْتَ فَارْفَعْ صَوْتَكَ بِالْأَذَانِ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيْسَ شَيْءٌ يَسْمَعُهُ إِلَّا شَهِدَ لَهُ جِنٌّ وَلَا إِنْسٌ وَلَا حَجَرٌ ‏ ‏و قَالَ ‏ ‏مَرَّةً يَا بُنَيَّ إِذَا كُنْتَ فِي الْبَرَارِيِّ فَارْفَعْ صَوْتَكَ بِالْأَذَانِ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ لَا يَسْمَعُهُ جِنٌّ وَلَا إِنْسٌ وَلَا حَجَرٌ وَلَا شَيْءٌ يَسْمَعُهُ إِلَّا شَهِدَ لَهُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَسُفْيَانُ ‏ ‏مُخْطِئٌ فِي اسْمِهِ وَالصَّوَابُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ ‏","","",""],[10608,10608,"","আমরা আমার বাবার কথা বলেছিলাম... ...যে বাবার জন্য আমার বাবার কথা শোনে, সে একটা মই পাবে... একটা টিউমারের পিছু নিয়েছে, ড্রাগন।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي صَعْصَعَةَ ‏ ‏شَيْخٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوشِكُ أَنْ يَكُونَ خَيْرَ مَالِ الرَّجُلِ الْمُسْلِمِ غَنَمٌ يَتْبَعُ بِهَا ‏ ‏شَعَفَ ‏ ‏الْجِبَالِ وَمَوَاقِعَ ‏ ‏الْقَطْرِ ‏ ‏يَفِرُّ بِدِينِهِ مِنْ الْفِتَنِ ‏","","",""],[10609,10609,"","আমরা দুজন ছেলে আমার বাবার খুশি হওয়ার কথা বলেছি... ...আমার বাবা বলেছিলেন যে তার বাবা শুনতে পাবে... ...সে এমন একজন যে তার কথা শুনেছে সে ছিল সেই ব্যক্তি যে বলবে যে সে হতে যাচ্ছে সে হবে সেই হবে যে হতে যাচ্ছে সে হবে সেই হবে, যে হবে সে হবে সেই হবে, যে হবে সেই হবে সেই হবে, যে হবে সেই ব্যক্তি, যে ছিল সে, যে ছিল সে হবে। তার কথা শুনবে, বজ্রপাতের পরেও তাকে প্রার্থনা করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ضَمْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قُلْتُ ‏ ‏سُفْيَانُ ‏ ‏سَمِعَهُ قَالَ زَعَمَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَلَاةٍ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ وَبَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ ‏","","",""],[10610,10610,"","বাবার সাথে কথা বলার জন্য আমরা দুই বছর সময় করেছি। আর আমি আমার বাবার অভিশাপকে তোমার কাছে ফিরিয়ে দেবার সাহস পাই। একবার সে আমাদের দিয়ে চলে গেলে বলল আমরা ভালো আছি। আজ রাতে তাকে ভুলে গিয়েছিলাম, আর আমাকে সুন্দর, সুন্দর পানিতে খুজে বের করো। আত্মসমর্পণ করতে হবে এবং পানি আর কাদার প্রভাব নিতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏وَابْنُ أَبِي لَبِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ ‏ ‏وَابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏اعْتَكَفَ ‏ ‏الْعَشْرَ الْوَسَطَ ‏ ‏وَاعْتَكَفْنَا ‏ ‏مَعَهُ ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا كَانَ صَبِيحَةُ عِشْرِينَ مَرَّ بِنَا وَنَحْنُ نَنْقُلُ مَتَاعَنَا فَقَالَ مَنْ كَانَ ‏ ‏مُعْتَكِفًا ‏ ‏فَلْيَكُنْ فِي ‏ ‏مُعْتَكَفِهِ ‏ ‏إِنِّي رَأَيْتُ هَذِهِ اللَّيْلَةَ فَنُسِّيتُهَا وَرَأَيْتُنِي أَسْجُدُ فِي مَاءٍ وَطِينٍ وَعَرِيشُ الْمَسْجِدِ جَرِيدٌ فَهَاجَتْ السَّمَاءُ فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّ عَلَى أَنْفِهِ وَجَبْهَتِهِ أَثَرَ الْمَاءِ وَالطِّينِ ‏","","",""],[10611,10611,"","আমরা দুই বছর আগে একটি ছোট ছেলের কথা বলেছি যে কিনা পূর্বে ঈশ্বরের সাথে দেখা করেছিল... ...আমার বাবার গোপন কথা শুনেই খুশি হবে, নাকি খুশি হবে, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করবেন। আমি যা করতে ভয় পাই তা হলো, আমি তোমাকে হারানোর জন্য। একজন লোক বললো, ঈশ্বর কি খারাপ কিছু হতে পারে,\" সে তাই ছিল। প্রশ্ন হলো, আমি যেতে চাইনি, ঈশ্বর ঠিক আছে বলে। যদি ভালো ভালো কিছু হারিয়ে না যায়, অথবা ব্যথাটা না খায়, তাহলে তাকেও খেয়ে ফেলা হবে। তোমার আলোটা ঠিক আছে, আর কে তাকে নিয়ে গেছে... ...আর সে কখনোই এত নির্দোষ ছিল না, আমি জীবিত আছি।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ عَبْدِ اللَّهِ بْنِ سَعْدِ بْنِ أَبِي سَرْحٍ ‏ ‏سَمِعَ ‏ ‏أَبَا سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَلَى الْمِنْبَرِ إِنَّ أَخْوَفَ مَا أَخَافُ عَلَيْكُمْ مَا يُخْرِجُ اللَّهُ مِنْ نَبَاتِ الْأَرْضِ وَزَهْرَةِ الدُّنْيَا فَقَالَ رَجُلٌ أَيْ رَسُولَ اللَّهِ ‏ ‏أَوَ يَأْتِي الْخَيْرُ بِالشَّرِّ فَسَكَتَ حَتَّى رَأَيْنَا أَنَّهُ يَنْزِلُ عَلَيْهِ قَالَ وَغَشِيَهُ ‏ ‏بُهْرٌ ‏ ‏وَعَرَقٌ فَقَالَ أَيْنَ السَّائِلُ فَقَالَ هَا أَنَا وَلَمْ أُرِدْ إِلَّا خَيْرًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْخَيْرَ لَا يَأْتِي إِلَّا بِالْخَيْرِ إِنَّ الْخَيْرَ لَا يَأْتِي إِلَّا بِالْخَيْرِ إِنَّ الْخَيْرَ لَا يَأْتِي إِلَّا بِالْخَيْرِ وَلَكِنَّ الدُّنْيَا خَضِرَةٌ حُلْوَةٌ وَكَانَ مَا يُنْبِتُ الرَّبِيعُ يَقْتُلُ ‏ ‏حَبَطًا ‏ ‏أَوْ ‏ ‏يُلِمُّ ‏ ‏إِلَّا آكِلَةُ الْخَضِرِ فَإِنَّهَا أَكَلَتْ حَتَّى ‏ ‏امْتَدَّتْ خَاصِرَتَاهَا ‏ ‏وَاسْتَقْبَلَتْ الشَّمْسَ ‏ ‏فَثَلَطَتْ ‏ ‏وَبَالَتْ ثُمَّ عَادَتْ فَأَكَلَتْ فَمَنْ أَخَذَهَا بِحَقِّهَا بُورِكَ لَهُ فِيهِ وَمَنْ أَخَذَهَا بِغَيْرِ حَقِّهَا لَمْ يُبَارَكْ لَهُ وَكَانَ كَالَّذِي يَأْكُلُ وَلَا يَشْبَعُ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏وَكَانَ ‏ ‏الْأَعْمَشُ ‏ ‏يَسْأَلُنِي عَنْ هَذَا الْحَدِيثِ ‏","","",""],[10612,10612,"","আমার বাবার মৃত্যুর দুই বছর ধরে আমার বাবার মৃত্যুর জন্য আমি আমার বাবাকে খুশি করে দিয়েছি যে ঈশ্বরকে উদ্ধার করেছে আর এটা করবে। যদি সে সবাই একত্রিত হয়, সে ফিরে যেতে চায় এবং বলে \"পাপ\" খুশি তুমি মুক্ত হয়ে গেলে, সে আমার বাবার খুশির কথা... ...একটা লাইন অথবা একটা লাইনকে হত্যা করতে ভয় পায়...","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَتَوَضَّأُ إِذَا جَامَعَ وَإِذَا أَرَادَ أَنْ يَرْجِعَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَدْرَكَ ‏ ‏الْحَرَّةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏يَقْتُلُ ‏ ‏حَبَطًا ‏ ‏أَوْ ‏ ‏خَبْطًا ‏ ‏وَإِنَّمَا هُوَ ‏ ‏حَبَطًا ‏","","",""],[10613,10613,"","সে বলেছে সে তোমাকে ছেড়ে দেবে না, অন্ধকার তার নিয়তিকে বদলে দেয় আর দুই জায়গা থেকে শুনতে পায়। উদ্ধার","‏ ‏قَالَ ‏ ‏سَمِعْت ‏ ‏سُفْيَانَ ‏ ‏قَالَ ‏ ‏وَإِنَّ اللَّهَ عَزَّ وَجَلَّ مُسْتَخْلِفُكُمْ فِيهَا فَيَنْظُرُ كَيْفَ تَعْمَلُونَ أَلَا وَإِنَّ لِكُلِّ ‏ ‏غَادِرٍ ‏ ‏لِوَاءً ‏ ‏يَوْمَ الْقِيَامَةِ عِنْدَ اسْتِهِ بِقَدْرِ ‏ ‏غَدْرَتِهِ ‏ ‏وَقُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏سَمِعْتُ ‏ ‏عَلِيَّ بْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[10614,10614,"","আমরা দুই বছর ধরে কথা বলেছি আমার বাবা তার শান্তি লাভ করেছেন। লন্ড্রি তৈরি করেছে.","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَيْفَ أَنْعَمُ وَقَدْ الْتَقَمَ صَاحِبُ الْقَرْنِ الْقَرْنَ ‏ ‏وَحَنَى ‏ ‏جَبْهَتَهُ وَأَصْغَى سَمْعَهُ يَنْظُرُ مَتَى يُؤْمَرُ قَالَ الْمُسْلِمُونَ يَا رَسُولَ اللَّهِ فَمَا نَقُولُ قَالَ قُولُوا ‏ ‏حَسْبُنَا ‏ ‏اللَّهُ وَنِعْمَ الْوَكِيلُ عَلَى اللَّهِ تَوَكَّلْنَا ‏","","",""],[10615,10615,"","আমরা রাজার আদর্শের দুই বছর কথা বলেছি, তুমি আমার সাথে তিনদিন কাটাতে পারবেনা তার সাথে অপরাধী হওয়ার কারণে.","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏رِوَايَةً يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُسَافِرُ الْمَرْأَةُ ثَلَاثَةَ أَيَّامٍ إِلَّا وَمَعَهَا ذُو مَحْرَمٍ ‏","","",""],[10616,10616,"","সে সিল্ক কাল আর সিল্কের দিন নিয়ে কথা বলছে।","‏ ‏وَنَهَى عَنْ صِيَامِ الْفِطْرِ وَيَوْمِ النَّحْرِ ‏","","",""],[10617,10617,"","বজ্রপাতের পর সে দুই প্রার্থনার মধ্যে পড়ে যায় এবং আঙ্গুলে আঙ্গুল তুলে, যতক্ষণ না সূর্য নামতে না আসে।","‏ ‏وَنَهَى عَنْ صَلَاتَيْنِ صَلَاةٍ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ وَبَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ ‏","","",""],[10618,10618,"","যাত্রা তোমার ইচ্ছার মহিমার উন্নতি করবে না.","‏ ‏وَلَا تُشَدُّ الرِّحَالُ إِلَّا إِلَى ثَلَاثَةِ مَسَاجِدَ ‏ ‏الْمَسْجِدِ الْحَرَامِ ‏ ‏وَمَسْجِدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمَسْجِدِ الْأَقْصَى ‏","","",""],[10619,10619,"","আমরা দুজন ছেলে কথা বলেছি তারা আমার বাবার সাথে আমাকে সুখী করেছে. তারা বলে আমরা জয়ী, তারা জয়ী, তারা বলছে, \"আপনার কি ভাল সকাল আছে? তারা বলবে, আমরা এটা করতে পারি এবং তারপর একটি জয় লাভ করব। তারা বলে, \"আমরা কি এটা করতে পারি?\" তারা বলবে, \"আমরা কি এটা করতে পারি এবং তারপর একটি জয়ের জন্য?\" তারা বলল, তারা বলল, \"তারা জিতল, তারা জিতে যাবে।\" এবং তারপর তারা জয়ী হবে। তারা বলল, তারা বলল, \"তারা জয়ী হবে।\" এবং তারপর তারা বলল, \"তারা জিতল, তারা জয়ী হবে।\" এবং তারপর তারা বলল, তারা বলল, \"তারা জিতল, \"আমরা জিতবো,\" এবং তারপর তারা জয়ী হল, তারা জানে, তারা জয়ী হবে। তারা জানে যে, তারা জয়ী হয়েছে, তারা জানে, তারা জানে, তারা জয়ী হয়েছে। কয়েক বছর ধরে মানুষ বলে যে এটা একটা চোখ দিয়ে লেখা, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করবেন বলে আমরা প্রার্থনা করব যাতে তারা তা করতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏سَمِعَ ‏ ‏جَابِرًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِي عَلَى النَّاسِ زَمَانٌ يَغْزُو ‏ ‏فِئَامٌ ‏ ‏مِنْ النَّاسِ فَيُقَالُ هَلْ فِيكُمْ مَنْ صَاحَبَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُولُونَ نَعَمْ فَيُفْتَحُ لَهُمْ ثُمَّ يَغْزُو ‏ ‏فِئَامٌ ‏ ‏مِنْ النَّاسِ فَيُقَالُ هَلْ فِيكُمْ مَنْ صَاحَبَ مَنْ صَاحَبَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُولُونَ نَعَمْ فَيُفْتَحُ لَهُمْ ثُمَّ يَغْزُو ‏ ‏فِئَامٌ ‏ ‏مِنْ النَّاسِ فَيَقُولُونَ هَلْ فِيكُمْ مَنْ صَاحَبَ مَنْ صَاحَبَ ‏ ‏أَصْحَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُولُونَ نَعَمْ فَيُفْتَحُ لَهُمْ ‏","","",""],[10620,10620,"","দুই বছর আগে আমরা আমার সুখী বাবাকে ঈশ্বরকে কথা বলার চেষ্টা করেছি। আমি দুই বছর সময় দেব, যদি আমি মানুষের জন্য ঈশ্বরের সেবা করি। আমরা খুঁজে পাওয়ার ইচ্ছা নিয়ে উড়ছি","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏سَمِعَ ‏ ‏عَمْرًا ‏ ‏عَنْ ‏ ‏عَتَّابِ بْنِ حُنَيْنٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏لَا أَدْرِي مَنْ ‏ ‏عَتَّابٌ ‏ ‏لَوْ أَمْسَكَ اللَّهُ ‏ ‏الْقَطْرَ ‏ ‏عَنْ النَّاسِ سَبْعَ سِنِينَ ثُمَّ أَرْسَلَهُ لَأَصْبَحَتْ طَائِفَةٌ بِهِ كَافِرِينَ يَقُولُونَ مُطِرْنَا ‏ ‏بِنَوْءِ ‏ ‏الْمِجْدَحِ ‏","","",""],[10621,10621,"","আমার ভাইয়ের কথা বলেছিলাম, কিন্তু আমাদের কখনো বয়ফ্রেন্ড ছিল না। বাবা খুশি যে আমরা ঈশ্বরের লর্ডের সাথে দেখা করেছি আর লর্ডকে দু'টো দিতে বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكُ بْنُ أَبِي نَمِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الِاثْنَيْنِ إِلَى ‏ ‏قُبَاءَ ‏","","",""],[10622,10622,"","আমরা আমাদের বাবার সঙ্গে কথা বলেছিলাম, যখন আমরা তার সম্বন্ধে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الرِّجَالِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَارَةُ بْنُ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَأَلَ وَلَهُ قِيمَةُ ‏ ‏أُوقِيَّةٍ ‏ ‏فَقَدْ ‏ ‏أَلْحَفَ ‏","","",""],[10623,10623,"","আমরা আশা করছি আমার কিছু একটা একটা একটা হবে... ...যার মানে আমার সাথে এমন একটা ছেলে, ঈশ্বরের কাছে প্রার্থনা করেছে তার জন্য। দেয়ালটা তৃতীয় উত্তর দিচ্ছে এটা খাওয়ার জন্য না, একবার যদি আমি তোমাকে চ্যালেঞ্জ করি।","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلُ بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَتَى أَحَدُكُمْ ‏ ‏حَائِطًا ‏ ‏فَأَرَادَ أَنْ يَأْكُلَ فَلْيُنَادِ يَا صَاحِبَ ‏ ‏الْحَائِطِ ‏ ‏ثَلَاثًا فَإِنْ أَجَابَهُ وَإِلَّا فَلْيَأْكُلْ وَإِذَا مَرَّ أَحَدُكُمْ بِإِبِلٍ فَأَرَادَ أَنْ يَشْرَبَ مِنْ أَلْبَانِهَا فَلْيُنَادِ يَا صَاحِبَ الْإِبِلِ ‏ ‏أَوْ يَا رَاعِيَ الْإِبِلِ ‏ ‏فَإِنْ أَجَابَهُ وَإِلَّا فَلْيَشْرَبْ وَالضِّيَافَةُ ثَلَاثَةُ أَيَّامٍ فَمَا زَادَ فَهُوَ ‏ ‏صَدَقَةٌ ‏","","",""],[10624,10624,"","বাবা বলেছিল, প্রথম মানুষ এগিয়ে যাওয়ার জন্য... তার কাছে আর তাকে ঈশ্বরের অনুগ্রহে দেয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عِمْرَانُ بْنُ أَبِي أَنَسٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏تَمَارَى ‏ ‏رَجُلَانِ فِي الْمَسْجِدِ الَّذِي أُسِّسَ عَلَى التَّقْوَى مِنْ أَوَّلِ يَوْمٍ فَقَالَ رَجُلٌ هُوَ ‏ ‏مَسْجِدُ قُبَاءَ ‏ ‏وَقَالَ رَجُلٌ هُوَ ‏ ‏مَسْجِدُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ ‏ ‏مَسْجِدِي ‏","","",""],[10625,10625,"","আমরা আবেগে বাপ্তাইজিত হয়েছি যে সে মারা গেছে, আর আমার বাবা একজন পলাতক... ...সে লর্ডের অতিথি। আত্মসমর্পণ করো.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏حَدَّثَ أَنَّ ‏ ‏ذَكْوَانَ أَبَا صَالِحٍ ‏ ‏حَدَّثَ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏وَجَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏أَنَّهُمْ ‏ ‏نُهُوا عَنْ ‏ ‏الصَّرْفِ ‏ ‏وَرَفَعَهُ رَجُلَانِ مِنْهُمْ إِلَى نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[10626,10626,"","আমরা কথা বলেছিলাম যে কি হবে, আমরা খুশি হব... ...দুই রহস্যের সুরক্ষার ব্যাপারে যেটা হয়তো বাকি ছিল। ঈশ্বর ও আমার বাবা সুখী ও সুখী ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏مَطَرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏أَنَّ ‏ ‏ذَكْوَانَ أَبَا صَالِحٍ ‏ ‏قَالَ ‏ ‏وَأَثْنَى عَلَيْهِ خَيْرًا ‏ ‏حَدَّثَ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏أَنَّهُمْ ‏ ‏نُهُوا عَنْ ‏ ‏الصَّرْفِ ‏ ‏رَفَعَهُ رَجُلَانِ مِنْهُمْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[10627,10627,"","আমার বাবার ভালো মানুষ হওয়া নিয়ে আমরা খুশি। গ্রীষ্ম।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏وَجَابِرٍ ‏ ‏اثْنَيْنِ مِنْ هَؤُلَاءِ الثَّلَاثَةِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الصَّرْفِ ‏","","",""],[10628,10628,"","আমার বাবা ঈশ্বরের কাছে প্রার্থনা করেছেন এবং রক্তের পাপের পাপ স্বীকার করে নেওয়ার আশা পরিত্যাগ করেছেন । ঈশ্বর তাকে পাঠিয়েছেন, আর তারপর তারা ঈশ্বরের পথে দেখেননি আর তারপর তিনি হবেন তার জন্য আমি সম্মানিত। সমবেদনা জানাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي السَّمْحِ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُؤْمِنُونَ فِي الدُّنْيَا عَلَى ثَلَاثَةِ أَجْزَاءٍ الَّذِينَ آمَنُوا بِاللَّهِ وَرَسُولِهِ ثُمَّ لَمْ يَرْتَابُوا وَجَاهَدُوا بِأَمْوَالِهِمْ وَأَنْفُسِهِمْ فِي سَبِيلِ اللَّهِ وَالَّذِي يَأْمَنُهُ النَّاسُ عَلَى أَمْوَالِهِمْ وَأَنْفُسِهِمْ ثُمَّ الَّذِي إِذَا أَشْرَفَ عَلَى طَمَعٍ تَرَكَهُ لِلَّهِ عَزَّ وَجَلَّ ‏","","",""],[10629,10629,"","আমরা একটি দৃষ্টি দিয়ে খুশি হব কিন্তু বাপ্তিস্মের ব্যাপারে কথা বলা ভালো। আমার বাবা তাকে ঈশ্বরের কাছে প্রার্থনা করতে শিখিয়েছিলেন যাতে তিনি আমার মায়ের কাছ থেকে দূরে থাকেন।","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏رُبَيْحُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحَّى بِكَبْشٍ أَقْرَنَ وَقَالَ هَذَا عَنِّي وَعَمَّنْ لَمْ يُضَحِّ مِنْ أُمَّتِي ‏","","",""],[10630,10630,"","আমি আমার আত্মার আনন্দের প্রতি বাধ্য হতে চেষ্টা করেছি। আমার বাবা তার শান্তি ও করুণা কামনা করে খুশি। ভাস্কর্য।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِدْرِيسَ يَعْنِي الشَّافِعَيَّ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏مَوْلَى ‏ ‏أَبِي أَحْمَدَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الْمُزَابَنَةِ وَالْمُحَاقَلَةِ ‏ ‏وَالْمُزَابَنَةُ اشْتِرَاءُ التَّمْرِ بِالتَّمْرِ فِي رُءُوسِ النَّخْلِ وَالْمُحَاقَلَةُ ‏ ‏اسْتِكْرَاءُ ‏ ‏الْأَرْضِ ‏ ‏بِالْحِنْطَةِ ‏","","",""],[10631,10631,"","আমরা তো বলেছি, আমার বাবা হয়ত শুনেছেন যে আমি বেঁচে আছি। ঈশ্বরের সেবা করে খুশি হলাম, সে বলবে সে রাতে তোমাকে যেতে বলে না। বলো, ঈশ্বর আমি বানরের তৃতীয় ভাগ","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏الضَّحَّاكِ الْمَشْرِقِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ أَيَعْجِزُ أَحَدُكُمْ أَنْ يَقْرَأَ ثُلُثَ الْقُرْآنِ فِي لَيْلَةٍ قَالَ فَشَقَّ ذَلِكَ عَلَى أَصْحَابِهِ فَقَالُوا مَنْ يُطِيقُ ذَلِكَ قَالَ ‏ ‏يَقْرَأُ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏فَهِيَ ثُلُثُ الْقُرْآنِ ‏","","",""],[10632,10632,"","আমরা লড়াই করার চেয়ে সুখী এক দম্পতিকে চিঠি লেখার চেষ্টা করেছি, সে যদি এটা দেখে যে সে এটা পছন্দ করে, তাহলে সে বলবে, সে এমন একজনকে দেখবে যে তাকে ভালোবাসে। সে তার সাথে কথা বলতে চায়। তাই সে আছে। তোমার মন মনে করতে লাগলো সে একটা প্রেত, তাকে আঘাত করছে না।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنِ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ خَبَّابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا رَأَى أَحَدُكُمْ الرُّؤْيَا يُحِبُّهَا فَإِنَّمَا هِيَ مِنْ اللَّهِ فَلْيَحْمَدْ اللَّهَ عَلَيْهَا وَلْيُحَدِّثْ بِهَا فَإِذَا رَأَى غَيْرَ ذَلِكَ مِمَّا يَكْرَهُ فَإِنَّمَا هِيَ مِنْ الشَّيْطَانِ فَلْيَسْتَعِذْ بِاللَّهِ مِنْ شَرِّهَا وَلَا يَذْكُرُهَا لِأَحَدٍ فَإِنَّهَا لَا تَضُرُّهُ ‏","","",""],[10633,10633,"","আমরা ঈশ্বরের পুত্র যে আঘাত পেয়েছে তা খুঁজে বের করার চেষ্টা করেছি, কিন্তু ঈশ্বরের দ্বারা, ঈশ্বরের দ্বারা, ঈশ্বরের দ্বারা, ঈশ্বরের দ্বারা, আমি তার সাথে বিশ্বাসঘাতকতা করব। তিনি শুনেছেন যে তিনি এটা প্রদান করবেন। আর প্রার্থনা না করলে আমি আমার সুযোগ পাব বলে প্রার্থনা করব। তারা বলেছে, তুমি এখনো বলছ আমি তোমার বাবার মত না।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنِ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ خَبَّابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏تُوَاصِلُوا ‏ ‏فَأَيُّكُمْ أَرَادَ أَنْ ‏ ‏يُوَاصِلَ ‏ ‏فَلْيُوَاصِلْ ‏ ‏حَتَّى ‏ ‏السَّحَرِ ‏ ‏فَقَالُوا إِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ إِنِّي لَسْتُ كَهَيْئَتِكُمْ إِنِّي أَبِيتُ لِي مُطْعِمٌ يُطْعِمُنِي وَسَاقٍ ‏ ‏يَسْقِينِي ‏","","",""],[10634,10634,"","আমরা ঈশ্বরের ছেলেকে খুঁজে বের করার চেষ্টা করেছি, যাকে আমি ভালোবাসি।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏دَرَّاجٍ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏حَلِيمَ ‏ ‏إِلَّا ذُو عِزَّةٍ وَلَا حَكِيمَ إِلَّا ذُو تَجْرِبَةٍ ‏","","",""],[10635,10635,"","আমরা একটি সুখী দম্পতি লিখতে চেষ্টা করেছি আমরা বিয়ে করার চেষ্টা করেছি. মাদক বলেছিল যে আমরা যখন ঈশ্বরের সাথে গমনাগমন করছি তখন কিছু খারাপ হবে ঈশ্বর মানুষকে শয়তানের হাত থেকে উদ্ধার করতে হবে অথবা রাজার আত্মাকে স্পর্শ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنِ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏يُحَنَّسَ ‏ ‏مَوْلَى ‏ ‏مُصْعَبِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ نَسِيرُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْعَرْجِ ‏ ‏إِذْ عَرَضَ شَاعِرٌ يُنْشِدُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذُوا الشَّيْطَانَ ‏ ‏أَوْ أَمْسِكُوا الشَّيْطَانَ ‏ ‏لَأَنْ يَمْتَلِئَ جَوْفُ رَجُلٍ قَيْحًا خَيْرٌ لَهُ مِنْ أَنْ يَمْتَلِئَ شِعْرًا ‏","","",""],[10636,10636,"","আমি এক সুখী ছেলেকে চিঠি লেখার চেষ্টা করেছিলাম, যে একজন দাস হিসেবে আমার সঙ্গে এমন একটা ছেলে হয়েছিল, যার কাছে একজন ঈশ্বরের কাছে প্রার্থনা করতে হবে । ...তার হৃদয় পূর্ণ করার জন্য.","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْخَبَّابِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذُكِرَ عِنْدَهُ عَمُّهُ ‏ ‏أَبُو طَالِبٍ ‏ ‏فَقَالَ ‏ ‏لَعَلَّهُ تَنْفَعُهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ فَيُجْعَلَ فِي ‏ ‏ضَحْضَاحٍ ‏ ‏مِنْ نَارٍ يَبْلُغُ كَعْبَهُ يَغْلِي مِنْهُ دِمَاغُهُ ‏","","",""],[10637,10637,"","আমরা একটি সুখী দম্পতি লিখতে চেষ্টা করেছি, আমি আমার বাবাকে সাহায্য করার কথা বলেছিলাম। তিনি বলেছিলেন, আমি একটা পাখির ছেলে যে আমার বাবাকে দেখতে পেরে খুশি হব। ঈশ্বর তাকে আদেশ দিয়েছেন। আমি যদি আমার বাবার সাথে দেখা করতে চাই, তাহলে আমি আপনাকে এই বিষয়ে কথা বলি যে, আমি আপনার বাবা-কে সাহায্য করতে চাই। আমি যদি আমার বাবা আমাদের বাবা আমাদের সাথে কথা বলি, তাহলে আমি তাকে সাহায্য করতে চাই। আর আমি যদি আমার বাবা আমাদের সাথে নেই, তাহলে আমি তাকে সাহায্য করতে চাই। আমি যদি আমার বাবা আমাদের বাবা আমাদের সাথে যোগ করি, আমি তাকে সাহায্য করতে চাই। আমি জানি যে আমি এই বিষয়ে কথা বলি, তাহলে আমরা তাকে আমি কি করতে পারি? আমি জানি না যে, আমি জানি না যে, আমি জানি না যে, আমি এই বিষয়ে আমার বাবা আমাকে খুব খুশি। আর তাকে বলে আমার বাবা খুশি হয়েছে যে ঈশ্বর তাকে আদেশ দিয়েছেন আর আমাকে আদেশ দিয়েছেন, সে পরিকল্পনার আগেই মারা যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي يَعْقُوبَ الْخَيَّاطِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ مَعَ ‏ ‏مُصْعَبِ بْنِ الزُّبَيْرِ ‏ ‏الْفِطْرَ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَأَرْسَلَ إِلَى ‏ ‏أَبِي سَعِيدٍ ‏ ‏فَسَأَلَهُ كَيْفَ كَانَ يَصْنَعُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي قَبْلَ أَنْ يَخْطُبَ فَصَلَّى يَوْمَئِذٍ قَبْلَ الْخُطْبَةِ ‏","","",""],[10638,10638,"","আমার বাবা যে - লোকেদের প্রেম করতেন, তাদের প্রতি আমরা হয়তো এক সুখী দাসকে চেষ্টা করার চেষ্টা করতাম । মা খুশি মনে ঈশ্বরের কাছে থাকবে, আমি তাকে খুন করবো, যে এটা গান গাইবে, যে আল্লাহকে ক্ষমা করবে এবং তাকে মাফ করবে। আমরা বাবার ছেলের ব্যাপারে কথা বলেছিলাম, যাকে আমরা ভালোবাসি।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الرِّجَالِ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَرَّحَتْنِي أُمِّي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْأَلُهُ فَأَتَيْتُهُ فَقَعَدْتُ قَالَ فَاسْتَقْبَلَنِي فَقَالَ ‏ ‏مَنْ اسْتَغْنَى أَغْنَاهُ اللَّهُ وَمَنْ ‏ ‏اسْتَعَفَّ ‏ ‏أَعَفَّهُ ‏ ‏اللَّهُ وَمَنْ اسْتَكْفَى كَفَاهُ اللَّهُ وَمَنْ سَأَلَ وَلَهُ قِيمَةُ ‏ ‏أُوقِيَّةٍ ‏ ‏فَقَدْ ‏ ‏أَلْحَفَ ‏ ‏قَالَ فَقُلْتُ نَاقَتِي الْيَاقُوتَةُ هِيَ خَيْرٌ مِنْ ‏ ‏أُوقِيَّةٍ ‏ ‏فَرَجَعْتُ وَلَمْ أَسْأَلْهُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الرِّجَالِ ‏ ‏نَحْوَهُ ‏","","",""],[10639,10639,"","আমরা আমাদের নিজের বাবাকে খুন করার চেষ্টা করেছি, আর বাবা ভালোর জন্য সব থেকে ভালোর জন্য প্রার্থনা করেছে, আর তাকে দেয়া হবে দুঃখ নিয়ে না যেতে।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ يَعْنِي الْقَارِئَ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَبِيعُوا الذَّهَبَ بِالذَّهَبِ وَلَا ‏ ‏الْوَرِقَ ‏ ‏بِالْوَرِقِ ‏ ‏إِلَّا وَزْنًا بِوَزْنٍ مِثْلًا بِمِثْلٍ سَوَاءً بِسَوَاءٍ ‏","","",""],[10640,10640,"","তিনি বলেন যদি তাপ পাওয়া যায়, তাহলে তাদের ক্ষতের আবরণ থেকে মুক্ত করা হবে।","‏ ‏و قَالَ ‏ ‏إِذَا اشْتَدَّ الْحَرُّ ‏ ‏فَأَبْرِدُوا ‏ ‏بِالصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏","","",""],[10641,10641,"","আমরা ঈশ্বরের সাথে কথা বলেছি আমার বাবার কথা বলার জন্য চেষ্টা করাটা আমার বাবার জন্য খুব খুশি যে সে যেন ঈশ্বরের সর্বোচ্চ আদেশ পালন করে। আর এটা এক ঘন্টার মধ্যে রেখে দিন বেড়ে যায়। শেষ।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَامِرٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اشْتَهَى الْمُؤْمِنُ الْوَلَدَ فِي الْجَنَّةِ كَانَ حَمْلُهُ وَوَضْعُهُ وَسِنُّهُ فِي سَاعَةٍ وَاحِدَةٍ كَمَا ‏ ‏يَشْتَهِي ‏","","",""],[10642,10642,"","আমি যখন তাকে জিজ্ঞেস করি যে, আমি কি আমার বাবা - মার সঙ্গে যুদ্ধ করার চেষ্টা করছি, তখন আমি সুখী হই । মুখ, সে তাকে বাঁচিয়েছিল।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏حَدَّثَنِي ‏ ‏عِيَاضُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ ‏ ‏الْعَرَاجِينَ ‏ ‏يُمْسِكُهَا فِي يَدِهِ ‏ ‏فَدَخَلَ الْمَسْجِدَ فَرَأَى ‏ ‏نُخَامَةً ‏ ‏فِي قِبْلَةِ الْمَسْجِدِ ‏ ‏فَحَتَّهَا ‏ ‏بِهِ حَتَّى أَنْقَاهَا ‏","","",""],[10643,10643,"","আমরা আমার ভাইয়ের চেয়ে ভালো কথা বলেছি। তাদের সাথে মিশে যাবে.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ نَهَى عَنْ ‏ ‏الْجَرِّ ‏ ‏أَنْ ‏ ‏يُنْبَذَ ‏ ‏فِيهِ وَعَنْ التَّمْرِ وَالزَّبِيبِ أَنْ يُخْلَطَ بَيْنَهُمَا وَعَنْ ‏ ‏الْبُسْرِ ‏ ‏وَالتَّمْرِ أَنْ يُخْلَطَ بَيْنَهُمَا ‏","","",""],[10644,10644,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং আমি যদি স্বর্গ ও আগুনের সময় পর্যন্ত প্রবেশ করি, তা হলে তাকে আত্মসমর্পণ করতে হবে । আগুন ও আগুন যখন আসবে তখন হবে আগুনে, অগ্নির স্থান, জেনে যাবে যে এটা হবে হবে নরকের জন্য । ( গীতসংহিতা ৩৭: ১১) সেই রহস্য হল, রাজকুমারকে তার হাতে একটা ঘরে রাখা । আমি আগুন জ্বালাই, আগুনের অস্তিত্ব যেন বন্য.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَمُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ أَهْلُ الْجَنَّةِ الْجَنَّةَ وَأَهْلُ النَّارِ النَّارَ يُجَاءُ بِالْمَوْتِ كَأَنَّهُ كَبْشٌ ‏ ‏أَمْلَحُ ‏ ‏فَيُوقَفُ بَيْنَ الْجَنَّةِ وَالنَّارِ فَيُقَالُ يَا أَهْلَ الْجَنَّةِ هَلْ تَعْرِفُونَ هَذَا قَالَ ‏ ‏فَيَشْرَئِبُّونَ ‏ ‏فَيَنْظُرُونَ وَيَقُولُونَ نَعَمْ هَذَا الْمَوْتُ قَالَ فَيُقَالُ يَا أَهْلَ النَّارِ هَلْ تَعْرِفُونَ هَذَا قَالَ ‏ ‏فَيَشْرَئِبُّونَ ‏ ‏فَيَنْظُرُونَ وَيَقُولُونَ نَعَمْ هَذَا الْمَوْتُ قَالَ فَيُؤْمَرُ بِهِ فَيُذْبَحُ قَالَ وَيُقَالُ يَا أَهْلَ الْجَنَّةِ خُلُودٌ لَا مَوْتَ وَيَا أَهْلَ النَّارِ خُلُودٌ لَا مَوْتَ قَالَ ثُمَّ قَرَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏وَأَنْذِرْهُمْ يَوْمَ الْحَسْرَةِ إِذْ قُضِيَ الْأَمْرُ وَهُمْ فِي غَفْلَةٍ ‏} ‏قَالَ وَأَشَارَ بِيَدِهِ ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏فِي حَدِيثِهِ إِذَا دَخَلَ أَهْلُ الْجَنَّةِ الْجَنَّةَ وَأَهْلُ النَّارِ النَّارَ يُجَاءُ بِالْمَوْتِ كَأَنَّهُ كَبْشٌ ‏ ‏أَمْلَحُ ‏","","",""],[10645,10645,"","আমরা আমার বাবার সাথে কথা বলেছিলাম সে ঈশ্বরকে বলে যে, সে একজন বাবা হিসেবে বড় হবে, যে কখনোই এমন মানুষ হবে না, যার আগে কখনো হয়নি। এমন একজন মানুষ যে কিনা কখনো ছেলে ছিল না, সেই মেয়ে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلِي وَمَثَلُ النَّبِيِّينَ مِنْ قَبْلِي كَمَثَلِ رَجُلٍ بَنَى دَارًا فَأَتَمَّهَا إِلَّا ‏ ‏لَبِنَةً ‏ ‏وَاحِدَةً فَجِئْتُ أَنَا فَأَتْمَمْتُ تِلْكَ ‏ ‏اللَّبِنَةَ ‏","","",""],[10646,10646,"","আমরা আমার বাবা ঈশ্বরকে খুঁজে পেতে আমাকে সাহায্য করার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا ‏} ‏قَالَ عَدْلًا ‏","","",""],[10647,10647,"","আমরা আমার বাবার সাথে কথা বলেছি, আমার ভাইকে সাহায্য করার চেষ্টা করছে, সে ঈশ্বরের প্রার্থনার কথা উল্লেখ করেছে, সে তাকে চিনত এবং সে বলেছে যে, সে তার ঘোড়া নিয়ে আসতে এবং তোমার সাথে যেতে চায়। চোখ.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَعْدٍ الطَّائِيِّ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَاحِبَ الصُّورِ فَقَالَ ‏ ‏عَنْ يَمِينِهِ ‏ ‏جِبْرِيلُ ‏ ‏وَعَنْ يَسَارِهِ ‏ ‏مِيكَائِيلُ ‏ ‏عَلَيْهِمْ السَّلَام ‏","","",""],[10648,10648,"","বাবার দোহাইের জন্য আমার বাবার সাথে ঝগড়ার কথা বলেছিলাম, আমরা ঈশ্বরের কাছে অনুরোধ করেছিলাম তার আদেশ আছে আর তাকে তিন সপ্তাহের মধ্যে আত্মসমর্পণ করতে হবে সে বলেছে, সে মারা গেছে। বরং আমরা বরং করতাম। আমি যদি ওদের মেরে ফেলি, আমাদের একে অপরকে খুন করতে হবে। এমনকি তারা আমাদের এমন কিছু দিতে বলেছে যা আমরা তোমাকে দিয়েছি, বলে আমি আবারও এটা করতে চাই। আমরা ইতোমধ্যে খরচ করেছি। সে বলেছিল, ছেলেটা যদি লর্ডকে না পেয়ে থাকে, সে জানতো সে একজন নৃত্যশিল্পী যে তাকে বিভক্ত করেছে এবং তাদের সাথে মারল।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ إِيَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏سَرِيَّةٍ ‏ ‏ثَلَاثِينَ رَاكِبًا قَالَ فَنَزَلْنَا بِقَوْمٍ مِنْ ‏ ‏الْعَرَبِ ‏ ‏قَالَ فَسَأَلْنَاهُمْ أَنْ يُضَيِّفُونَا فَأَبَوْا قَالَ فَلُدِغَ سَيِّدُهُمْ قَالَ فَأَتَوْنَا فَقَالُوا فِيكُمْ أَحَدٌ ‏ ‏يَرْقِي ‏ ‏مِنْ الْعَقْرَبِ قَالَ فَقُلْتُ نَعَمْ أَنَا وَلَكِنْ لَا أَفْعَلُ حَتَّى تُعْطُونَا شَيْئًا قَالُوا فَإِنَّا ‏ ‏نُعْطِيكُمْ ثَلَاثِينَ شَاةً قَالَ فَقَرَأْتُ عَلَيْهَا ‏ ‏الْحَمْدُ لِلَّهِ ‏ ‏سَبْعَ مَرَّاتٍ قَالَ ‏ ‏فَبَرَأَ ‏ ‏قَالَ فَلَمَّا قَبَضْنَا الْغَنَمَ قَالَ ‏ ‏عَرَضَ ‏ ‏فِي أَنْفُسِنَا مِنْهَا قَالَ فَكَفَفْنَا حَتَّى أَتَيْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَذَكَرْنَا ذَلِكَ لَهُ قَالَ فَقَالَ ‏ ‏أَمَا عَلِمْتَ أَنَّهَا ‏ ‏رُقْيَةٌ ‏ ‏اقْسِمُوهَا وَاضْرِبُوا لِي مَعَكُمْ ‏ ‏بِسَهْمٍ ‏","","",""],[10649,10649,"","বাবার সুখী কৌশলের জন্য আমার বাবার লড়াই সম্পর্কে আমরা কথা বলেছিলাম, ঈশ্বর ঈশ্বরের কাছে প্রার্থনা করলেন, তিনি জানতেন এবং ঘোড়ার কাছে আত্মসমর্পণ করতেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى حَصِيرٍ ‏","","",""],[10650,10650,"","বাবার সুখী কৌশলের জন্য আমার বাবার লড়াই সম্পর্কে আমরা কথা বলেছিলাম, ঈশ্বর তার কাছে প্রার্থনা করলেন এবং একদিন তার প্রাণ সমর্পণ করলেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ثَوْبٍ وَاحِدٍ وَاضِعًا طَرَفَيْهِ عَلَى ‏ ‏عَاتِقَيْهِ ‏","","",""],[10651,10651,"","আমরা তার বাবার সঙ্গে কথা বলেছিলাম এবং আমরা তার বাবা ও বাবার কথা শুনতে চাই । সে প্রার্থনা করার আগে সে এমন কাউকে খুন করতে শুরু করবে যে তোমাকে মেরে ফেলবে। তিনি বলেছিলেন, বাবা খুশি ছিলেন অথবা তিনি হয়তো যা কিছু করেছেন, তা শুনেছিলেন এবং আপনার কাছ থেকে যা কিছু শুনেছিলেন, তা শুনেছিলেননি । তাই আমি সঠিক ভাবে করছি","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ رَجَاءٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَعَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏أَخْرَجَ ‏ ‏مَرْوَانُ ‏ ‏الْمِنْبَرَ فِي يَوْمِ عِيدٍ وَلَمْ يَكُنْ يُخْرَجُ بِهِ وَبَدَأَ بِالْخُطْبَةِ قَبْلَ الصَّلَاةِ وَلَمْ يَكُنْ يُبْدَأُ بِهَا قَالَ فَقَامَ رَجُلٍ فَقَالَ يَا ‏ ‏مَرْوَانُ ‏ ‏خَالَفْتَ السُّنَّةَ أَخْرَجْتَ الْمِنْبَرَ يَوْمَ عِيدٍ وَلَمْ يَكُنْ يُخْرَجُ بِهِ فِي يَوْمِ عِيدٍ وَبَدَأْتَ بِالْخُطْبَةِ قَبْلَ الصَّلَاةِ وَلَمْ يَكُنْ يُبْدَأُ بِهَا قَالَ فَقَالَ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏مَنْ هَذَا قَالُوا فُلَانُ بْنُ فُلَانٍ قَالَ فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَمَّا هَذَا فَقَدْ قَضَى مَا عَلَيْهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَإِنْ اسْتَطَاعَ أَنْ يُغَيِّرَهُ بِيَدِهِ فَلْيَفْعَلْ ‏ ‏وَقَالَ مَرَّةً فَلْيُغَيِّرْهُ بِيَدِهِ ‏ ‏فَإِنْ لَمْ يَسْتَطِعْ بِيَدِهِ فَبِلِسَانِهِ فَإِنْ لَمْ يَسْتَطِعْ بِلِسَانِهِ فَبِقَلْبِهِ وَذَلِكَ أَضْعَفُ الْإِيمَانِ ‏","","",""],[10652,10652,"","আমি ঈশ্বরের মঙ্গলভাবের কথা বলেছিলাম যখন আমার গ্রীষ্মের দাস জন্ম নেয়, সে বলল ঈশ্বর তার জন্য প্রার্থনা করেন এবং তিনি আত্মসমর্পণ করবেন যে এমনকি তার পালকও দেবতাদের ক্ষমা করবে। আমি তিন বার চেষ্টা করছি, আর এটা অনেকটা মাখন আর অদ্ভুত.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ الْوَلِيدِ الْوَصَّافِيُّ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ حِينَ يَأْوِي إِلَى فِرَاشِهِ ‏ ‏أَسْتَغْفِرُ اللَّهَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ ثَلَاثَ مَرَّاتٍ غَفَرَ اللَّهُ لَهُ ذُنُوبَهُ وَإِنْ كَانَتْ مِثْلَ ‏ ‏زَبَدِ ‏ ‏الْبَحْرِ وَإِنْ كَانَتْ مِثْلَ رَمْلٍ عَالِجٍ وَإِنْ كَانَتْ مِثْلَ عَدَدِ وَرَقِ الشَّجَرِ ‏","","",""],[10653,10653,"","বাবা আমার সাথে যেতে চেষ্টা করে, আমার বাবা খুশি হয়েছে। ঈশ্বর এটা করেছেন এবং তিনি আপনাকে এই যেতে এবং তার ইচ্ছার ভ্রান্ত আদেশ দিয়েছেন যে তিনি কি আর তুমি ভবিষ্যদ্বাণীর মাধ্যমে প্রার্থনা করবে, প্রার্থনা করবে আর বলবে এটা করা হয়েছে। এটাই ভালো হবে। আদেশটা ছেড়ে দিয়ে তিনি বলেছিলেন, \"সে বলল, \"আব্বা তার অত্যাচারের ষড়যন্ত্রের মাধ্যমে যেতে পেরে খুশি হবেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَبِي سَعِيدٍ ‏ ‏أَسَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الذَّهَبِ بِالذَّهَبِ وَالْفِضَّةِ بِالْفِضَّةِ قَالَ سَأُخْبِرُكُمْ مَا سَمِعْتُ مِنْهُ جَاءَهُ ‏ ‏صَاحِبُ تَمْرِهِ ‏ ‏بِتَمْرٍ طَيِّبٍ وَكَانَ تَمْرُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَالُ لَهُ اللَّوْنُ قَالَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَيْنَ لَكَ هَذَا التَّمْرُ الطَّيِّبُ قَالَ ‏ ‏ذَهَبْتُ ‏ ‏بِصَاعَيْنِ ‏ ‏مِنْ تَمْرِنَا وَاشْتَرَيْتُ بِهِ ‏ ‏صَاعًا ‏ ‏مِنْ هَذَا قَالَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَيْتَ ‏ ‏قَالَ ‏ ‏ثُمَّ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَالتَّمْرُ بِالتَّمْرِ ‏ ‏أَرْبَى ‏ ‏أَمْ الْفِضَّةُ بِالْفِضَّةِ وَالذَّهَبُ بِالذَّهَبِ ‏","","",""],[10654,10654,"","আমি বাবার সঙ্গে কথা বলেছিলাম যে, আমার বাবা তোমার জীবনে সুখী হয়ে উঠেছিলেন । তারপর আমার ছেলের দশ টার দিকে, সে বিল্ডিং দিয়ে যায়, তারপর সে আবার ঘুমিয়ে পড়ে, সবাই বলবে আমি চলে গেলে, আমি বলবো ৯: ০০ টার সময়। আমি বললাম, আমি বলেছিলাম, আমার ছেলের ছেলের কাছে তার একটা ছোট বাবু। তারপর সে ঘুমের ওষুধটা রেখে চলে যায়। তারপর সে আবার চলে যায়। তারপর সে ঘুম থেকে উঠে। তারপর সে বলে দেবে, আমি বলবো, আমি বললাম, আমি তোমার কাছে যাচ্ছি। আর ৭:০০। আমি কি করবো? বাবা, আমি দুঃখিত, আর সাত বছর বয়সী বাবা, তুমি দশটার একটা ফোন করবে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏اعْتَكَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَشْرَ الْأَوْسَطَ مِنْ رَمَضَانَ وَهُوَ يَلْتَمِسُ لَيْلَةَ الْقَدْرِ قَبْلَ أَنْ تُبَانَ لَهُ فَلَمَّا تَقَضَّيْنَ أَمَرَ بِبُنْيَانِهِ فَنُقِضَ ثُمَّ أُبِينَتْ لَهُ أَنَّهَا فِي الْعَشْرِ الْأَوَاخِرِ فَأَمَرَ بِالْبِنَاءِ فَأُعِيدَ ثُمَّ اعْتَكَفَ الْعَشْرَ الْأَوَاخِرَ ثُمَّ خَرَجَ عَلَى النَّاسِ فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنَّهَا أُبِينَتْ لِي لَيْلَةُ الْقَدْرِ فَخَرَجْتُ لِأُخْبِرَكُمْ بِهَا فَجَاءَ رَجُلَانِ يَحِيفَانِ مَعَهُمَا الشَّيْطَانُ فَنُسِّيتُهَا فَالْتَمِسُوهَا فِي التَّاسِعَةِ وَالسَّابِعَةِ وَالْخَامِسَةِ ‏ ‏فَقُلْتُ ‏ ‏يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏إِنَّكُمْ أَعْلَمُ بِالْعَدَدِ مِنَّا قَالَ ‏ ‏أَنَا أَحَقُّ بِذَاكَ مِنْكُمْ فَمَا التَّاسِعَةُ وَالسَّابِعَةُ وَالْخَامِسَةُ قَالَ تَدَعُ الَّتِي تَدْعُونَ إِحْدَى وَعِشْرِينَ وَالَّتِي تَلِيهَا التَّاسِعَةُ وَتَدَعُ الَّتِي ‏ ‏تَدْعُونَ ثَلَاثَةً وَعِشْرِينَ وَالَّتِي تَلِيهَا السَّابِعَةُ وَتَدَعُ الَّتِي تَدْعُونَ خَمْسَةً وَعِشْرِينَ وَالَّتِي تَلِيهَا الْخَامِسَةُ ‏","","",""],[10655,10655,"","আমরা কথা বলেছি আমার বাবার এই আনন্দকে বাড়িয়ে বেনকে সাহায্য করার জন্য, ঈশ্বর আত্মসমর্পণ করতে হবে অথবা যারা উৎসর্গ করেছে আমি তাদের আমি আগুনে পুড়িয়ে দেবো যারা তার হাতে মারা যাবে না ( মথি ২৪: ১৪) একজন ব্যক্তি বলেছিলেন যে, অন্ধকার সম্বন্ধে একজন ব্যক্তি বলেছিলেন । ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا أَهْلُ النَّارِ الَّذِينَ هُمْ أَهْلُهَا فَإِنَّهُمْ لَا يَمُوتُونَ فِيهَا وَلَا يَحْيَوْنَ وَلَكِنْ نَاسٌ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏تُصِيبُهُمْ النَّارُ بِذُنُوبِهِمْ ‏ ‏أَوْ قَالَ بِخَطَايَاهُمْ ‏ ‏فَيُمِيتُهُمْ إِمَاتَةً حَتَّى إِذَا صَارُوا فَحْمًا ‏ ‏أَذِنَ ‏ ‏فِي ‏ ‏الشَّفَاعَةِ ‏ ‏فَجِيءَ بِهِمْ ‏ ‏ضَبَائِرَ ‏ ‏ضَبَائِرَ ‏ ‏ضَبَائِرَ ‏ ‏فَنَبَتُوا عَلَى أَنْهَارِ الْجَنَّةِ فَيُقَالُ يَا أَهْلَ الْجَنَّةِ ‏ ‏أَفِيضُوا ‏ ‏عَلَيْهِمْ فَيَنْبُتُونَ نَبَاتَ الْحِبَّةِ تَكُونُ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ قَالَ فَقَالَ رَجُلٌ مِنْ الْقَوْمِ حِينَئِذٍ كَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ كَانَ بِالْبَادِيَةِ ‏","","",""],[10656,10656,"","আমার বাবা চেয়েছিলেন যেন তুমি ঈশ্বর হও যে, তার প্রভু আছে । তার কাছ থেকে ও তাকে ঘৃণা করে আর মানুষ আকাশে যেতে হবে, যখন এটার মূল্য আছে, তখন তোমাকে যা করতে হবে তা করতে হবে না।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ بِشْرِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏فَرَدَّ الْحَدِيثَ حَتَّى رَدَّهُ إِلَى ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏ذُكِرَ ذَلِكَ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ وَمَا ‏ ‏ذَاكُمْ قَالُوا الرَّجُلُ تَكُونُ لَهُ الْمَرْأَةُ تُرْضِعُ فَيُصِيبُ مِنْهَا وَيَكْرَهُ أَنْ تَحْمِلَ مِنْهُ وَالرَّجُلُ تَكُونُ لَهُ ‏ ‏الْجَارِيَةُ ‏ ‏فَيُصِيبُ مِنْهَا وَيَكْرَهُ أَنْ تَحْمِلَ مِنْهُ فَقَالَ ‏ ‏فَلَا عَلَيْكُمْ أَنْ تَفْعَلُوا ‏ ‏ذَاكُمْ فَإِنَّمَا هُوَ الْقَدَرُ ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏فَحَدَّثْتُ ‏ ‏بِهِ ‏ ‏الْحَسَنَ ‏ ‏فَقَالَ ‏ ‏فَلَا عَلَيْكُمْ لَكَأَنَّ هَذَا ‏ ‏زَجْرٌ ‏","","",""],[10657,10657,"","আমি আমার বাবার সাথে এই জাদুর জন্য যুদ্ধ করেছি বলে কথা বলেছি, আমাকে হার মানতে হবে, যেন সে ভুল করে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسُبُّوا أَصْحَابِي فَإِنَّ أَحَدَكُمْ لَوْ أَنْفَقَ مِثْلَ ‏ ‏أُحُدٍ ‏ ‏ذَهَبًا مَا بَلَغَ ‏ ‏مُدَّ ‏ ‏أَحَدِهِمْ وَلَا نَصِيفَهُ ‏","","",""],[10658,10658,"","আমি যখন আমার বাবাকে সাহায্য করার জন্য আমার বাবাকে সাহায্য করার অথবা আমার বাবাকে সাহায্য করার বিষয়ে বলেছিলাম, তখন কেন লোকেরা ভয় পেত যে, ঈশ্বর যদি আমরা মুক্ত হতাম, তাহলে আমরা একা থাকতাম না । তার জন্য প্রার্থনা করে, আর তারা যখন তা করবে, আমি তাদের আরও ভালো জয় করতে পারব, তারপর তাকে আশীর্বাদ করব। তাকে যদি জয় করতে হয় এবং পরিবর্তন করতে হয়, তা হলে তাকে অবশ্যই জয় করতে হবে । এমনকি আপনি তাদের চিনি খেতে এবং এমনকি যদি তারা এটা খেয়েও ফেলে, আমি এটা দেখাতে পারবো যে আমি ঈশ্বরের কাছে যাচ্ছি না, ঈশ্বরের কাছে কখনও ঈশ্বরের কাছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَوْ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏شَكَّ ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ غَزْوَةُ ‏ ‏تَبُوكَ ‏ ‏أَصَابَ النَّاسَ مَجَاعَةٌ فَقَالُوا يَا رَسُولَ اللَّهِ لَوْ أَذِنْتَ لَنَا ‏ ‏فَنَحَرْنَا ‏ ‏نَوَاضِحَنَا ‏ ‏فَأَكَلْنَا وَادَّهَنَّا فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏افْعَلُوا فَجَاءَ ‏ ‏عُمَرُ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّهُمْ إِنْ فَعَلُوا قَلَّ الظَّهْرُ وَلَكِنْ ادْعُهُمْ بِفَضْلِ ‏ ‏أَزْوَادِهِمْ ‏ ‏ثُمَّ ادْعُ لَهُمْ عَلَيْهِ بِالْبَرَكَةِ لَعَلَّ اللَّهَ أَنْ يَجْعَلَ فِي ذَلِكَ فَدَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنِطَعٍ ‏ ‏فَبَسَطَهُ ثُمَّ دَعَاهُمْ بِفَضْلِ ‏ ‏أَزْوَادِهِمْ ‏ ‏فَجَعَلَ الرَّجُلُ يَجِيءُ بِكَفِّ الذُّرَةِ وَالْآخَرُ بِكَفِّ التَّمْرِ وَالْآخَرُ بِالْكِسْرَةِ حَتَّى اجْتَمَعَ عَلَى ‏ ‏النِّطْعِ ‏ ‏مِنْ ذَلِكَ شَيْءٌ يَسِيرٌ ثُمَّ دَعَا عَلَيْهِ بِالْبَرَكَةِ ثُمَّ قَالَ لَهُمْ خُذُوا فِي أَوْعِيَتِكُمْ قَالَ فَأَخَذُوا فِي أَوْعِيَتِهِمْ حَتَّى مَا تَرَكُوا مِنْ الْعَسْكَرِ وِعَاءً إِلَّا مَلَئُوهُ وَأَكَلُوا حَتَّى شَبِعُوا وَفَضَلَتْ مِنْهُ فَضْلَةٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ لَا يَلْقَى اللَّهَ بِهَا عَبْدٌ غَيْرُ شَاكٍّ فَتُحْجَبَ عَنْهُ الْجَنَّةُ ‏","","",""],[10659,10659,"","আমি আমার বাবাকে খুশি করতে চাই, যে আমার বাবাকে খুশি করতে চায়। ভালো প্রভু ভাল এবং ভালো। শিকার তাদের উদ্দেশ্য দেখাচ্ছে, তাদের সুখবোধ আছে, আর মানুষের মন এক মহান জীবন দ্বারা চিহ্নিত। তারা তাদের প্রার্থনা করে এবং তারা নিজেদের হাতে নিজেদের হাতে থাকবে । রাজা পরাজিত হবে, আমাদের কাছে ঋণী হয়ে প্রার্থনা করবে... ...আমাদের প্রার্থনা শেষ হবে... ...আর পরাজিত হবে, সেই অগ্নি আপনি বুঝতে পেরেছেন কে নিয়ে গেছে। তার পা অর্ধেক আর যে তাকে নিয়ে গেছে সে তাকে নিয়ে গেছে তারপর প্রতারণা করবে না। জীবন ওয়াশিং বলছে সূর্য থেকে ধোয়া কতটা পাগলামি। তিনি তার হৃদয়ের গভীরে তার ভালবাসাকে কখনো না পেয়েই ছেড়ে দিয়েছিলেন তার থেকে বের হও.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ الْمُغِيرَةِ بْنِ مُعَيْقِيبٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَمْرِو بْنِ عَبْدٍ الْعُتْوَارِيِّ ‏ ‏أَحَدُ ‏ ‏بَنِي لَيْثٍ ‏ ‏وَكَانَ يَتِيمًا فِي حِجْرِ ‏ ‏أَبِي سَعِيدٍ ‏ ‏سُلَيْمَانَ بْنِ عُمَرَ وَهُوَ أَبُو الْهَيْثَمِ ‏ ‏الَّذِي يَرْوِي عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يُوضَعُ الصِّرَاطُ بَيْنَ ظَهْرَيْ جَهَنَّمَ عَلَيْهِ ‏ ‏حَسَكٌ ‏ ‏كَحَسَكِ ‏ ‏السَّعْدَانِ ‏ ‏ثُمَّ ‏ ‏يَسْتَجِيزُ ‏ ‏النَّاسُ فَنَاجٍ مُسَلَّمٌ ‏ ‏وَمَجْدُوحٌ ‏ ‏بِهِ ثُمَّ نَاجٍ وَمُحْتَبِسٌ بِهِ مَنْكُوسٌ فِيهَا فَإِذَا فَرَغَ اللَّهُ عَزَّ وَجَلَّ مِنْ الْقَضَاءِ بَيْنَ الْعِبَادِ يَفْقِدُ الْمُؤْمِنُونَ رِجَالًا كَانُوا مَعَهُمْ فِي الدُّنْيَا يُصَلُّونَ بِصَلَاتِهِمْ وَيُزَكُّونَ بِزَكَاتِهِمْ وَيَصُومُونَ صِيَامَهُمْ وَيَحُجُّونَ حَجَّهُمْ وَيَغْزُونَ غَزْوَهُمْ فَيَقُولُونَ أَيْ رَبَّنَا عِبَادٌ مِنْ عِبَادِكَ كَانُوا مَعَنَا فِي الدُّنْيَا يُصَلُّونَ صَلَاتَنَا وَيُزَكُّونَ زَكَاتَنَا وَيَصُومُونَ صِيَامَنَا وَيَحُجُّونَ حَجَّنَا وَيَغْزُونَ غَزْوَنَا لَا ‏ ‏نَرَاهُمْ فَيَقُولُ ‏ ‏اذْهَبُوا إِلَى النَّارِ فَمَنْ وَجَدْتُمْ فِيهَا مِنْهُمْ فَأَخْرِجُوهُ قَالَ فَيَجِدُونَهُمْ قَدْ أَخَذَتْهُمْ النَّارُ عَلَى قَدْرِ أَعْمَالِهِمْ فَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى قَدَمَيْهِ وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى نِصْفِ سَاقَيْهِ وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى رُكْبَتَيْهِ وَمِنْهُمْ مَنْ ‏ ‏أَزِرَتْهُ ‏ ‏وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى ثَدْيَيْهِ وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى عُنُقِهِ وَلَمْ تَغْشَ الْوُجُوهَ فَيَسْتَخْرِجُونَهُمْ مِنْهَا فَيُطْرَحُونَ فِي مَاءِ الْحَيَاةِ قِيلَ يَا رَسُولَ اللَّهِ وَمَا مَاءُ الْحَيَاةِ قَالَ غُسْلُ أَهْلِ الْجَنَّةِ فَيَنْبُتُونَ نَبَاتَ ‏ ‏الزَّرْعَةِ ‏ ‏وَقَالَ مَرَّةً فِيهِ كَمَا تَنْبُتُ الزَّرْعَةُ فِي ‏ ‏غُثَاءِ ‏ ‏السَّيْلِ ‏ ‏ثُمَّ يَشْفَعُ الْأَنْبِيَاءُ فِي كُلِّ مَنْ كَانَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ مُخْلِصًا فَيُخْرِجُونَهُمْ مِنْهَا قَالَ ثُمَّ يَتَحَنَّنُ اللَّهُ بِرَحْمَتِهِ عَلَى مَنْ فِيهَا فَمَا يَتْرُكُ فِيهَا عَبْدًا فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ إِيمَانٍ إِلَّا أَخْرَجَهُ مِنْهَا ‏","","",""],[10660,10660,"","আমি যেভাবে প্রার্থনা করি, তা আপনাকে দুটো পুরুষ খুঁজে বের করতে সাহায্য করবে । যদি আমি তোমার কাছে যেতাম, আমি বলবো তুমি মারা যাবে, হয় সে তার কান দিয়ে তার কণ্ঠ শুনতে পেয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏الدَّسْتُوَائِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيَاضٌ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَحَدُنَا ‏ ‏يُصَلِّي ‏ ‏فَلَا يَدْرِي ‏ ‏كَمْ صَلَّى فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فَلَمْ يَدْرِ كَمْ صَلَّى فَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ وَإِذَا جَاءَ أَحَدَكُمْ الشَّيْطَانُ فَقَالَ إِنَّكَ قَدْ ‏ ‏أَحْدَثْتَ ‏ ‏فَلْيَقُلْ كَذَبْتَ إِلَّا مَا وَجَدَ رِيحَهُ بِأَنْفِهِ أَوْ سَمِعَ صَوْتَهُ بِأُذُنِهِ ‏","","",""],[10661,10661,"","ঈশ্বর তাকে আদেশ দিয়েছেন এবং আমরা বধির লোকেদের আত্মসমর্পণ করে ফেলেছি । ভালো যে খুজে পেয়েছে... ...সে শুধু হারিয়ে গেছে","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا نَغْزُو مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمِنَّا الصَّائِمُ وَمِنَّا الْمُفْطِرُ فَلَا ‏ ‏يَجِدُ ‏ ‏الصَّائِمُ عَلَى الْمُفْطِرِ وَلَا الْمُفْطِرُ عَلَى الصَّائِمِ ‏ ‏يَرَوْنَ أَنَّهُ ‏ ‏يَعْنِي مَنْ وَجَدَ قُوَّةً فَصَامَ فَإِنَّ ذَلِكَ حَسَنٌ وَيَرَوْنَ أَنَّهُ مَنْ وَجَدَ ضَعْفًا فَأَفْطَرَ فَإِنَّ ذَلِكَ حَسَنٌ ‏","","",""],[10662,10662,"","আমরা বাবার সাথে কথা বলেছি যে আমরা আর কাজে যাই না। এটাই সেই গল্প যা আমাদের প্রভুকে খুঁজতে হবে। ঈশ্বর যে এই গাছ খেয়েছে, সে-ই হয়েছে। আমি যা করার চেষ্টা করছি, সে যেন না হয়, সে আমাকে মুক্ত না করে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏لَمْ نَعُدْ أَنْ فُتِحَتْ ‏ ‏خَيْبَرُ ‏ ‏وَقَعْنَا فِي تِلْكَ ‏ ‏الْبَقْلَةِ ‏ ‏فَأَكَلْنَا مِنْهَا أَكْلًا شَدِيدًا وَنَاسٌ جِيَاعٌ ثُمَّ رَحَلْنَا إِلَى الْمَسْجِدِ فَوَجَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرِّيحَ فَقَالَ مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ الْخَبِيثَةِ شَيْئًا فَلَا يَقْرَبْنَا فِي الْمَسْجِدِ فَقَالَ النَّاسُ حُرِّمَتْ حُرِّمَتْ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَيُّهَا النَّاسُ ‏ ‏إِنَّهُ لَيْسَ لِي تَحْرِيمُ مَا أَحَلَّ اللَّهُ وَلَكِنَّهَا شَجَرَةٌ أَكْرَهُ رِيحَهَا ‏","","",""],[10663,10663,"","আমরা আমাকে কঠিন সময়ের কথা বলেছি, ঈশ্বর তাকে এটা করতে বলেছেন আর আমাকে আত্মসমর্পণ করবেন না যা লেখা আর লিখতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَكْتُبُوا عَنِّي شَيْئًا سِوَى الْقُرْآنِ وَمَنْ كَتَبَ شَيْئًا سِوَى الْقُرْآنِ فَلْيَمْحُهُ ‏","","",""],[10664,10664,"","আমরা আমার বাবার সাথে কথা বলেছিলাম যে কথা বলার জন্য বাবার খ্যাতি নিয়ে... ...ঈশ্বর তার জন্য প্রার্থনা করেছিলেন আর জাদুর জন্য তার আশীর্বাদও থাকবে. ( লূক ১১: ১৩) তাঁর সমস্ত দূতই এই চমৎকার ব্যক্তিদের জন্য প্রার্থনা করছে ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏هِشَامٍ الدَّسْتُوَائِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي رِفَاعَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّحُورُ أَكْلُهُ بَرَكَةٌ فَلَا تَدَعُوهُ وَلَوْ أَنْ يَجْرَعَ أَحَدُكُمْ جُرْعَةً مِنْ مَاءٍ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الْمُتَسَحِّرِينَ ‏","","",""],[10665,10665,"","আমরা যুদ্ধের কথা বলেছিলাম, আমরা একটা যুদ্ধ সম্পর্কে বলেছিলাম যেটা ভালো হাত দেবে। সে বলল ঈশ্বর তাকে জানতেন আর সে আমাকে নিয়ে কিছু লিখতে পারতো না।","‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ حَرْبٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَكْتُبُوا عَنِّي شَيْئًا فَمَنْ كَتَبَ عَنِّي شَيْئًا فَلْيَمْحُهُ ‏","","",""],[10666,10666,"","আমরা আমার সহকর্মীর সাথে কথা বলেছি যে, আমি তাকে একটা প্রশ্ন জিজ্ঞাসা করতাম যে সে সুখী হতে পারে। জাবের আমরা আপনাকে ঘৃণা করতাম।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الرَّجُلِ يَشْرَبُ وَهُوَ قَائِمٌ قَالَ ‏ ‏جَابِرٌ ‏ ‏كُنَّا نَكْرَهُ ذَلِكَ ‏","","",""],[10667,10667,"","আমরা বলেছিলাম যে, আমার বাবার ভালো ছেলের ব্যাপারে ভালো করার জন্য আমরা একটা ছেলেকে বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَشْهَدُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَجَرَ ‏ ‏عَنْ ذَاكَ ‏ ‏وَزَجَرَ ‏ ‏أَنْ نَسْتَقْبِلَ الْقِبْلَةَ لِبَوْلٍ ‏","","",""],[10668,10668,"","আমরা ঈশ্বরের পুত্র দ্বারা আবদ্ধ হওয়ার চেষ্টা করেছি, যে কিনা আমাদের সাথে এক ছেলে হিসেবে কথা বলেছে, যে কিনা সন্তান ধারণ করে খুশি হবে। সুখী অথবা তুমি ঈশ্বরকে জিজ্ঞেস করতে জানতো যে, তিনি মারা যাওয়ার আগে ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏فَتَحَ ‏ ‏خَوْخَةً ‏ ‏لَهُ وَعِنْدَهُ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏فَخَرَجَتْ عَلَيْهِمْ حَيَّةٌ فَأَمَرَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏بِقَتْلِهَا فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَمَا عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ أَنْ يُؤْذِنَهُنَّ قَبْلَ أَنْ يَقْتُلَهُنَّ ‏","","",""],[10669,10669,"","আমরা যুদ্ধ করার চেষ্টা করেছি ভালো হাত দেয়ার চেয়ে। আমি শুনেছি ভগবানের কাছে প্রার্থনা করার জন্য। সে বলবে, কে সেই প্রতারনা, সে পচ, খোদা, এবং আমি তা খুঁজে বের করেছি। তুমি ধৈর্য থেকে বড় হয়ে পড়.","‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ يَتَصَبَّرْ يُصَبِّرْهُ اللَّهُ وَمَنْ يَسْتَغْنِ يُغْنِهِ اللَّهُ وَمَنْ يَسْتَعْفِفْ يُعِفَّهُ اللَّهُ وَمَا أَجِدُ لَكُمْ رِزْقًا أَوْسَعَ مِنْ الصَّبْرِ ‏","","",""],[10670,10670,"","আমি বাবার শোক থেকে বেঁচে থাকা এক ছেলেকে চুরি করার চেষ্টা করছি, আমরা ভবিষ্যদ্বাণীর মাধ্যমে যা শুনেছি, ঈশ্বর আমাদের বাইরে নিয়ে যান এবং আমাদের যেতে দেন। ঈশ্বরের বই আমরা বলেছি, আমরা লর্ডের অনুপস্থিত হিসেবে গুনবো, ঈশ্বরের বই বা তার গোপন কথা কখনো কখনো লিখতে পারবো না। লজ্জা পেয়ে আমাকে বলতে যে কে ছিল, আমি তোমাকে অনুরোধ করছি আমার সম্পর্কে কথা বলতে, যখন তুমি লজ্জা পেতে।","‏ ‏حَدَّثَنِي ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنَّا قُعُودًا نَكْتُبُ مَا نَسْمَعُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجَ عَلَيْنَا فَقَالَ مَا هَذَا تَكْتُبُونَ فَقُلْنَا مَا نَسْمَعُ مِنْكَ فَقَالَ أَكِتَابٌ مَعَ كِتَابِ اللَّهِ فَقُلْنَا مَا نَسْمَعُ فَقَالَ اكْتُبُوا كِتَابَ اللَّهِ ‏ ‏أَمْحِضُوا ‏ ‏كِتَابَ اللَّهِ أَكِتَابٌ غَيْرُ كِتَابِ اللَّهِ ‏ ‏أَمْحِضُوا ‏ ‏كِتَابَ اللَّهِ ‏ ‏أَوْ خَلِّصُوهُ ‏ ‏قَالَ فَجَمَعْنَا مَا كَتَبْنَا فِي ‏ ‏صَعِيدٍ ‏ ‏وَاحِدٍ ثُمَّ أَحْرَقْنَاهُ بِالنَّارِ قُلْنَا أَيْ رَسُولَ اللَّهِ أَنَتَحَدَّثُ عَنْكَ قَالَ نَعَمْ ‏ ‏تَحَدَّثُوا عَنِّي وَلَا حَرَجَ وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ قَالَ فَقُلْنَا يَا رَسُولَ اللَّهِ أَنَتَحَدَّثُ عَنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏قَالَ نَعَمْ تَحَدَّثُوا عَنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏وَلَا حَرَجَ فَإِنَّكُمْ لَا تَحَدَّثُوا عَنْهُمْ بِشَيْءٍ إِلَّا وَقَدْ كَانَ فِيهِمْ أَعْجَبَ مِنْهُ ‏","","",""],[10671,10671,"","আমরা আমার বাবাকে খুন করার ব্যাপারে কথা বলেছি, তাকে এটা জানার জন্য বন্ধ করা হয়েছে আর সে তার হাত তার নিজের সময় যোগ করেছে আর এটা কাজ করে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏بِشْرِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاقِفًا ‏ ‏بِعَرَفَةَ ‏ ‏يَدْعُو هَكَذَا وَرَفَعَ يَدَيْهِ حِيَالَ ‏ ‏ثَنْدُوَتَيْهِ ‏ ‏وَجَعَلَ بُطُونَ كَفَّيْهِ مِمَّا ‏ ‏يَلِي ‏ ‏الْأَرْضَ ‏","","",""],[10672,10672,"","আমরা একটা পিপপির ছেলেের কথা বলেছিলাম... ...যে ঈশ্বরের হাতে যেতে বলেছিল, আমি তার জন্য প্রার্থনা করছি, আর আমি তাকে আমার জন্য সবচেয়ে সেরাটা দেব।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏اشْتِمَالِ ‏ ‏الصَّمَّاءِ ‏ ‏وَأَنْ ‏ ‏يَحْتَبِيَ ‏ ‏الرَّجُلُ فِي ثَوْبٍ وَاحِدٍ لَيْسَ عَلَى فَرْجِهِ مِنْهُ شَيْءٌ ‏","","",""],[10673,10673,"","আমি আমার বাবাকে মদ খেতে সাহায্য করার চেষ্টা করেছিলাম । ছায়া নেওয়ার অধিকার ছিল, আমি তাদের হুমকি দিচ্ছি তার বাড়ির ঠিকানা হাতে নিয়ে শহরে নিয়ে আসার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْلُصُ الْمُؤْمِنُونَ يَوْمَ الْقِيَامَةِ مِنْ النَّارِ فَيُحْبَسُونَ عَلَى قَنْطَرَةٍ بَيْنَ الْجَنَّةِ وَالنَّارِ ‏ ‏فَيُقْتَصُّ ‏ ‏لِبَعْضِهِمْ مِنْ بَعْضٍ مَظَالِمُ كَانَتْ بَيْنَهُمْ فِي الدُّنْيَا حَتَّى إِذَا هُذِّبُوا وَنُقُّوا أُذِنَ لَهُمْ فِي دُخُولِ الْجَنَّةِ فَوَالَّذِي نَفْسِي بِيَدِهِ لَأَحَدُهُمْ ‏ ‏أَهْدَى ‏ ‏لِمَنْزِلِهِ فِي الْجَنَّةِ مِنْهُ بِمَنْزِلِهِ كَانَ فِي الدُّنْيَا ‏","","",""],[10674,10674,"","আমরা যখন আমাদের সাক্ষাৎ হয়েছিল, তখন আমরা যখন কথা বলার চেষ্টা করছিলাম, তখন আমরা এক দুর্বল ছেলের কথা বলেছিলাম । সে খুন হয়, তারপর সকালে তাকে অর্ধেক খরচ করতে বলা হয়, তারপর সে বলে তুমি যা বলেছ, তুমি যা বলেছ, তা তোমার ভয় তাকে ক্ষমা করে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏فِرَاسُ بْنُ يَحْيَى الْهَمْدَانِيُّ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَقَدْ دَخَلَ رَجُلٌ الْجَنَّةَ مَا عَمِلَ خَيْرًا قَطُّ قَالَ لِأَهْلِهِ حِينَ حَضَرَهُ الْمَوْتُ إِذَا أَنَا مِتُّ فَأَحْرِقُونِي ثُمَّ اسْحَقُونِي ثُمَّ ‏ ‏اذْرُوا ‏ ‏نِصْفِي فِي الْبَحْرِ وَنِصْفِي فِي الْبَرِّ فَأَمَرَ اللَّهُ الْبَرَّ وَالْبَحْرَ فَجَمَعَاهُ ثُمَّ قَالَ ‏ ‏مَا حَمَلَكَ عَلَى مَا صَنَعْتَ قَالَ مَخَافَتُكَ قَالَ فَغَفَرَ لَهُ بِذَلِكَ ‏","","",""],[10675,10675,"","আমি তাকে বলি যে আমি ঈশ্বরের কাছে প্রার্থনা করব যেন তিনি তার কাজ সম্পর্কে বলার জন্য তার মুক্তির কথা বলতে পারেন. তিনি তার বাবার জন্য প্রার্থনা করেছিলেন এবং সেই আগুনের মধ্যে দিয়ে যাওয়ার জন্য তিনি সেই অগ্নির পাত্রগুলো দিয়েছিলেন, যাতে তিনি সেই ঘটনার কথা উল্লেখ করেছিলেন । অনুষ্ঠান।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ الْعَوْفِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏أَخْبَرَهُ قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْوَتْرِ ‏ ‏فَقَالَ ‏ ‏أَوْتِرُوا ‏ ‏قَبْلَ الصُّبْحِ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏فِي تَفْسِيرِ ‏ ‏شَيْبَانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْمُتَوَكِّلِ النَّاجِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْلُصُ الْمُؤْمِنُونَ مِنْ النَّارِ فَذَكَرَ الْحَدِيثَ ‏","","",""],[10676,10676,"","আমরা সবাই ঈশ্বরের বাপ্তিস্মের জন্য কৃতজ্ঞ। আমার বাবা তার কাছে প্রার্থনা করতে এবং তাঁর জীবন ফিরিয়ে দিতে পেরে খুশি। যে সমস্ত লোক বলে যে, দেবতাদের উন্মাদনা এবং অন্ধকারের আলো, তাদের মধ্যে দিয়ে তুমি আমার পাপের জন্য লড়াই করছ, আমি যা বলি তা হল আমার জীবন। সে যদি গুলি করে, সে বলবে \"সে কি তাকে কিছু বলবে?\" আপনার আশীর্বাদ তাকে সামনে রাখবে, সে বলবে আমার শাসন আর মা পাগলের মত। সৃষ্টি.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ افْتَخَرَتْ الْجَنَّةُ وَالنَّارُ فَقَالَتْ النَّارُ يَا رَبِّ يَدْخُلُنِي الْجَبَابِرَةُ وَالْمُتَكَبِّرُونَ وَالْمُلُوكُ وَالْأَشْرَافُ وَقَالَتْ الْجَنَّةُ أَيْ رَبِّ يَدْخُلُنِي الضُّعَفَاءُ وَالْفُقَرَاءُ وَالْمَسَاكِينُ فَيَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى لِلنَّارِ ‏ ‏أَنْتِ عَذَابِي أُصِيبُ بِكِ مَنْ أَشَاءُ وَقَالَ لِلْجَنَّةِ أَنْتِ رَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ وَلِكُلِّ وَاحِدَةٍ مِنْكُمَا مِلْؤُهَا ‏ ‏فَيُلْقَى فِي النَّارِ أَهْلُهَا فَتَقُولُ هَلْ مِنْ مَزِيدٍ قَالَ وَيُلْقَى فِيهَا وَتَقُولُ هَلْ مِنْ مَزِيدٍ وَيُلْقَى فِيهَا وَتَقُولُ هَلْ مِنْ مَزِيدٍ حَتَّى يَأْتِيَهَا تَبَارَكَ وَتَعَالَى فَيَضَعَ قَدَمَهُ عَلَيْهَا ‏ ‏فَتُزْوَى ‏ ‏فَتَقُولُ ‏ ‏قَدْنِي ‏ ‏قَدْنِي ‏ ‏وَأَمَّا الْجَنَّةُ فَيَبْقَى فِيهَا أَهْلُهَا مَا شَاءَ اللَّهُ أَنْ يَبْقَى فَيُنْشِئُ اللَّهُ لَهَا خَلْقًا مَا يَشَاءُ ‏","","",""],[10677,10677,"","আমরা সব বদলেছি, প্রতিবেশীকে সাহায্য করার চেয়ে আমার বাবার কাছে ফিরে আসা দ্বিগুণ খারাপ। ড্রাগটি বলেছে, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং ঈশ্বর তাকে উদ্ধার করবেন। তারা আগুনের সাথে খেলা করছে, চলে যাওয়ার প্রক্রিয়া নিয়ে, চলে যাওয়ার জন্য। আগুন উঠে যেতে হবে এবং তাকে হত্যা করতে হবে। অত্যাচার হয়তো চলে যেতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْوَنُ أَهْلِ النَّارِ عَذَابًا رَجُلٌ فِي رِجْلَيْهِ نَعْلَانِ يَغْلِي مِنْهُمَا دِمَاغُهُ وَمِنْهُمْ فِي النَّارِ إِلَى كَعْبَيْهِ مَعَ إِجْرَاءِ الْعَذَابِ وَمِنْهُمْ مَنْ فِي النَّارِ إِلَى رُكْبَتَيْهِ مَعَ إِجْرَاءِ الْعَذَابِ وَمِنْهُمْ مَنْ ‏ ‏اغْتُمِرَ ‏ ‏فِي النَّارِ إِلَى ‏ ‏أَرْنَبَتِهِ ‏ ‏مَعَ إِجْرَاءِ الْعَذَابِ وَمِنْهُمْ مَنْ هُوَ فِي النَّارِ إِلَى صَدْرِهِ مَعَ إِجْرَاءِ الْعَذَابِ وَمِنْهُمْ مَنْ قَدْ ‏ ‏اغْتُمِرَ ‏ ‏فِي النَّارِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏مَعَ إِجْرَاءِ الْعَذَابِ قَدْ ‏ ‏اغْتُمِرَ ‏","","",""],[10678,10678,"","আমি আমার প্রিয় বাবাকে হাত থেকে সাহায্য করার ব্যাপারে কথা বলেছি, আমি মনে করি সেই বৃদ্ধটিকে প্রভুর কাছে তুলে নিয়ে গেছে, যেমনটা তিনি আত্মসমর্পণ করেছেন অথবা এর মূল্য অনুসারে কাজ করেছেন। ক্যাম্পাস মরে যায়, আর লর্ডের নিরাপত্তা সুরক্ষিত থাকে, আমরা নগ্ন হয়ে ঈশ্বরের চেয়ে বেশি নিরাপদ।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏سَعْدٍ أَبِي الْمُجَاهِدِ الطَّائِيِّ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ بْنِ سَعْدٍ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أُرَاهُ قَدْ رَفَعَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا مُؤْمِنٍ سَقَى مُؤْمِنًا شَرْبَةً عَلَى ظَمَإٍ سَقَاهُ اللَّهُ يَوْمَ الْقِيَامَةِ مِنْ الرَّحِيقِ الْمَخْتُومِ ‏ ‏وَأَيُّمَا مُؤْمِنٍ أَطْعَمَ مُؤْمِنًا عَلَى جُوعٍ أَطْعَمَهُ اللَّهُ مِنْ ثِمَارِ الْجَنَّةِ وَأَيُّمَا مُؤْمِنٍ كَسَا مُؤْمِنًا ثَوْبًا عَلَى عُرْيٍ كَسَاهُ اللَّهُ مِنْ خُضْرِ الْجَنَّةِ ‏","","",""],[10679,10679,"","আমি আমার বাবার সাথে প্রেম করার কথা বলেছি। আমার বাবা, যিনি বলেছিলেন প্রভুর দয়া নিতে, তিনি আমার হাতে তাকে আশীর্বাদ করেছেন এবং বলেছেন, \"আমি তিন বার সুখী হব।\" প্রভু বলেছেন, তাঁরা কি, আল্লাহ ও খোদাকে দয়া করে, আর ভালটা হচ্ছে আকাশ কতটা অসুস্থ আর প্রভুর পথে দেখা যায়।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏أَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِي فَقَالَ يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏ثَلَاثَةٌ مَنْ قَالَهُنَّ دَخَلَ الْجَنَّةَ قُلْتُ مَا هُنَّ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏مَنْ رَضِيَ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏رَسُولًا ثُمَّ قَالَ يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏وَالرَّابِعَةُ لَهَا مِنْ الْفَضْلِ كَمَا بَيْنَ السَّمَاءِ إِلَى الْأَرْضِ وَهِيَ الْجِهَادُ فِي سَبِيلِ اللَّهِ ‏","","",""],[10680,10680,"","আমরা আমার বাবার এই খুশি কৌশল নিয়ে কথা বলেছি... ...সে বলেছে যে ঈশ্বর এটা দিয়েছেন আর তাকে সন্তুষ্ট করার জন্য যথেষ্ট করেছে.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏بِشْرِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَفَةَ ‏ ‏يَدْعُو هَكَذَا وَجَعَلَ بَاطِنَ كَفَّيْهِ مِمَّا ‏ ‏يَلِي ‏ ‏الْأَرْضَ ‏","","",""],[10681,10681,"","আমার বাবার সঙ্গে কথা বলেছিলাম, আমার বাবার কাছে প্রার্থনা করার চেষ্টা করছিল । যতক্ষণ না পর্যন্ত আমি হারাব ততক্ষণও হারবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو إِسْرَائِيلَ يَعْنِي إِسْمَاعِيلَ بْنَ أَبِي إِسْحَاقَ الْمُلَائِيَّ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي تَارِكٌ فِيكُمْ ‏ ‏الثَّقَلَيْنِ ‏ ‏أَحَدُهُمَا أَكْبَرُ مِنْ الْآخَرِ كِتَابُ اللَّهِ حَبْلٌ مَمْدُودٌ مِنْ السَّمَاءِ إِلَى الْأَرْضِ ‏ ‏وَعِتْرَتِي ‏ ‏أَهْلُ بَيْتِي وَإِنَّهُمَا لَنْ يَفْتَرِقَا حَتَّى يَرِدَا عَلَيَّ الْحَوْضَ ‏","","",""],[10682,10682,"","আমার বাবা একজন ভবিষ্যদ্বাণীকারী হওয়ার জন্য খুবই খুশি হয়েছিলেন আর আমি তাকে তার কাছে যেতে বলেছিলাম । সে বলল আমরা লেক থেকে এসেছি, ঈশ্বর তোমাকে কখনো তোমার ব্যবসা থেকে বের করে দেবেন না।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ الْفَزَارِيُّ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ عَنْ الْهِجْرَةِ فَقَالَ ‏ ‏وَيْحَكَ ‏ ‏إِنَّ الْهِجْرَةَ شَأْنُهَا شَدِيدٌ فَهَلْ لَكَ مِنْ إِبِلٍ قَالَ نَعَمْ قَالَ هَلْ تُؤَدِّي صَدَقَتَهَا قَالَ نَعَمْ قَالَ هَلْ ‏ ‏تَمْنَحُ ‏ ‏مِنْهَا قَالَ نَعَمْ قَالَ هَلْ تَحْلِبُهَا يَوْمَ ‏ ‏وِرْدِهَا ‏ ‏قَالَ نَعَمْ قَالَ فَاعْمَلْ مِنْ وَرَاءِ الْبِحَارِ فَإِنَّ اللَّهَ لَنْ يَتِرَكَ مِنْ عَمَلِكَ شَيْئًا ‏","","",""],[10683,10683,"","আমরা সবাই সিদ্ধান্ত নিয়েছি যে জয়ের চেয়ে আমরা ভালো কাজ করেছি। বাবা, ঈশ্বরকে তার আশীর্বাদ পাঠাতে পেরে খুশি। তাকে খুঁজে বের করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ قَرْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ يَعْنِي ابْنَ الْأَصْبَهَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَدَّمَ ثَلَاثَةً مِنْ وَلَدِهِ حَجَبُوهُ مِنْ النَّارِ ‏","","",""],[10684,10684,"","আমরা কিভাবে তৃষ্ণার সন্ধান করছিলাম, সেই লোক যে কিনা ঈশ্বরের কাছে প্রার্থনা করেছে তার দাসের জন্য প্রার্থনা করেছে আর দীর্ঘ মেয়াদে জেলে প্রবেশ করেনি, সে তার নামে। ভাল কাজ করেছ, কোন মানুষ নয়.","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سَعْدٍ الطَّائِيِّ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ صَاحِبُ خَمْسٍ مُدْمِنُ خَمْرٍ وَلَا مُؤْمِنٌ بِسِحْرٍ وَلَا قَاطِعُ ‏ ‏رَحِمٍ ‏ ‏وَلَا ‏ ‏كَاهِنٌ ‏ ‏وَلَا ‏ ‏مَنَّانٌ ‏","","",""],[10685,10685,"","আমি আল্লাহ্‌র সাথে কথা বলেছি আমি তোমাকে ভালো একটা নাম দিতে চাই। এই কৌশলটা হল আমার সাথে লড়াই করা। আমি ইশ্বরকে অনুরোধ করব তার আত্মসমর্পণের জন্য এবং আত্মসমর্পণের জন্য প্রার্থনা করতে। আমি আপনাকে একটি ভাল হাত দিতে পারি। আমি যদি আমার সাথে লড়াই করতে হয়, তাহলে আপনি কি করবেন? আমি আপনাকে কি করতে পারি? আমি কি আছে? আমি জানি না? আমি কি করব? আমি জানি না যে, আপনি আপনার জন্য প্রার্থনা করতে হবে? আপনি কি জানেন না? আপনি যদি আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি আপনার জন্য একটি ভাল কাজ করেন, আপনি কি করছেন? আপনি আপনার জন্য একটি ভাল উপায় আছে? আপনি কি? আপনি কি? আপনি কি? আপনি আপনার জন্য ধন্যবাদ দিতে চান না? আপনি যদি আপনি আপনার জন্য একটি ভাল উপায় আছে? আপনি কি? আপনি কি? আপনি আপনার জন্য একটি ভাল উপায় আছে? আপনি কি? আপনি আপনার জন্য একটি ভাল উপায় আছে? আপনি কি কি? আপনি আপনার জন্য একটি ভাল কাজ করতে পারেন? আত্মসমর্পণ করো, তুমি কি বলেছিলে আমরা বিশ্বাস করি নি, আর সে আমাকে বলেছিল সে নাকি লেক থেকে যা করেছে... ...যেটা তুমি ঈশ্বরের কাছে করতে চাও না...","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنِي ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ أَعْرَابِيًّا سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْهِجْرَةِ فَقَالَ ‏ ‏وَيْحَكَ ‏ ‏إِنَّ الْهِجْرَةَ شَأْنُهَا شَدِيدٌ فَهَلْ لَكَ مِنْ إِبِلٍ قَالَ نَعَمْ قَالَ أَلَسْتَ تُؤَدِّي صَدَقَتَهَا قَالَ بَلَى قَالَ أَلَسْتَ ‏ ‏تَمْنَحُ ‏ ‏مِنْهَا قَالَ بَلَى قَالَ أَلَسْتَ تَحْلُبُهَا يَوْمَ ‏ ‏وِرْدِهَا ‏ ‏قَالَ بَلَى قَالَ فَاعْمَلْ مِنْ وَرَاءِ الْبِحَارِ مَا شِئْتَ فَإِنَّ اللَّهَ لَنْ يَتِرَكَ مِنْ عَمَلِكَ شَيْئًا ‏","","",""],[10686,10686,"","আমরা কয়েকজন পরিচিতের ব্যাপারে কথা বলেছি, আমি কিভাবে কথা বলতে চাই সে সম্পর্কে কথা বলেছি। ঈশ্বরের আশা হল তিনি এমন একজন ভালো দাসের সাথে কথা বলেছেন যিনি কথা বলেছিলেন। যে কিনা কোথাও বের হয়েছে, তাকে ঈশ্বরের কাছে আত্মসমর্পণ করতে হবে এবং তাকে প্রভুর কাছে সমর্পণ করতে হবে। যদি সে কখনো তার সাথে কথা বলে, সে বলে, তোমাকে খুন করতে হবে। আর আমি তাকে একটা ঈশ্বর দেব। আর আমি তোমাকে বলি, আমি তোমাকে বলি, আমি যেন আমার জীবনের জন্য কিছু করতে পারি। আর আমি যদি তাকে বলি, আমি তোমার কাছে ক্ষমা চাই, আর আমি তোমার কাছে ক্ষমা চাই, আর আমি তোমার কাছে ক্ষমা চাই, আর আমি যেন আমার জীবনের জন্য এটা একটা জিনিস পাই। আর আমি তোমার কাছে এটা একটা জিনিস আছে। আর আমি জানি না যে তুমি জানো, তুমি যদি তুমি এটা তোমার কাছে আমার কথা বল, তুমি এটা একটা জিনিস নিয়ে নাও। আর তুমি জানো, আমি তোমার কাছে একটা জিনিস নিয়ে যেতে পার। আর আমি যদি তার কাছে ফিরে আসি, তাহলে আমি তোমার কাছে ফিরে আসি। আর আমি জানি যে তুমি এটা একটা জিনিসও দেব। আর আমি তোমার কাছে এটা একটা জিনিস আছে। আর আমি তোমার জন্য দেব। আর আমি জানি, আমি জানি যে, আমি জানি, আমি জানি, ঈশ্বর আমাকে শান্তি স্থাপন করবেন এবং তিনি শান্তি দেবেন । আমাদের সম্পর্কে কোন গায়কের দ্বারা আমাদের কোন লাভ হয়নি, যদি না আপনি স্বাধীনতার আগুন জ্বালিয়ে থাকেন, কিন্তু এটা মজার স্বাদ। আমাকে বলেন, আপনি এমন কিছু করার চেষ্টা করবেন না যা করা হয়েছে তার আংটি যখন চলছিল তখন আমার কাছে ছিল.","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ سَوَادَةَ ‏ ‏أَنَّ ‏ ‏أَبَا النَّجِيبِ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ سَعْدٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَجُلًا قَدِمَ مِنْ ‏ ‏نَجْرَانَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ خَاتَمُ ذَهَبٍ فَأَعْرَضَ عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يَسْأَلْهُ عَنْ شَيْءٍ فَرَجَعَ الرَّجُلُ إِلَى امْرَأَتِهِ فَحَدَّثَهَا فَقَالَتْ إِنَّ لَكَ لَشَأْنًا فَارْجِعْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَجَعَ إِلَيْهِ فَأَلْقَى خَاتَمَهُ وَجُبَّةً كَانَتْ عَلَيْهِ فَلَمَّا اسْتَأْذَنَ أُذِنَ لَهُ وَسَلَّمَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَدَّ عَلَيْهِ السَّلَامَ فَقَالَ يَا رَسُولَ اللَّهِ أَعْرَضْتَ عَنِّي قَبْلُ حِينَ جِئْتُكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكَ جِئْتَنِي وَفِي يَدِكَ جَمْرَةٌ مِنْ نَارٍ فَقَالَ يَا رَسُولَ اللَّهِ لَقَدْ جِئْتُ إِذًا بِجَمْرٍ كَثِيرٍ وَكَانَ قَدْ قَدِمَ بِحُلِيٍّ مِنْ ‏ ‏الْبَحْرَيْنِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مَا جِئْتَ بِهِ غَيْرُ مُغْنٍ عَنَّا شَيْئًا إِلَّا مَا أَغْنَتْ حِجَارَةُ ‏ ‏الْحَرَّةِ ‏ ‏وَلَكِنَّهُ مَتَاعُ الْحَيَاةِ الدُّنْيَا فَقَالَ الرَّجُلُ فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏اعْذُرْنِي ‏ ‏فِي أَصْحَابِكَ لَا يَظُنُّونَ أَنَّكَ سَخِطْتَ عَلَيَّ بِشَيْءٍ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَذَرَهُ ‏ ‏وَأَخْبَرَ أَنَّ الَّذِي ‏ ‏كَانَ مِنْهُ إِنَّمَا كَانَ لِخَاتَمِهِ الذَّهَبِ ‏","","",""],[10687,10687,"","আমরা একটা ছেলে ছেলের কথা বলেছিলাম যে বাবার ভালবাসা সম্পর্কে আমাকে বলেছিল. আমার বাবা আমার বাবার খুশির কৌশল নিয়ে কিন্তু ঈশ্বর আমাকে সব মানুষের থেকে বের করে আনতে বলেছেন বাইরে যাও আর এটা নিয়ে চলে যাও।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏الْمَهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ إِلَى ‏ ‏بَنِي لَحْيَانَ ‏ ‏لِيَخْرُجْ مِنْ كُلِّ رَجُلَيْنِ رَجُلٌ ثُمَّ قَالَ لِلْقَاعِدِ ‏ ‏أَيُّكُمْ خَلَفَ الْخَارِجَ فِي أَهْلِهِ وَمَالِهِ بِخَيْرٍ كَانَ لَهُ مِثْلُ نِصْفِ أَجْرِ الْخَارِجِ ‏","","",""],[10688,10688,"","আমরা দু'বছর আগে আমাদের সাথে একটি ছেলে থাকার কথা বলেছি, কিন্তু ঈশ্বর কখনোই আমার বাবার সাথে থাকতে পারেন নি। সে জিততে পারবে না, আর জিততে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏حَنَشِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏لَيْسَ مَرْفُوعًا ‏ ‏قَالَ ‏ ‏لَا يَصْلُحُ ‏ ‏السَّلَفُ ‏ ‏فِي الْقَمْحِ وَالشَّعِيرِ ‏ ‏وَالسُّلْتِ ‏ ‏حَتَّى يُفْرَكَ وَلَا فِي الْعِنَبِ وَالزَّيْتُونِ وَأَشْبَاهِ ذَلِكَ حَتَّى ‏ ‏يُمَجِّجَ ‏ ‏وَلَا ذَهَبًا عَيْنًا ‏ ‏بِوَرِقٍ ‏ ‏دَيْنًا وَلَا ‏ ‏وَرِقًا ‏ ‏دَيْنًا بِذَهَبٍ عَيْنًا ‏","","",""],[10689,10689,"","আমি আমার বাবার নাম নিয়ে কথা বলেছি, আল্লাহকে কেবল তার প্রার্থনার চ্যালেঞ্জ করতে হবে... ...আর তারপর তার দয়ায় ফিরে যেতে হবে. প্রার্থনা করে ঈশ্বর তার বাড়িতে প্রার্থনা থেকে কাজ করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَضَى أَحَدُكُمْ صَلَاتَهُ فِي الْمَسْجِدِ ثُمَّ رَجَعَ إِلَى بَيْتِهِ حِينَئِذٍ فَلْيُصَلِّ فِي بَيْتِهِ رَكْعَتَيْنِ وَلْيَجْعَلْ فِي بَيْتِهِ نَصِيبًا مِنْ صَلَاتِهِ فَإِنَّ اللَّهَ جَاعِلٌ فِي بَيْتِهِ مِنْ صَلَاتِهِ خَيْرًا ‏","","",""],[10690,10690,"","আমরা সংবাদ চুরি করার চেষ্টা করেছি, একটি ছেলে ঈশ্বরের মুখ থেকে দূরে সরে যেতে শিখেছে। অথবা তাকে বলতে পেরে খুশি হয়েছি যে, ঈশ্বরের দয়া ভালো এবং সে জিজ্ঞেস করেছে এবং এটাই হচ্ছে। ভাল.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ الْمُغِيرَةِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْهَيْثَمِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ بَيَاضَ ‏ ‏كَشْحِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ سَاجِدٌ ‏","","",""],[10691,10691,"","আমরা ঈশ্বরের পুত্রের সাথে ঈশ্বরের এক দাসের কথা বলেছি, মাদক বলেছিল আমি ঈশ্বরের অনুগ্রহের সাদাদের দেখছি।","‏ ‏حَدَّثَنَاه ‏ ‏مُوسَى هُوَ ابْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى بَيَاضِ ‏ ‏كَشْحِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ سَاجِدٌ ‏","","",""],[10692,10692,"","আমি আমার ভাইয়ের সাহায্য করার চেয়ে ভালো কথা বলেছি, সে রাতে অন্ধ হয়ে যায় নি। সে বললো, সে সসিয়ামের কাছে হাত পড়েছিলো... ...হাহাড়ার অর্ধেকটা গুনতে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏بَاتَ ‏ ‏قَتَادَةُ بْنُ النُّعْمَانِ ‏ ‏يَقْرَأُ اللَّيْلَ كُلَّهُ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏فَذُكِرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَتَعْدِلُ نِصْفَ الْقُرْآنِ ‏ ‏أَوْ ثُلُثَهُ ‏","","",""],[10693,10693,"","আমরা তার বাবার সাথে কথা বলেছি আমরা বরং বলতে চাই আমাদের ভাই আছে। সে ঈশ্বরের কাছে প্রার্থনা করে যেন সে আপনাকে উদ্ধার করে, যদি আমি আপনার বিচার করি, যদি সে তার ভ্রমণের পরের বারের মত হয়।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏حَبَّانَ بْنِ وَاسِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فِي ثَوْبٍ فَلْيَجْعَلْ طَرَفَهُ عَلَى ‏ ‏عَاتِقَيْهِ ‏","","",""],[10694,10694,"","আমরা সবাই একটা ছেলের কথা বলেছি, গুড গডের বাবা আমাকে বলেছিলেন আমি তার সবচেয়ে ভাল হাত থেকে তোমার কথা শুনবো. আমার বাবার কাছে, পাইলট বলেছিলেন যে আমি সেই লোকটিকে জিজ্ঞেস করব যে সে যদি মনে করে যে সে চলে যাবে, তাহলে সে চলে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَخْبَرَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَشْهَدُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَجَرَهُ عَنْ ذَلِكَ وَزَجَرَهُ أَنْ يَسْتَقْبِلَ الْقِبْلَةَ لِبَوْلٍ ‏ ‏وَهَذَا يَتْلُو حَدِيثَ ‏ ‏ابْنِ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الرَّجُلِ يَشْرَبُ وَهُوَ قَائِمٌ فَقَالَ كُنَّا نَكْرَهُ ذَاكَ ‏ ‏ثُمَّ ذَكَرَ حَدِيثَ ‏ ‏أَبِي سَعِيدٍ ‏","","",""],[10695,10695,"","ঈশ্বর কখনো এত ভাল কথা বলেননি বলে ঈশ্বর প্রার্থনা করেছেন । ভগবানের কাছে লর্ডের কাছে প্রার্থনা করুক, লর্ডের লর্ডের কাছে প্রার্থনা করুক। আমি তাকে মারার জন্য গর্বিত। তাকে মেরে ফেলো! সে আমার বিজ্ঞানে গিয়েছিল, সে তাকে দেখেনি, সে আমার মুখ থেকে বের হতে দেখেনি, সে বলেছিল, \"ঈশ্বর, ঈশ্বর তাকে এটা বলতে পারেনি যে \"ঈশ্বর\" এটা আমি চেষ্টা করছি। তারা ফিরে আসার আগ পর্যন্ত তারা ফিরে আসে.","‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏جَامِعُ بْنُ مَطَرٍ الْحَبَطِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو رُؤْبَةَ شَدَّادُ بْنُ عِمْرَانَ الْقَيْسِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏جَاءَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي مَرَرْتُ بِوَادِي كَذَا وَكَذَا فَإِذَا رَجُلٌ مُتَخَشِّعٌ حَسَنُ الْهَيْئَةِ ‏ ‏يُصَلِّي فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اذْهَبْ إِلَيْهِ فَاقْتُلْهُ قَالَ فَذَهَبَ إِلَيْهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَلَمَّا رَآهُ عَلَى تِلْكَ الْحَالِ كَرِهَ أَنْ يَقْتُلَهُ فَرَجَعَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِعُمَرَ ‏ ‏اذْهَبْ فَاقْتُلْهُ فَذَهَبَ ‏ ‏عُمَرُ ‏ ‏فَرَآهُ عَلَى تِلْكَ الْحَالِ الَّتِي رَآهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏قَالَ فَكَرِهَ أَنْ يَقْتُلَهُ قَالَ فَرَجَعَ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي رَأَيْتُهُ ‏ ‏يُصَلِّي مُتَخَشِّعًا فَكَرِهْتُ أَنْ أَقْتُلَهُ قَالَ يَا ‏ ‏عَلِيُّ ‏ ‏اذْهَبْ فَاقْتُلْهُ قَالَ فَذَهَبَ ‏ ‏عَلِيٌّ ‏ ‏فَلَمْ يَرَهُ فَرَجَعَ ‏ ‏عَلِيٌّ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّهُ لَمْ ‏ ‏يُرَهْ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذَا وَأَصْحَابَهُ يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏ثُمَّ لَا يَعُودُونَ فِيهِ حَتَّى يَعُودَ السَّهْمُ فِي ‏ ‏فُوقِهِ ‏ ‏فَاقْتُلُوهُمْ هُمْ شَرُّ ‏ ‏الْبَرِيَّةِ ‏","","",""],[10696,10696,"","আমরা দিনের কথা বলেছিলাম যখন আমরা স্বপ্ন দেখতে গিয়েছিলাম, আমি বাবার ছেলের উপর সেলাই করে দেবো, সে বলে যে তুমি আমার বাবার সাথে কাজ করেছ। আপনি ভাল করে বলবেন, ঈশ্বর তার থেকে আলো আসছে... ...আর সে তার মুখেই থাকবে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُطَرِّفٌ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي نَوْفٍ ‏ ‏عَنِ ‏ ‏سَلِيطِ بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏انْتَهَيْتُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَتَوَضَّأُ مِنْ ‏ ‏بِئْرِ بُضَاعَةَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏تَوَضَّأُ مِنْهَا وَهِيَ يُلْقَى فِيهَا مَا يُلْقَى مِنْ النَّتْنِ فَقَالَ إِنَّ ‏ ‏الْمَاءَ لَا يُنَجِّسُهُ شَيْءٌ ‏","","",""],[10697,10697,"","আমরা আমার বাবার সাথে কথা বলেছি আমার ভাইকে মারার চেষ্টা করার কথা, ঈশ্বর বললেন, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি আপনাকে আত্মসমর্পণ করবেন আপনার প্রভু এবং আপনার প্রভু এবং আপনি আঘাত পাবেন আপনি আপনার প্রভু এবং আপনি আঘাত পেয়েছিলাম আপনি দেখুন সূর্য অর্ধেক নদী তারা বলেছিল, প্রভুর ভাগ্যকে হারিয়ে না ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ عَزَّ وَجَلَّ قَالُوا يَا رَسُولَ اللَّهِ نَرَى رَبَّنَا قَالَ فَقَالَ هَلْ ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَةِ الشَّمْسِ نِصْفَ النَّهَارِ قَالُوا لَا قَالَ فَتُضَارُّونَ فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ قَالُوا لَا قَالَ فَإِنَّكُمْ لَا ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَتِهِ إِلَّا كَمَا ‏ ‏تُضَارُّونَ ‏ ‏فِي ذَلِكَ ‏ ‏قَالَ ‏ ‏الْأَعْمَشُ ‏ ‏لَا ‏ ‏تُضَارُّونَ ‏ ‏يَقُولُ لَا ‏ ‏تُمَارُونَ ‏","","",""],[10698,10698,"","আমরা একটা ছেলের কথা বলেছিলাম যে সূর্য দিয়ে সাহায্য করার জন্য গোলাম ছিল। ড্রাগ বলেছিল, ঈশ্বরের প্রার্থনা হবে তার কাছে আর এই কঠিন ঋতুর শক্তিশালী রাজাদের কাছে। শেষ কয়েকজন মহিলা হল, যারা আমার কাছে এসে হাজির হবে। বুড়ো হয়ে বলতে গেলে, \"তুমি একজন মহিলার দশ ভাগের এক ভাগ\" বাটনটা।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ صُفُوفِ الرِّجَالِ الصَّفُّ الْمُقَدَّمُ وَشَرُّهَا الصَّفُّ الْمُؤَخَّرُ وَخَيْرُ صُفُوفِ النِّسَاءِ الْمُؤَخَّرُ وَشَرُّهَا الْمُقَدَّمُ وَقَالَ يَا مَعْشَرَ النِّسَاءِ لَا تَرْفَعْنَ رُءُوسَكُنَّ إِذَا سَجَدْتُنَّ لَا تَرَيْنَ عَوْرَاتِ الرِّجَالِ مِنْ ضِيقِ ‏ ‏الْأُزُرِ ‏","","",""],[10699,10699,"","আমরা আগে থেকে দুজন লোককে খুঁজে বের করার চেষ্টা করেছি, বাবা খুশি ড্রাগে বলেছে যে ঈশ্বর ঈশ্বরকে রক্ষা করেছে আর আমি পতাকা নিয়ে আসছি। হঠাৎ করে দুটো শব্দ বলে, আমরা সেলাই করে তাকে খুন করতে এসেছি। আর এভাবেই সে তাকে এমন একজনকে দিতে দৃঢ়প্রতিজ্ঞ ছিল যে কখনো সেখানে থেকে পালিয়ে যেতে পারবে না। সে তাকে ব্যর্থ করেছিল, তারা তাদের মাঝে এসে তাদের চালাত।","‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ الْمِقْدَامِ ‏ ‏وَحُجَيْنُ بْنُ الْمُثَنَّى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عِصْمَةَ الْعِجْلِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَ ‏ ‏الرَّايَةَ ‏ ‏فَهَزَّهَا ثُمَّ قَالَ ‏ ‏مَنْ يَأْخُذُهَا بِحَقِّهَا فَجَاءَ فُلَانٌ فَقَالَ أَنَا قَالَ ‏ ‏أَمِطْ ‏ ‏ثُمَّ جَاءَ رَجُلٌ فَقَالَ ‏ ‏أَمِطْ ‏ ‏ثُمَّ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي كَرَّمَ وَجْهَ ‏ ‏مُحَمَّدٍ ‏ ‏لَأُعْطِيَنَّهَا رَجُلًا لَا يَفِرُّ ‏ ‏هَاكَ يَا ‏ ‏عَلِيُّ ‏ ‏فَانْطَلَقَ حَتَّى فَتَحَ اللَّهُ عَلَيْهِ ‏ ‏خَيْبَرَ ‏ ‏وَفَدَكَ ‏ ‏وَجَاءَ بِعَجْوَتِهِمَا ‏ ‏وَقَدِيدِهِمَا ‏ ‏قَالَ ‏ ‏مُصْعَبٌ ‏ ‏بِعَجْوَتِهَا ‏ ‏وَقَدِيدِهَا ‏","","",""],[10700,10700,"","আমরা আমার ভাইয়ের শেষ দিন সম্পর্কে কথা বলেছি, আমি আমার ভাইয়ের থেকে ভালো ভাই শুরু করেছি, ঈশ্বর আমাকে বলতে শুনেছেন যে তুমি ডেনারকে একটা কথা বলছো, আমি এটা দিচ্ছি দশ বা দশ বছর। আমি এটা দিয়ে দিয়েছি। আমি এটা আমার ভাইয়ের শেষ কথা বলছি, আমার ভাইয়ের সাথে আমার ভাইয়ের শেষ কথা বলছি, আমি তোমাকে বলতে চাই। আমি তোমাকে বলতে চাই, আমি তোমার কাছে এটা বলতে চাই যে, আমি তোমার কাছে এটা ১০---------------------------------------------------------------------------------------------------------------------------------------------------------------------------- ভুলের কথা বলতে গেলে... ...দুই শত মানুষের হয়ে কাজ করতে হবে, আর আমি তাদের বলতেও পারবো না যে তারা এটা করবে না, ঈশ্বর আমাদের একজন পিপাসার্ত ছেলের দ্বারা হত্যা করেছে। বাবা খুশি আমরা তার পরিভাষার কথা উল্লেখ করেছি","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ سَمِعْتُ فُلَانًا يَقُولُ خَيْرًا ذَكَرَ أَنَّكَ أَعْطَيْتَهُ دِينَارَيْنِ قَالَ لَكِنْ فُلَانٌ لَا يَقُولُ ذَلِكَ وَلَا ‏ ‏يُثْنِي ‏ ‏بِهِ لَقَدْ أَعْطَيْتُهُ مَا بَيْنَ الْعَشَرَةِ إِلَى الْمِائَةِ ‏ ‏أَوْ قَالَ إِلَى الْمِائَتَيْنِ ‏ ‏وَإِنَّ أَحَدَهُمْ لَيَسْأَلُنِي الْمَسْأَلَةَ فَأُعْطِيهَا إِيَّاهُ فَيَخْرُجُ بِهَا مُتَأَبِّطُهَا وَمَا هِيَ لَهُمْ إِلَّا نَارٌ قَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ فَلِمَ ‏ ‏تُعْطِيهِمْ قَالَ ‏ ‏إِنَّهُمْ يَأْبَوْنَ إِلَّا أَنْ يَسْأَلُونِي ‏ ‏وَيَأْبَى اللَّهُ لِي الْبُخْلَ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عُثْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[10701,10701,"","আমি কথা বলেছি আমাকে আরো ভালো হাতে দেওয়ার জন্য দেরী করার কথা। আমি তার কাছে প্রার্থনা করেছি এবং সে জানতে ব্যর্থ হয়েছে যে মানুষ আসলে কি জানে। জনতার মাঝে \"সেফটি\" মানে ঈশ্বরের কাছে মূল্যহীন এবং মানুষকে তার মন্দ থেকে আহ্বান জানানো।","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسُئِلَ أَيُّ النَّاسِ خَيْرٌ فَقَالَ ‏ ‏مُؤْمِنٌ مُجَاهِدٌ بِمَالِهِ وَنَفْسِهِ فِي سَبِيلِ اللَّهِ قَالَ ثُمَّ مَنْ قَالَ مُؤْمِنٌ فِي ‏ ‏شِعْبٍ ‏ ‏مِنْ ‏ ‏الشِّعَابِ ‏ ‏يَتَّقِي اللَّهَ وَيَدَعُ النَّاسَ مِنْ شَرِّهِ ‏","","",""],[10702,10702,"","তিনি বলেছিলেন, আমার বাবার প্রভুর কাছে ফিরে যাওয়ার কথা । তার মাথার দিকে তার মগজটা তার মাংসের দিকে ফিরে এসে তাকে ভেঙে ফেলা এবং তাকে সমাধান করা যায় ।","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏فُضَيْلٌ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَوَّلَ ‏ ‏زُمْرَةٍ ‏ ‏تَدْخُلُ الْجَنَّةَ يَوْمَ الْقِيَامَةِ صُورَةُ وُجُوهِهِمْ عَلَى مِثْلِ صُورَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ ‏ ‏وَالزُّمْرَةُ ‏ ‏الثَّانِيَةُ عَلَى لَوْنٍ أَحْسَنَ مِنْ كَوْكَبٍ ‏ ‏دُرِّيٍّ ‏ ‏فِي السَّمَاءِ لِكُلِّ رَجُلٍ مِنْهُمْ زَوْجَتَانِ عَلَى كُلِّ زَوْجَةٍ سَبْعُونَ ‏ ‏حُلَّةً ‏ ‏يُرَى مُخُّ سَاقِهَا مِنْ وَرَاءِ لُحُومِهَا وَدَمِهَا وَحُلَلِهَا ‏","","",""],[10703,10703,"","আমার বাবা মারা যাওয়ার পর খুশি হয়ে বলেছিলেন যে আমরা ঈশ্বরের কাছে যেতে পারব আর তিনি তাকে আত্মসমর্পণ করতে হবে । তিনি আমাদের হত্যা করার চেষ্টা করে তার ধর্মকে ক্ষতি করতে বলেছেন যে তিনি কোন ক্ষতি করতে পারবেন না এই কারনে যে তিনি কোন ক্ষতি করেননি যে তিনি আসলে কোন কারনে প্রভাবিত হয়েছেন। নায়ক আমরা বলছি না যে আপনি হয়তো ভাল হতে পারেন আপনি বিশ্বের সেরা লোকদের একত্রিত করতে পারেন. এটা তাকে অনুসরণ করা কিছু তাকে অনুসরণ করতে বলা হয়েছে. যারা সূর্যের সবচেয়ে খারাপ অংশ হতো, তারা আগুনে ধরা পড়ত এবং যারা ছিল তাদের অনুসরণ করবে, তারা আগুনে পুড়ছিল এবং যারা ক্লান্ত ছিল তাদের অনুসরণ করবে। ঈশ্বরের নামেও যদি কেউ আগুনে আটকে থাকে তাহলে যদি বিশ্বস্তরা সন্তুষ্ট থাকে এবং বলে তারা রাজার হাতে আছে, আমি তাদের অনুসরণ করছি না। আল্লাহ, সে ভালো চিহ্ন রেখে দিয়েছে আর কেউ তার চোখের সামনে থেকে তাকে দেখতে পায়নি। আর ভবিষ্যদ্বাণীটা বলছে যে তারা সেখানে পৌঁছে যাবে আর আসবে তিনি বলেছিলেন যে, লোকেরা অপহরণ করেছে আর কর্তৃপক্ষ এত ভালো ছিল যে তাকে অপহরণ করা হয়েছে। আমি ঘোড়া আর যাত্রীকে একটা শান্তিপূর্ণ, বিকৃত তথ্য, বিকৃত এবং হিংস্রভাবে আগুনে খুঁজে বের করতে পারি, তাই আমি তাকে কেটে ফেলি অথবা মেরে ফেলব। আমরা যখন বেঁচে থাকি এবং তারা বলেছিল যে, ঈশ্বর দুঃখ । তার হৃদয়ে ছিল দ্বিতীয় একটি কার্টুন, যা একটা ধার্মিকতার প্রতি ভালোবাসা, সে দিনের মাঝখানে তা বের করে, আর তারপরে সে বলে, \"বাবা, বাবা, \"বাবা, সে বললো, \"বাবা,\" \"বাবা,\" বললো, \"সা\" সে বলল, \"সা\" সে বলল, \"স্য\" আমার মনে হয় এটা ভালবাসা ছিল যে সে একটা আবর্জনার প্রতি ভালোবাসা ছিল যা আমাদের যুদ্ধ করতে হত, তারা শেষ হয়ে গেছে। তারা ছিল এক সময়, তারা ছিল এক আগুনের মধ্যে, তারা শেষ। তারা ছিল এক এক সময়, তারা ছিল এক সময়, তারা ছিল এক সময়, তারা ছিল এক সময় ছিল এক শিশু, তারা ছিল এক শিশু, এবং তারা ছিল এক শিশু, তারা ছিল। নদীর মধ্যে থাকা অবস্থায় তিমিকে উড়িয়ে দিতে হবে যখন তুমি ভালবাসার প্রতি ভালোবাসাকে ভালোবাসো। ছায়া, আমি হয়তো গান ডাকতাম","‏ ‏حَدَّثَنَا ‏ ‏رِبْعِيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْنَا يَا رَسُولَ اللَّهِ هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ فَقَالَ هَلْ ‏ ‏تُضَارُّونَ ‏ ‏فِي الشَّمْسِ لَيْسَ دُونَهَا سَحَابٌ قَالَ قُلْنَا لَا قَالَ فَهَلْ ‏ ‏تُضَارُّونَ ‏ ‏فِي الْقَمَرِ لَيْلَةَ الْبَدْرِ لَيْسَ دُونَهُ سَحَابٌ قَالَ قُلْنَا لَا قَالَ فَإِنَّكُمْ تَرَوْنَ رَبَّكُمْ كَذَلِكَ يَوْمَ الْقِيَامَةِ يَجْمَعُ اللَّهُ النَّاسَ يَوْمَ الْقِيَامَةِ فِي ‏ ‏صَعِيدٍ ‏ ‏وَاحِدٍ قَالَ فَيُقَالُ مَنْ كَانَ يَعْبُدُ شَيْئًا فَلْيَتْبَعْهُ قَالَ فَيَتْبَعُ الَّذِينَ كَانُوا يَعْبُدُونَ الشَّمْسَ الشَّمْسَ فَيَتَسَاقَطُونَ فِي النَّارِ وَيَتْبَعُ الَّذِينَ كَانُوا يَعْبُدُونَ الْقَمَرَ الْقَمَرَ فَيَتَسَاقَطُونَ فِي النَّارِ وَيَتْبَعُ الَّذِينَ كَانُوا يَعْبُدُونَ الْأَوْثَانَ الْأَوْثَانَ وَالَّذِينَ كَانُوا يَعْبُدُونَ الْأَصْنَامَ الْأَصْنَامَ فَيَتَسَاقَطُونَ فِي النَّارِ قَالَ وَكُلُّ مَنْ كَانَ يُعْبَدُ مِنْ ‏ ‏دُونِ اللَّهِ حَتَّى يَتَسَاقَطُونَ فِي النَّارِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَبْقَى الْمُؤْمِنُونَ وَمُنَافِقُوهُمْ بَيْنَ ظَهْرَيْهِمْ وَبَقَايَا ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏وَقَلَّلَهُمْ بِيَدِهِ قَالَ ‏ ‏فَيَأْتِيهِمْ اللَّهُ عَزَّ وَجَلَّ فَيَقُولُ ‏ ‏أَلَا تَتَّبِعُونَ مَا كُنْتُمْ تَعْبُدُونَ قَالَ فَيَقُولُونَ كُنَّا نَعْبُدُ اللَّهَ وَلَمْ نَرَ اللَّهَ فَيُكْشَفُ عَنْ سَاقٍ فَلَا يَبْقَى أَحَدٌ كَانَ يَسْجُدُ لِلَّهِ إِلَّا وَقَعَ سَاجِدًا وَلَا يَبْقَى أَحَدٌ كَانَ يَسْجُدُ ‏ ‏رِيَاءً ‏ ‏وَسُمْعَةً ‏ ‏إِلَّا وَقَعَ عَلَى قَفَاهُ قَالَ ثُمَّ يُوضَعُ ‏ ‏الصِّرَاطُ ‏ ‏بَيْنَ ظَهْرَيْ جَهَنَّمَ وَالْأَنْبِيَاءُ بِنَاحِيتَيْهِ قَوْلُهُمْ اللَّهُمَّ سَلِّمْ سَلِّمْ اللَّهُمَّ سَلِّمْ سَلِّمْ وَإِنَّهُ ‏ ‏لَدَحْضُ ‏ ‏مَزَلَّةٍ ‏ ‏وَإِنَّهُ ‏ ‏لَكَلَالِيبُ ‏ ‏وَخَطَاطِيفُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَلَا أَدْرِي لَعَلَّهُ قَدْ قَالَ تَخْطَفُ النَّاسَ ‏ ‏وَحَسَكَةٌ ‏ ‏تَنْبُتُ ‏ ‏بِنَجْدٍ ‏ ‏يُقَالُ لَهَا ‏ ‏السَّعْدَانُ ‏ ‏قَالَ ‏ ‏وَنَعَتَهَا ‏ ‏لَهُمْ قَالَ فَأَكُونُ أَنَا وَأُمَّتِي لَأَوَّلَ مَنْ مَرَّ ‏ ‏أَوْ أَوَّلَ مَنْ ‏ ‏يُجِيزُ ‏ ‏قَالَ فَيَمُرُّونَ عَلَيْهِ مِثْلَ الْبَرْقِ وَمِثْلَ الرِّيحِ وَمِثْلَ ‏ ‏أَجَاوِيدِ ‏ ‏الْخَيْلِ وَالرِّكَابِ فَنَاجٍ مُسَلَّمٌ وَمَخْدُوشٌ ‏ ‏مُكَلَّمٌ ‏ ‏وَمَكْدُوسٌ ‏ ‏فِي النَّارِ فَإِذَا قَطَعُوهُ ‏ ‏أَوْ فَإِذَا جَاوَزُوهُ ‏ ‏فَمَا أَحَدُكُمْ فِي حَقٍّ يَعْلَمُ أَنَّهُ حَقٌّ لَهُ بِأَشَدَّ مُنَاشَدَةً مِنْهُمْ فِي إِخْوَانِهِمْ الَّذِينَ سَقَطُوا فِي النَّارِ يَقُولُونَ أَيْ رَبِّ كُنَّا نَغْزُو جَمِيعًا وَنَحُجُّ جَمِيعًا وَنَعْتَمِرُ جَمِيعًا فَبِمَ نَجَوْنَا الْيَوْمَ وَهَلَكُوا قَالَ فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ انْظُرُوا مَنْ كَانَ فِي قَلْبِهِ زِنَةُ دِينَارٍ مِنْ إِيمَانٍ فَأَخْرِجُوهُ قَالَ فَيُخْرَجُونَ قَالَ ثُمَّ يَقُولُ مَنْ كَانَ فِي قَلْبِهِ زِنَةُ ‏ ‏قِيرَاطٍ ‏ ‏مِنْ إِيمَانٍ فَأَخْرِجُوهُ قَالَ فَيُخْرَجُونَ قَالَ ثُمَّ يَقُولُ مَنْ كَانَ فِي قَلْبِهِ ‏ ‏مِثْقَالُ ‏ ‏حَبَّةِ ‏ ‏خَرْدَلٍ ‏ ‏مِنْ إِيمَانٍ فَأَخْرِجُوهُ قَالَ فَيُخْرَجُونَ ‏ ‏قَالَ ثُمَّ يَقُولُ ‏ ‏أَبُو سَعِيدٍ ‏ ‏بَيْنِي وَبَيْنَكُمْ كِتَابُ اللَّهِ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَأَظُنُّهُ ‏ ‏يَعْنِي قَوْلَهُ ‏ { ‏وَإِنْ كَانَ ‏ ‏مِثْقَالَ ‏ ‏حَبَّةٍ مِنْ ‏ ‏خَرْدَلٍ ‏ ‏أَتَيْنَا بِهَا وَكَفَى بِنَا حَاسِبِينَ ‏} ‏قَالَ فَيُخْرَجُونَ ‏ ‏مِنْ النَّارِ فَيُطْرَحُونَ فِي نَهَرٍ يُقَالُ لَهُ نَهَرُ الْحَيَوَانِ فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبُّ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ أَلَا تَرَوْنَ مَا يَكُونُ مِنْ النَّبْتِ إِلَى الشَّمْسِ يَكُونُ أَخْضَرَ وَمَا يَكُونُ إِلَى الظِّلِّ يَكُونُ أَصْفَرَ قَالُوا يَا رَسُولَ اللَّهِ كَأَنَّكَ كُنْتَ قَدْ رَعَيْتَ الْغَنَمَ قَالَ أَجَلْ قَدْ رَعَيْتُ الْغَنَمَ ‏","","",""],[10704,10704,"","আমরা যখন আমাদের সাক্ষাৎ হয়েছিল, তখন আমরা যখন কথা বলার চেষ্টা করছিলাম, তখন আমরা এক দুর্বল ছেলের কথা বলেছিলাম । এরপর তিনি বলেছিলেন যে, তিনি তার জন্য ক্ষমা প্রার্থনা করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏فِرَاسُ بْنُ يَحْيَى الْهَمْدَانِيُّ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَقَدْ دَخَلَ رَجُلٌ الْجَنَّةَ مَا عَمِلَ خَيْرًا قَطُّ قَالَ لِأَهْلِهِ حِينَ حَضَرَهُ الْمَوْتُ إِذَا أَنَا مُتُّ فَأَحْرِقُونِي ثُمَّ اسْحَقُونِي ثُمَّ اذْرُوا نِصْفِي فِي الْبَحْرِ وَنِصْفِي فِي الْبَرِّ فَأَمَرَ اللَّهُ الْبَرَّ وَالْبَحْرَ فَجَمَعَاهُ ثُمَّ قَالَ ‏ ‏مَا حَمَلَكَ عَلَى مَا فَعَلْتَ قَالَ مَخَافَتُكَ قَالَ فَغُفِرَ لَهُ لِذَلِكَ ‏","","",""],[10705,10705,"","বাবা আমার ভাইকে নিয়ে কথা বলেছিল, বাবা বলেছিলেন, ঈশ্বর তার কাছে প্রার্থনা করুক আর প্রভু হিসেবে তিনি লর্ডের কাছে প্রার্থনা করবেন। আমি তার কভার ঘুরিয়ে দিচ্ছি এবং বলে রাখছি, \"বাদুর্নীতি\" নাকি \"বা \"বাকি\"র কথা বলা দরকার।\" কফিনের পতন হয়, অথবা কফিনের পতন হয় এবং শপথটা আত্মার পতনের সমান। এটা অনেকটা ভালো পানির অমার্জন এবং একই ধারণা। সে কখন শেষ পর্যন্ত চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقُلُوبُ أَرْبَعَةٌ قَلْبٌ ‏ ‏أَجْرَدُ ‏ ‏فِيهِ مِثْلُ ‏ ‏السِّرَاجِ ‏ ‏يُزْهِرُ وَقَلْبٌ ‏ ‏أَغْلَفُ ‏ ‏مَرْبُوطٌ عَلَى غِلَافِهِ وَقَلْبٌ ‏ ‏مَنْكُوسٌ ‏ ‏وَقَلْبٌ ‏ ‏مُصْفَحٌ ‏ ‏فَأَمَّا الْقَلْبُ ‏ ‏الْأَجْرَدُ ‏ ‏فَقَلْبُ الْمُؤْمِنِ ‏ ‏سِرَاجُهُ ‏ ‏فِيهِ نُورُهُ وَأَمَّا الْقَلْبُ ‏ ‏الْأَغْلَفُ ‏ ‏فَقَلْبُ الْكَافِرِ وَأَمَّا الْقَلْبُ ‏ ‏الْمَنْكُوسُ ‏ ‏فَقَلْبُ الْمُنَافِقِ عَرَفَ ثُمَّ أَنْكَرَ وَأَمَّا الْقَلْبُ ‏ ‏الْمُصْفَحُ ‏ ‏فَقَلْبٌ فِيهِ إِيمَانٌ وَنِفَاقٌ فَمَثَلُ الْإِيمَانِ فِيهِ كَمَثَلِ ‏ ‏الْبَقْلَةِ ‏ ‏يَمُدُّهَا الْمَاءُ الطَّيِّبُ وَمَثَلُ النِّفَاقِ فِيهِ كَمَثَلِ الْقُرْحَةِ يَمُدُّهَا الْقَيْحُ وَالدَّمُ فَأَيُّ الْمَدَّتَيْنِ غَلَبَتْ عَلَى الْأُخْرَى غَلَبَتْ عَلَيْهِ ‏","","",""],[10706,10706,"","আমি আমার বাবার সাথে কথা বলেছি আমার ছেলের জীবনের দু'টি ভাগ করে নিয়ে যেতে। মাদকের কথা বলেছিলাম তার কাছে প্রার্থনা করতে। আর আমি সেই লোকটির কাছে যেতে পারবো না। আমার কাছে আছে, পুরো দৌড় দিয়ে চলাটা ছিল সাত বছর আগের অন্ধকার।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ شَيْبَانُ ‏ ‏عَنْ ‏ ‏مَطَرِ بْنِ طَهْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَمْلِكَ رَجُلٌ مِنْ أَهْلِ بَيْتِي أَجْلَى ‏ ‏أَقْنَى ‏ ‏يَمْلَأُ الْأَرْضَ عَدْلًا كَمَا مُلِئَتْ قَبْلَهُ ظُلْمًا يَكُونُ سَبْعَ سِنِينَ ‏","","",""],[10707,10707,"","আমি যখন সেখান থেকে বের হয়ে আসি, তখন ঈশ্বর আমাকে চিঠি লিখে দিয়েছিলেন । স্বর্গ আমার আত্মাকে মিথ্যা বলতে, তারা কখনো ভেঙ্গে ফেলতে পারবে না, তারা আমাকে দেখাতে চায় তুমি কি করতে চাইছ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ طَلْحَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنِّي ‏ ‏أُوشِكُ ‏ ‏أَنْ ‏ ‏أُدْعَى فَأُجِيبَ وَإِنِّي تَارِكٌ فِيكُمْ ‏ ‏الثَّقَلَيْنِ ‏ ‏كِتَابَ اللَّهِ عَزَّ وَجَلَّ ‏ ‏وَعِتْرَتِي ‏ ‏كِتَابُ اللَّهِ حَبْلٌ مَمْدُودٌ مِنْ السَّمَاءِ إِلَى الْأَرْضِ ‏ ‏وَعِتْرَتِي ‏ ‏أَهْلُ بَيْتِي وَإِنَّ اللَّطِيفَ الْخَبِيرَ أَخْبَرَنِي أَنَّهُمَا لَنْ يَفْتَرِقَا حَتَّى يَرِدَا عَلَيَّ الْحَوْضَ فَانْظُرُونِي بِمَ تَخْلُفُونِي فِيهِمَا ‏","","",""],[10708,10708,"","আমরা রাজার সাহায্য নিয়ে কথা বলেছিলাম। ভুলে যাও আর এটাই আমার কাজ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَرَزَ بَيْنَ يَدَيْهِ غَرْزًا ثُمَّ غَرَزَ إِلَى جَنْبِهِ آخَرَ ثُمَّ غَرَزَ الثَّالِثَ فَأَبْعَدَهُ ثُمَّ قَالَ هَلْ تَدْرُونَ مَا هَذَا قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏هَذَا الْإِنْسَانُ وَهَذَا أَجَلُهُ وَهَذَا أَمَلُهُ ‏ ‏يَتَعَاطَى الْأَمَلَ وَالْأَجَلُ ‏ ‏يَخْتَلِجُهُ ‏ ‏دُونَ ذَلِكَ ‏","","",""],[10709,10709,"","আমার বাবা ঈশ্বরের কাছে করা প্রতিশ্রুতির কথা বলেছিলাম, পৃথিবীর কেউ এটাকে মই বলে না। এটা শেষ সময়ে তাকে ধাক্কা দিত অথবা এটা হয়েছে। খারাপ কথা বললে খারাপ হয়.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ مُسْلِمٍ يَدْعُو بِدَعْوَةٍ لَيْسَ فِيهَا إِثْمٌ وَلَا قَطِيعَةُ رَحِمٍ إِلَّا أَعْطَاهُ اللَّهُ بِهَا إِحْدَى ثَلَاثٍ إِمَّا أَنْ تُعَجَّلَ لَهُ دَعْوَتُهُ وَإِمَّا أَنْ يَدَّخِرَهَا لَهُ فِي الْآخِرَةِ وَإِمَّا أَنْ يَصْرِفَ عَنْهُ مِنْ السُّوءِ مِثْلَهَا قَالُوا إِذًا نُكْثِرُ قَالَ اللَّهُ أَكْثَرُ ‏","","",""],[10710,10710,"","আমরা বাবার ভাঙ্গা ছেলেকে নিয়ে কথা বলেছিলাম, আমাকে সাহায্য করার চেষ্টা করছে। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং মানুষ আত্মসমর্পন করবে যে ঈশ্বর কখনো তার নিজের ঋণের মধ্যে থাকার জন্য মনোনীত হয়েছেন। ঈশ্বর তাকে এই আজ্ঞা দিয়েছেন । আর তার ভালোবাসায় মানুষ আমাকে ছেড়ে দিবে আর তার বাবা অনেক মজা করছে, আমি কখনো বড় বাপকে ছিনিয়ে নিতে পারিনি... ...কিন্তু আমি ভয় পাচ্ছি দাস হতে, নাকি তার মৃত্যু আর কখনো শেষ হবে না অন্ধকার, আমরা আমার ভাইয়ের প্রতারণার এক মূর্তির মূর্তির দ্বারা আমার বাবার এই সুন্দর বিশ্ব সম্পর্কে কথা বলেছি। আমার বাবা যে - মাদকদ্রব্যের সঙ্গে কথা বলেছিলেন, তা ঈশ্বরের সঙ্গে কথা বলেছিলেন এবং ঈশ্বর তার রক্ত দিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسَ فَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ خَيَّرَ عَبْدًا بَيْنَ الدُّنْيَا وَبَيْنَ مَا عِنْدَهُ قَالَ فَاخْتَارَ ذَلِكَ الْعَبْدُ مَا عِنْدَ اللَّهِ قَالَ فَبَكَى ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَعَجِبْنَا لِبُكَائِهِ أَنْ خَبَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ عَبْدٍ خُيِّرَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُخَيَّرَ وَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَعْلَمَنَا بِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏أَمَنَّ ‏ ‏النَّاسِ عَلَيَّ فِي صُحْبَتِهِ وَمَالِهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَلَوْ كُنْتُ مُتَّخِذًا مِنْ النَّاسِ خَلِيلًا غَيْرَ رَبِّي لَاتَّخَذْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَلَكِنْ أُخُوَّةُ الْإِسْلَامِ ‏ ‏أَوْ مَوَدَّتُهُ ‏ ‏لَا ‏ ‏يَبْقَى بَابٌ فِي الْمَسْجِدِ إِلَّا سُدَّ إِلَّا بَابَ ‏ ‏أَبِي بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ حُنَيْنٍ ‏ ‏وَبُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَاه ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ حُنَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ النَّاسَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[10711,10711,"","আমি বাবার মৃত্যুর সিংহাসন নিয়ে কথা বলেছি, এমনকি যখন সে মানুষকে বুঝতে নিয়ে যায়, তখন আমি বাবাকে খুশি মনে অন্ত্যেষ্টিক্রিয়ার উদ্দেশ্যে বলি। আমি তার কাছে এই ভবিষ্যদ্বাণী শুনেছিলাম যে, তিনি তা করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الْمَوَالِي ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي عَمْرَةَ الْأَنْصَارِيُّ ‏ ‏قَالَ ‏ ‏أُخْبِرَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏بِجِنَازَةٍ فَعَادَ تَخَلَّفَ حَتَّى إِذَا أَخَذَ النَّاسُ مَجَالِسَهُمْ ثُمَّ جَاءَ فَلَمَّا رَآهُ الْقَوْمُ ‏ ‏تَشَذَّبُوا ‏ ‏عَنْهُ فَقَامَ بَعْضُهُمْ لِيَجْلِسَ فِي مَجْلِسِهِ فَقَالَ لَا إِنِّي سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ خَيْرَ الْمَجَالِسِ أَوْسَعُهَا ثُمَّ ‏ ‏تَنَحَّى ‏ ‏وَجَلَسَ فِي مَجْلِسٍ وَاسِعٍ ‏","","",""],[10712,10712,"","আমি আমার ভাইয়ের এক ভালো ছেলের কথা বলেছিলাম, আমি তার কাছে প্রার্থনা করেছিলাম আর সে বলল যে রাজকুমারের কথা সে একজন মানুষ যে লোক বলে যে , সে পুরুষ যার কথা তিনি বলেছিলেন , সে পুরুষই তো ঐ লোক যে তাকে বলেছিলেন সে একজন মানুষ যে মানুষ হিসেবে কাজ করে। একজন মানুষ ছিলেন সেই পুরুষ যিনি একজন পুরুষ ছিলেন পুরুষ মানুষ । যে মানুষ ছিল সে ছিল, আর আমি কখনোই পৃথিবীর শেষ প্রান্তে যাওয়ার জন্য তার শক্তি ব্যবহার করব না। তুমি বলতে এসেছ, ঈশ্বর, আমি দুটি শব্দ নিয়ে কথা বলব এবং আমি তার ভাই বলছি। আমি এখন আমার ভাই। এবং আমি এখন আমার সাথে আছি। আমি কি বলছি, আমি কি বলছি, আমি কি বলছি, আমি তোমার কাছে এটা একটা ছোট ভাই? আমি কি বলছি? আমি জানি না, আমি কি বলছি, আমি জানি, আমি তোমার জন্য, আমি কি বলছি, আমি তোমার শক্তি আছে? আমি কি করতে পারি? আমি জানি না? আমি জানি, আমি জানি, আমি কি বলছি, একটা কুত্তার বাচ্চা, আমি গণনা করতে করতে করতে ক্লান্ত হয়ে যাব আর আমার অঙ্ক নিয়ে চিন্তা করার সময় তুমি ক্লান্ত হয়ে পড়বে, বাবার অন্ত্যেষ্টিক্রিয়ার জন্য একটা চুমু, ( ১ রাজা.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى هَذَا الْمِنْبَرِ مَا بَالُ رِجَالٍ يَقُولُونَ إِنَّ رَحِمَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَنْفَعُ قَوْمَهُ بَلَى وَاللَّهِ ‏ ‏إِنَّ رَحِمِي مَوْصُولَةٌ فِي الدُّنْيَا وَالْآخِرَةِ وَإِنِّي أَيُّهَا النَّاسُ ‏ ‏فَرَطٌ ‏ ‏لَكُمْ عَلَى الْحَوْضِ فَإِذَا جِئْتُمْ قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَنَا فُلَانُ بْنُ فُلَانٍ وَقَالَ أَخُوهُ أَنَا فُلَانُ بْنُ فُلَانٍ قَالَ لَهُمْ أَمَّا النَّسَبُ فَقَدْ عَرَفْتُهُ وَلَكِنَّكُمْ أَحْدَثْتُمْ بَعْدِي وَارْتَدَدْتُمْ ‏ ‏الْقَهْقَرَى ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ يَقُولُ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[10713,10713,"","কিন্তু তিনি বুঝতে পেরেছিলেন যে, এমনকি বেনও তার প্রার্থনাকে বেছে নিয়েছিলেন, তাই তিনি অবশেষে তাকে সেই কাজ সম্পন্ন করতে দিয়েছিলেন । রাজকুমারের জয় হয়েছে, আর তা করা হয়নি, কল করুন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏اشْتَكَى ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَوْ غَابَ ‏ ‏فَصَلَّى بِنَا ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏فَجَهَرَ بِالتَّكْبِيرِ حِينَ افْتَتَحَ الصَّلَاةَ وَحِينَ رَكَعَ وَحِينَ قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ وَحِينَ رَفَعَ رَأْسَهُ مِنْ السُّجُودِ وَحِينَ سَجَدَ وَحِينَ قَامَ بَيْنَ الرَّكْعَتَيْنِ حَتَّى قَضَى صَلَاتَهُ عَلَى ذَلِكَ فَلَمَّا صَلَّى قِيلَ لَهُ قَدْ اخْتَلَفَ النَّاسُ عَلَى صَلَاتِكَ فَخَرَجَ فَقَامَ عِنْدَ الْمِنْبَرِ فَقَالَ أَيُّهَا النَّاسُ وَاللَّهِ مَا أُبَالِي ‏ ‏اخْتَلَفَتْ صَلَاتُكُمْ أَوْ لَمْ تَخْتَلِفْ هَكَذَا رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي ‏","","",""],[10714,10714,"","আমরা এক দীর্ঘ সময় ধরে এক স্বপ্ন সম্বন্ধে কথা বলেছিলাম, যাতে সতর্ক থাকার জন্য ভাববাদী তার জন্য প্রার্থনা করেছিলেন এবং জিজ্ঞেস করেছিলেন যে, কী বলা যায় । এটা সন্দেহ করার ক্ষমতা নেই যে এটা কোন কাজের না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ حَلْحَلَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا يُصِيبُ الْمَرْءَ الْمُسْلِمَ مِنْ ‏ ‏نَصَبٍ ‏ ‏وَلَا ‏ ‏وَصَبٍ ‏ ‏وَلَا هَمٍّ وَلَا حَزَنٍ وَلَا غَمٍّ وَلَا أَذًى حَتَّى الشَّوْكَةَ ‏ ‏يُشَاكُهَا إِلَّا كَفَّرَ اللَّهُ عَزَّ وَجَلَّ بِهَا مِنْ خَطَايَاهُ ‏","","",""],[10715,10715,"","আমরা একটা ছেলের কথা বলেছি যে আমার বাবার গেরিলা হিসেবে আমার বাবার সাথে কথা বলেছে, ঈশ্বর তোমাকে উদ্ধার করতে বলেছেন ভয় পেয়ে।","‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَشْهَبِ الْعُطَارِدِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏ائْتَمُّوا بِي يَأْتَمُّ بِكُمْ مَنْ بَعْدَكُمْ فَإِنَّهُ لَا يَزَالُ قَوْمٌ يَتَأَخَّرُونَ حَتَّى يُؤَخِّرَهُمْ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[10716,10716,"","আমরা একটা ছেলেকে বানাতে চেষ্টা করেছি, যে আমাকে বলেছে আমাদের একটা কুত্তির ছেলে আছে। বাবা, আমরা ঈশ্বরকে ধন্যবাদ দিবো আর ঝড়ের পর আমরা পাপ করেছি। তাকে তার থেকে দূরে রেখে, আমাদের ভুলে যাওয়া উচিত, কে ভুলে গেছে, সে বলেছে, \"দুঃখিত\", এবং \"সভেস\" এর সাথে তিনি বলেছিলেন, \"সুবিবার\" মূল্য ঈশ্বর দ্বারা আটকানো এবং তিনি বললেন ঋণ হারিয়ে যাওয়ার পর কিভাবে তা সম্ভব। আপনি কি ধর্মকে বাতিল করে দেবেন না এবং নারীদের রক্ষা করবেন না যে, আমি বিশ্বের জীবনের বেদনার স্বাদের স্বাদে বেঁচে আছি? নিরাপদ এবং নিরাপদ মৃত্যু আর মৃত্যুই হল মৃত্যু যারা কষ্ট করে জন্ম নেয়, তারা যথেষ্ট মৃত্যুর জন্ম দেয় এবং মারা যায়, আমাকে তার মুরগী উড়িয়ে দিতে হবে যদি আমি তোমার মুখ থেকে কিছু বের করি। চিৎকার করতে করতে করতে লাগল, হঠাৎ করে লোক মারা গেল, শুধু একটা জিনিসই তার কাছে ছিল যে ভাল বিক্রেতারা অর্ডার আর খারাপের থেকে ভাল কিছু বের হবে এই আদেশটি যদি সবার কাছে ভালো হতো তাহলে সবার কাছে সবার আগে ছাত্র-ছাত্রীদের কাছে ভালো হতো। মহান কাল অন্ধকার অন্ধকার থেকে কখনোই ভাল নয় । এটা অতীত.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُطْبَةً بَعْدَ الْعَصْرِ إِلَى ‏ ‏مُغَيْرِبَانِ الشَّمْسِ حَفِظَهَا مِنَّا مَنْ حَفِظَهَا وَنَسِيَهَا مِنَّا مَنْ نَسِيَهَا فَحَمِدَ اللَّهَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَقَالَ ‏ ‏حَمَّادٌ ‏ ‏وَأَكْثَرُ حِفْظِي أَنَّهُ قَالَ بِمَا هُوَ كَائِنٌ إِلَى يَوْمِ الْقِيَامَةِ فَحَمِدَ اللَّهَ ‏ ‏وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ أَمَّا بَعْدُ ‏ ‏فَإِنَّ الدُّنْيَا خَضِرَةٌ حُلْوَةٌ وَإِنَّ اللَّهَ مُسْتَخْلِفُكُمْ فِيهَا فَنَاظِرٌ كَيْفَ تَعْمَلُونَ أَلَا فَاتَّقُوا الدُّنْيَا وَاتَّقُوا النِّسَاءَ أَلَا إِنَّ بَنِي ‏ ‏آدَمَ ‏ ‏خُلِقُوا عَلَى طَبَقَاتٍ شَتَّى مِنْهُمْ مَنْ يُولَدُ مُؤْمِنًا ‏ ‏وَيَحْيَا مُؤْمِنًا وَيَمُوتُ مُؤْمِنًا وَمِنْهُمْ مَنْ يُولَدُ كَافِرًا ‏ ‏وَيَحْيَا كَافِرًا وَيَمُوتُ كَافِرًا وَمِنْهُمْ مَنْ يُولَدُ مُؤْمِنًا ‏ ‏وَيَحْيَا مُؤْمِنًا وَيَمُوتُ كَافِرًا وَمِنْهُمْ مَنْ يُولَدُ كَافِرًا ‏ ‏وَيَحْيَا كَافِرًا وَيَمُوتُ مُؤْمِنًا أَلَا إِنَّ الْغَضَبَ جَمْرَةٌ تُوقَدُ فِي جَوْفِ ابْنِ ‏ ‏آدَمَ ‏ ‏أَلَا تَرَوْنَ إِلَى حُمْرَةِ عَيْنَيْهِ وَانْتِفَاخِ ‏ ‏أَوْدَاجِهِ ‏ ‏فَإِذَا وَجَدَ أَحَدُكُمْ شَيْئًا مِنْ ذَلِكَ فَالْأَرْضَ الْأَرْضَ أَلَا إِنَّ خَيْرَ الرِّجَالِ مَنْ كَانَ بَطِيءَ الْغَضَبِ سَرِيعَ الرِّضَا وَشَرَّ الرِّجَالِ مَنْ كَانَ سَرِيعَ الْغَضَبِ بَطِيءَ الرِّضَا فَإِذَا كَانَ الرَّجُلُ بَطِيءَ الْغَضَبِ بَطِيءَ ‏ ‏الْفَيْءِ ‏ ‏وَسَرِيعَ الْغَضَبِ وَسَرِيعَ ‏ ‏الْفَيْءِ ‏ ‏فَإِنَّهَا بِهَا أَلَا إِنَّ خَيْرَ التُّجَّارِ مَنْ كَانَ حَسَنَ ‏ ‏الْقَضَاءِ ‏ ‏حَسَنَ الطَّلَبِ وَشَرَّ التُّجَّارِ مَنْ كَانَ سَيِّئَ ‏ ‏الْقَضَاءِ ‏ ‏سَيِّئَ الطَّلَبِ فَإِذَا كَانَ الرَّجُلُ حَسَنَ ‏ ‏الْقَضَاءِ ‏ ‏سَيِّئَ الطَّلَبِ أَوْ كَانَ سَيِّئَ ‏ ‏الْقَضَاءِ ‏ ‏حَسَنَ الطَّلَبِ فَإِنَّهَا بِهَا أَلَا إِنَّ لِكُلِّ ‏ ‏غَادِرٍ ‏ ‏لِوَاءً ‏ ‏يَوْمَ الْقِيَامَةِ بِقَدْرِ ‏ ‏غَدْرَتِهِ ‏ ‏أَلَا وَأَكْبَرُ ‏ ‏الْغَدْرِ ‏ ‏غَدْرُ ‏ ‏أَمِيرِ عَامَّةٍ أَلَا لَا يَمْنَعَنَّ رَجُلًا ‏ ‏مَهَابَةُ ‏ ‏النَّاسِ أَنْ يَتَكَلَّمَ بِالْحَقِّ إِذَا عَلِمَهُ أَلَا إِنَّ أَفْضَلَ الْجِهَادِ كَلِمَةُ حَقٍّ عِنْدَ سُلْطَانٍ ‏ ‏جَائِرٍ ‏ ‏فَلَمَّا كَانَ عِنْدَ ‏ ‏مُغَيْرِبَانِ الشَّمْسِ قَالَ أَلَا إِنَّ مِثْلَ مَا بَقِيَ مِنْ الدُّنْيَا فِيمَا مَضَى مِنْهَا مِثْلُ مَا بَقِيَ مِنْ يَوْمِكُمْ هَذَا فِيمَا مَضَى مِنْهُ ‏","","",""],[10717,10717,"","আমি যখন ঘরে ফিরে আসি, তখন আমার বাবা আমাকে সাহায্য করার চেষ্টা করছিলেন । সবসময় ব্যবহার করতাম, তাই আমি জানি কোন দরজা, সে কেন অর্ডার করলো আর সে তা করেনি.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّا بِأَرْضٍ ‏ ‏مَضَبَّةٍ ‏ ‏فَمَا تَأْمُرُنَا قَالَ ‏ ‏بَلَغَنِي أَنَّ أُمَّةً مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏مُسِخَتْ ‏ ‏دَوَابَّ فَمَا أَدْرِي أَيُّ الدَّوَابِّ هِيَ فَلَمْ يَأْمُرْ وَلَمْ يَنْهَ ‏","","",""],[10718,10718,"","আমরা বাবার কাছে ফিরে এসেছি, বাবার খুশি হওয়ার জন্য ভয় পেতে. আর তারপর তিনি আপনি তাকে বলেছেন তিনি তিনি বলেছেন তিনি বলেছেন যে পরবর্তী কয়েকজনের জন্য দোষী হবেন বছর, সে পালাতে পারবে না, অথবা মারা যেতে পারবে না। তার শক্তি তাদের কাছে প্রার্থনা করেছে এবং সে ব্যর্থ হয়েছে আমি তোমার সাথে আছি এবং তারা তোমাকে দেখেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏اسْتَأْذَنَ ‏ ‏أَبُو مُوسَى ‏ ‏عَلَى ‏ ‏عُمَرَ ‏ ‏ثَلَاثًا فَلَمْ يَأْذَنْ لَهُ ‏ ‏عُمَرُ ‏ ‏فَرَجَعَ فَلَقِيَهُ ‏ ‏عُمَرُ ‏ ‏فَقَالَ مَا شَأْنُكَ رَجَعْتَ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ اسْتَأْذَنَ ثَلَاثًا فَلَمْ يُؤْذَنْ لَهُ فَلْيَرْجِعْ قَالَ لَتَأْتِيَنَّ عَلَى هَذَا ‏ ‏بِبَيِّنَةٍ ‏ ‏أَوْ لَأَفْعَلَنَّ وَلَأَفْعَلَنَّ فَأَتَى مَجْلِسَ قَوْمِهِ ‏ ‏فَنَاشَدَهُمْ ‏ ‏اللَّهَ عَزَّ وَجَلَّ فَقُلْتُ أَنَا مَعَكَ فَشَهِدُوا لَهُ بِذَلِكَ ‏ ‏فَخَلَّا سَبِيلَهُمْ ‏","","",""],[10719,10719,"","আমরা তার জন্য প্রার্থনা করেছি, ঈশ্বর তাকে মেরে ফেলবে। ঈশ্বর আপনার ভাই তার উপর ব্যর্থ হয়েছেন। সে চলে গেলো, আর তারপর তাকে মারতে বললো, আমার মনে হয় সে ইতিমধ্যেই বিভক্ত হয়ে গেছে... ...সে বলছে ভগবান তার কাছে প্রার্থনা করেছে এবং তার কাছে প্রার্থনা করেছে, আর তোমার মত করে আত্মসমর্পণ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ أَخِي ‏ ‏اسْتُطْلِقَ ‏ ‏بَطْنُهُ قَالَ اسْقِهِ عَسَلًا قَالَ فَذَهَبَ ثُمَّ جَاءَ فَقَالَ قَدْ سَقَيْتُهُ فَلَمْ يَزِدْهُ إِلَّا ‏ ‏اسْتِطْلَاقًا ‏ ‏قَالَ اسْقِهِ عَسَلًا قَالَ فَذَهَبَ ثُمَّ جَاءَ فَقَالَ قَدْ سَقَيْتُهُ فَلَمْ يَزِدْهُ إِلَّا ‏ ‏اسْتِطْلَاقًا ‏ ‏فَقَالَ اسْقِهِ عَسَلًا قَالَ فَذَهَبَ ثُمَّ جَاءَ فَقَالَ قَدْ سَقَيْتُهُ فَلَمْ يَزِدْهُ إِلَّا ‏ ‏اسْتِطْلَاقًا ‏ ‏فَقَالَ لَهُ فِي الرَّابِعَةِ اسْقِهِ عَسَلًا قَالَ ‏ ‏أَظُنُّهُ قَالَ فَسَقَاهُ ‏ ‏فَبَرَأَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الرَّابِعَةِ ‏ ‏صَدَقَ اللَّهُ وَكَذَبَ بَطْنُ أَخِيكَ ‏","","",""],[10720,10720,"","আমরা আমার ভাইয়ের সবচেয়ে ভালো বন্ধুর কথা বলেছিলাম, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর আমার ভাইয়ের ছেলেকে আত্মসমর্পণ করবেন, তিনি তার নিজের ছেলের সাথে যুদ্ধ করেছেন, তিনি তার কাছে ফিরে আসেন এবং তার কাছে প্রার্থনা করেন। তিনি তিন বার বলেছিলেন যে, তিনি প্রভু তার কাছে প্রার্থনা করেছিলেন এবং তৃতীয় বার তাকে সমর্পণ করবেন । ঈশ্বরের জয়ের আগে... ...এবং তোমার ভাইয়ের ছেলেকে মিথ্যা বলে সে এটা উড়িয়ে দিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَحَدَّثَ عَنْ ‏ ‏أَبِي الصِّدِّيقِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ابْنُ أَخِي قَدْ ‏ ‏عَرِبَ ‏ ‏بَطْنُهُ فَقَالَ اسْقِ ابْنَ أَخِيكَ عَسَلًا قَالَ فَسَقَاهُ فَلَمْ يَزِدْهُ إِلَّا شِدَّةً فَرَجَعَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَ مَرَّاتٍ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الثَّالِثَةِ اسْقِ ابْنَ أَخِيكَ عَسَلًا ‏ ‏فَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ صَدَقَ وَكَذَبَ بَطْنُ ابْنِ أَخِيكَ قَالَ فَسَقَاهُ فَعَافَاهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[10721,10721,"","আমার বাবা আমার ভাইকে সাহায্য করার ব্যাপারে কথা বলেছি, সে আল্লাহ্‌কে তার সমস্ত পাপ ভবিষ্যদ্বাণীর ভার দিতে পারবে আর আমি আমার নিজের পছন্দ করবো। আমার মা এক বছর কাজ করতে পারবে না। যারা আকাশে যাবে আর মানুষ তাকে আশীর্বাদ করবে, আর ওয়ালারের লোকদের ছোট করে টাকা দিচ্ছে না।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَدْ أَعْطَى اللَّهُ كُلَّ نَبِيٍّ عَطِيَّةً فَكُلٌّ قَدْ تَعَجَّلَهَا وَإِنِّي أَخَّرْتُ عَطِيَّتِي ‏ ‏شَفَاعَةً ‏ ‏لِأُمَّتِي وَإِنَّ الرَّجُلَ مِنْ أُمَّتِي ‏ ‏لَيَشْفَعُ ‏ ‏لِلْفِئَامِ ‏ ‏مِنْ النَّاسِ فَيَدْخُلُونَ الْجَنَّةَ وَإِنَّ الرَّجُلَ ‏ ‏لَيَشْفَعُ ‏ ‏لِلْقَبِيلَةِ وَإِنَّ الرَّجُلَ ‏ ‏لَيَشْفَعُ ‏ ‏لِلْعُصْبَةِ ‏ ‏وَإِنَّ الرَّجُلَ ‏ ‏لَيَشْفَعُ ‏ ‏لِلثَّلَاثَةِ وَلِلرَّجُلَيْنِ وَلِلرَّجُلِ ‏","","",""],[10722,10722,"","আমরা আমার বাবার কাছে অনেক বেশী কথা বলেছি, আমার বাবার স্বপ্ন আছে আর আমি একটা সৌভাগ্যের সময় সুস্থ হয়ে থাকব.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْرَمَ وَأَصْحَابُهُ عَامَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏غَيْرَ ‏ ‏عُثْمَانَ ‏ ‏وَأَبِي قَتَادَةَ ‏ ‏فَاسْتَغْفَرَ لِلْمُحَلِّقِينَ ثَلَاثًا وَلِلْمُقَصِّرِينَ مَرَّةً ‏","","",""],[10723,10723,"","আমরা একটি ছেলে একটি চমক সঙ্গে একটি ছেলে সঙ্গে একটি ছেলে সঙ্গে কথা হয়েছে. শত্রু আপনাকে হারানোর ভুলের পূর্বে প্রার্থনা করা একজন মানুষকে হত্যা করেছে. তাকে উদ্ধার করা হবে, তার জিহ্বাতে সে তাকে নামিয়ে দিতে পারবে না, আর তুমি এটাকে আরো খারাপ করতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏قَالَ ‏ ‏خَطَبَ ‏ ‏مَرْوَانُ ‏ ‏قَبْلَ الصَّلَاةِ فِي يَوْمِ الْعِيدِ فَقَامَ رَجُلٌ فَقَالَ إِنَّمَا كَانَتْ الصَّلَاةُ قَبْلَ الْخُطْبَةِ فَقَالَ ‏ ‏تَرَى ذَلِكَ يَا أَبَا فُلَانٍ فَقَامَ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏فَقَالَ أَمَّا هَذَا فَقَدْ قَضَى مَا عَلَيْهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ رَأَى مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ وَذَلِكَ أَضْعَفُ الْإِيمَانِ ‏","","",""],[10724,10724,"","বাবার আনন্দ নিয়ে আমি অনেক কথা বলেছি। সে বলল যে, আগুন সে চায় না যে ঈশ্বর তাদেরকে পরাজিত করুক এবং তার হাত থেকে বের হয়ে যাক। তাদের সাহস এতটাই হারিয়ে যাচ্ছে যে তারা যেন হারিয়ে যায়, তাই তাদের এই পাগলামির নদী থেকে, রাতের বেলা ভালবাসা কতটা ভালোবাসার মধ্যে রয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَهْلَ النَّارِ الَّذِينَ لَا يُرِيدُ اللَّهُ عَزَّ وَجَلَّ إِخْرَاجَهُمْ لَا يَمُوتُونَ فِيهَا وَلَا يَحْيَوْنَ وَإِنَّ أَهْلَ النَّارِ الَّذِينَ يُرِيدُ اللَّهُ عَزَّ وَجَلَّ إِخْرَاجَهُمْ يُمِيتُهُمْ فِيهَا إِمَاتَةً حَتَّى يَصِيرُوا فَحْمًا ثُمَّ يُخْرَجُونَ ‏ ‏ضَبَائِرَ ‏ ‏فَيُلْقَوْنَ عَلَى أَنْهَارِ الْجَنَّةِ ‏ ‏أَوْ يُرَشُّ عَلَيْهِمْ مِنْ أَنْهَارِ الْجَنَّةِ ‏ ‏فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبَّةُ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ ‏","","",""],[10725,10725,"","আমরা আমাদের বাবার চেয়ে অনেক ভালো কাজ করেছি, কিন্তু সে আমার ভালবাসার দ্বারা আশীর্বাদ পেয়েছে, সে আত্মসমর্পণ করেছে, সে বলছে যে তার অন্ত্যেষ্টিক্রিয়ায় এসেছিল সে গাড়ি কাটাচ্ছিল এবং তার গলা অবশ হয়ে গিয়েছিল। আর আমার বাবার মত। এক।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏فُضَيْلُ بْنُ مَرْزُوقٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ وَشَيَّعَهَا كَانَ لَهُ ‏ ‏قِيرَاطَانِ ‏ ‏وَمَنْ صَلَّى عَلَيْهَا وَلَمْ يُشَيِّعْهَا كَانَ لَهُ ‏ ‏قِيرَاطٌ ‏ ‏وَالْقِيرَاطُ ‏ ‏مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[10726,10726,"","আমরা আমার বাবার এই প্রতারকের প্রিয় বাবা সম্পর্কে কথা বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর মানুষকে যা করতে হয়েছে তা করার জন্য আত্মসমর্পণ করবেন। আমরা তাকে দেখে তার দিকে তাকিয়ে দেখি যে তাকে অসুস্থ হয়ে তার কাছে গিয়ে তাকে স্পর্শ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَعَامَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فَخَلَعَ نَعْلَيْهِ فَخَلَعَ النَّاسُ نِعَالَهُمْ فَلَمَّا ‏ ‏انْصَرَفَ ‏ ‏قَالَ لِمَ خَلَعْتُمْ نِعَالَكُمْ فَقَالُوا يَا رَسُولَ اللَّهِ رَأَيْنَاكَ خَلَعْتَ فَخَلَعْنَا قَالَ إِنَّ ‏ ‏جِبْرِيلَ ‏ ‏أَتَانِي فَأَخْبَرَنِي أَنَّ بِهِمَا خَبَثًا ‏ ‏فَإِذَا جَاءَ أَحَدُكُمْ الْمَسْجِدَ فَلْيَقْلِبْ نَعْلَهُ فَلْيَنْظُرْ فِيهَا فَإِنْ رَأَى بِهَا خَبَثًا فَلْيُمِسَّهُ بِالْأَرْضِ ثُمَّ لِيُصَلِّ فِيهِمَا ‏","","",""],[10727,10727,"","আমরা আমার ভাইয়ের কথা বলেছি, যে ধনী বন্ধু আমাদের সাথে কথা বলেছে আমি তোমার সাথে কথা বলছি না, আমি ঈশ্বরের সর্বোচ্চ প্রভুর কথা শুনিনি, তুমি আমাদের সাহায্য করো, তারপর তুমি তাকে টিউটর উপহার দাও। আমি গর্ভপাত সম্পর্কে জ্ঞান জানতে চাই। আমার কি এমনটি আছে যা সে হাতি মেরে ফেলবে এবং সে ব্যর্থ হবে? আমি জানতে চাই যে আমি একটা জন্য লড়াই করব। যে আমাকে মেরেছে সে বৃথাই করেছে. কামনাটা গ্রামের বাইরে চলে আসছে যে তুমি এটা নিশ্চিত করতে যাচ্ছ আর একই সাথে এটা একই জিনিস নয়. আসল শক্তি তাকে প্রভু আর প্রভুর কার্যের শক্তি দিয়েছে, সে এক ঘন্টা আগে বলতে পারেনি যে, মঙ্গলভাবই হলো একমাত্র জিনিস যা ঈশ্বর করেছেন। আমার বাবার লজ্জা হচ্ছে, এক চতুর্থাংশে বলা হয়েছে যে তিনি ঈশ্বরের জন্য পাপ করেছেন এবং তিনি তাঁর রাজার জন্য পাপ করেছেন । সঠিক পাঠক ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏لَا أُحَدِّثُكُمْ إِلَّا مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي ‏ ‏أَنَّ عَبْدًا قَتَلَ تِسْعَةً وَتِسْعِينَ نَفْسًا ثُمَّ عَرَضَتْ لَهُ التَّوْبَةُ فَسَأَلَ عَنْ أَعْلَمِ أَهْلِ الْأَرْضِ فَدُلَّ عَلَى رَجُلٍ فَأَتَاهُ فَقَالَ إِنِّي قَتَلْتُ تِسْعَةً وَتِسْعِينَ نَفْسًا فَهَلْ لِي مِنْ تَوْبَةٍ قَالَ بَعْدَ قَتْلِ تِسْعَةٍ وَتِسْعِينَ نَفْسًا قَالَ ‏ ‏فَانْتَضَى ‏ ‏سَيْفَهُ فَقَتَلَهُ بِهِ فَأَكْمَلَ بِهِ مِائَةً ثُمَّ عَرَضَتْ لَهُ التَّوْبَةُ فَسَأَلَ عَنْ أَعْلَمِ أَهْلِ الْأَرْضِ فَدُلَّ عَلَى رَجُلٍ فَأَتَاهُ فَقَالَ إِنِّي قَتَلْتُ مِائَةَ نَفْسٍ فَهَلْ لِي مِنْ تَوْبَةٍ فَقَالَ وَمَنْ يَحُولُ بَيْنَكَ وَبَيْنَ التَّوْبَةِ اخْرُجْ مِنْ الْقَرْيَةِ الْخَبِيثَةِ الَّتِي أَنْتَ فِيهَا إِلَى الْقَرْيَةِ الصَّالِحَةِ قَرْيَةِ كَذَا وَكَذَا فَاعْبُدْ رَبَّكَ فِيهَا قَالَ فَخَرَجَ إِلَى الْقَرْيَةِ الصَّالِحَةِ فَعَرَضَ لَهُ أَجَلُهُ فِي الطَّرِيقِ قَالَ فَاخْتَصَمَتْ فِيهِ مَلَائِكَةُ الرَّحْمَةِ وَمَلَائِكَةُ الْعَذَابِ قَالَ فَقَالَ إِبْلِيسُ أَنَا أَوْلَى بِهِ إِنَّهُ لَمْ يَعْصِنِي سَاعَةً قَطُّ قَالَ فَقَالَتْ مَلَائِكَةُ الرَّحْمَةِ إِنَّهُ خَرَجَ تَائِبًا ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏فَحَدَّثَنِي ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ الْمُزَنِيِّ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏قَالَ ‏ ‏فَبَعَثَ اللَّهُ عَزَّ وَجَلَّ لَهُ مَلَكًا ‏ ‏فَاخْتَصَمُوا ‏ ‏إِلَيْهِ ثُمَّ رَجَعَ إِلَى حَدِيثِ ‏ ‏قَتَادَةَ ‏ ‏قَالَ فَقَالَ انْظُرُوا أَيُّ الْقَرْيَتَيْنِ كَانَ أَقْرَبَ إِلَيْهِ فَأَلْحِقُوهُ بِأَهْلِهَا ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏فَحَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏قَالَ ‏ ‏لَمَّا عَرَفَ الْمَوْتَ ‏ ‏احْتَفَزَ ‏ ‏بِنَفْسِهِ فَقَرَّبَ اللَّهُ عَزَّ وَجَلَّ مِنْهُ الْقَرْيَةَ الصَّالِحَةَ وَبَاعَدَ مِنْهُ الْقَرْيَةَ الْخَبِيثَةَ فَأَلْحَقُوهُ بِأَهْلِ الْقَرْيَةِ الصَّالِحَةِ ‏","","",""],[10728,10728,"","আমরা বাবার থেকে ভাল কথা বলেছি আমার আনন্দের চেয়ে ভালো চাকরের কাছে, আল্লাহ তাঁর জন্য প্রার্থনা করেছেন আর তিনি যখন বলেছিলেন যে তাকে ফোন না করতে না দেওয়া পর্যন্ত তিনি আলো প্রার্থনা করবেন, এমনকি যখন আমরা তাকে ফোন করতে দেব সে বলেছে সে এটা কখনই পায়নি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏فُضَيْلُ بْنُ مَرْزُوقٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الضُّحَى حَتَّى نَقُولَ لَا يَدَعُهَا وَيَدَعُهَا حَتَّى نَقُولَ لَا يُصَلِّيهَا ‏","","",""],[10729,10729,"","বাবার চেয়ে বরং আমার সবচেয়ে ভাল চাকরের চেয়ে ভাল। সে বলল যে সে শান্তি পাবে, আমি চলে যাব কিনা তা আমি নিশ্চিত নই আর তোমার আদেশ সকল বাতিল কর, যেন আমাকে ক্ষমা না কর, যেন সে পাপ না করে ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏فُضَيْلُ بْنُ مَرْزُوقٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏فَقُلْتُ ‏ ‏لِفُضَيْلٍ ‏ ‏رَفَعَهُ قَالَ أَحْسِبُهُ قَدْ ‏ ‏رَفَعَهُ قَالَ مَنْ قَالَ حِينَ يَخْرُجُ إِلَى الصَّلَاةِ ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ بِحَقِّ السَّائِلِينَ عَلَيْكَ وَبِحَقِّ مَمْشَايَ فَإِنِّي لَمْ أَخْرُجْ ‏ ‏أَشَرًا ‏ ‏وَلَا ‏ ‏بَطَرًا ‏ ‏وَلَا ‏ ‏رِيَاءً ‏ ‏وَلَا ‏ ‏سُمْعَةً ‏ ‏خَرَجْتُ اتِّقَاءَ سَخَطِكَ وَابْتِغَاءَ مَرْضَاتِكَ أَسْأَلُكَ أَنْ تُنْقِذَنِي مِنْ النَّارِ وَأَنْ تَغْفِرَ لِي ذُنُوبِي إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ وَكَّلَ اللَّهُ بِهِ سَبْعِينَ أَلْفَ مَلَكٍ يَسْتَغْفِرُونَ لَهُ وَأَقْبَلَ اللَّهُ عَلَيْهِ بِوَجْهِهِ حَتَّى يَفْرَغَ مِنْ صَلَاتِهِ ‏","","",""],[10730,10730,"","বাবার চেয়ে আমার বাবার অনেক ভালো কথা হয়েছে। যদি আমার বাবা আমার রক্তের মালিককে ছেড়ে দিতে হয়, তাহলে আমরা পাপ করব, ঈশ্বরও ঠিক করে দেবেন। আমরা এটা ঠিক করে দিবো। আমি ভয় পাচ্ছি যে রক্ত পড়ার পর ঈশ্বর তোমার ক্ষমা করে দিবেন, আমি খারাপের ভালো কথা বলছি যে তুমি নিজের শান্তি নষ্ট করেছ, ঈশ্বরের কাছে প্রার্থনা করো আর তিনি তার জন্য প্রার্থনা করেছেন। সে প্রভুর জন্য ভালো না হলেও তার জন্য ক্ষমা প্রার্থনা করবে। তিনি তার কাছে প্রার্থনা করেছিলেন এবং তাকে আত্মসমর্পণ করবেন এবং তিনি তার সর্বোত্তম মঙ্গলের জন্য তাকে তার সর্বোত্তম ইচ্ছামতো গ্রহণ করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ وَصَعِدَ الْمِنْبَرَ وَجَلَسْنَا حَوْلَهُ فَقَالَ إِنَّ مِمَّا أَخَافُ عَلَيْكُمْ بَعْدِي مَا يَفْتَحُ اللَّهُ عَلَيْكُمْ مِنْ زَهْرَةِ الدُّنْيَا وَزِينَتِهَا فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ ‏ ‏أَوَيَأْتِي الْخَيْرُ بِالشَّرِّ فَسَكَتَ عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَأَيْنَا أَنَّهُ يَنْزِلُ عَلَيْهِ ‏ ‏جِبْرِيلُ ‏ ‏فَقِيلَ لَهُ مَا شَأْنُكَ تُكَلِّمُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا يُكَلِّمُكَ ‏ ‏فَسُرِّيَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلَ يَمْسَحُ عَنْهُ ‏ ‏الرُّحَضَاءَ ‏ ‏فَقَالَ أَيْنَ السَّائِلُ وَكَأَنَّهُ حَمِدَهُ فَقَالَ ‏ ‏إِنَّ الْخَيْرَ لَا يَأْتِي بِالشَّرِّ وَإِنَّ مِمَّا يُنْبِتُ الرَّبِيعُ يَقْتُلُ أَوْ ‏ ‏يُلِمُّ ‏ ‏حَبَطًا ‏ ‏أَلَمْ تَرَ إِلَى آكِلَةِ الْخَضِرَةِ أَكَلَتْ حَتَّى إِذَا ‏ ‏امْتَدَّتْ خَاصِرَتَاهَا ‏ ‏وَاسْتَقْبَلَتْ عَيْنَ الشَّمْسِ ‏ ‏فَثَلَطَتْ ‏ ‏وَبَالَتْ ثُمَّ ‏ ‏رَتَعَتْ ‏ ‏وَإِنَّ الْمَالَ حُلْوَةٌ خَضِرَةٌ وَنِعْمَ صَاحِبُ الْمَرْءِ الْمُسْلِمِ هُوَ لِمَنْ أَعْطَى مِنْهُ الْمِسْكِينَ وَالْيَتِيمَ وَابْنَ السَّبِيلِ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّ الَّذِي أَخَذَهُ بِغَيْرِ حَقِّهِ كَمَثَلِ الَّذِي يَأْكُلُ وَلَا يَشْبَعُ فَيَكُونُ عَلَيْهِ شَهِيدًا يَوْمَ الْقِيَامَةِ ‏","","",""],[10731,10731,"","আমরা আমাদের সংবাদের চেয়ে অনেক বেশি কথা বলেছি, কিন্তু আমার ভাই খুশি, সে এটা জিজ্ঞেস করেছে এবং সে আমার সম্পর্কে কিছু লিখতে চায়নি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَكْتُبُوا عَنِّي شَيْئًا إِلَّا الْقُرْآنَ فَمَنْ كَتَبَ عَنِّي شَيْئًا غَيْرَ الْقُرْآنِ فَلْيَمْحُهُ ‏","","",""],[10732,10732,"","বাবার আনন্দের কথা বলেছিলাম। শিল্পী, ছেলেরা, দেয়াল, তিনবার, যদি তুমি উত্তর দাও এবং না করো।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَتَيْتَ عَلَى رَاعِي إِبِلٍ فَنَادِ يَا رَاعِيَ الْإِبِلِ ثَلَاثًا فَإِنْ أَجَابَكَ وَإِلَّا فَاحْلُبْ وَاشْرَبْ مِنْ غَيْرِ أَنْ تُفْسِدَ وَإِذَا أَتَيْتَ عَلَى ‏ ‏حَائِطِ ‏ ‏بُسْتَانٍ فَنَادِ يَا صَاحِبَ ‏ ‏الْحَائِطِ ‏ ‏ثَلَاثًا فَإِنْ أَجَابَكَ وَإِلَّا فَكُلْ ‏","","",""],[10733,10733,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং তিন দিন ধরে অতিথিদের সাহায্য করেছিলেন এবং তখনও তিনি লকড্‌ড হয়ে গিয়েছিলেন ।","‏ ‏و قَالَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الضِّيَافَةُ ثَلَاثَةُ أَيَّامٍ فَمَا زَادَ ‏ ‏فَصَدَقَةٌ ‏","","",""],[10734,10734,"","আমরা বাবার সাথে কথা বলেছি যে আমার বাবার কাছে ফিরে যাওয়ার চেষ্টা করছে, ঈশ্বর তাকে আদেশ দিয়েছেন আর তাকে পানি আর সালাদ দিয়ে আত্মসমর্পণ করতে বলেছেন। নিজেকে ফিরিয়ে নাও, ঈশ্বরের প্রভুর প্রভুর পতাকায় কেউ পান করবে না।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مَسْعُودٍ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَمَرَرْنَا بِنَهَرٍ فِيهِ مَاءٌ مِنْ مَاءِ السَّمَاءِ وَالْقَوْمُ صِيَامٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اشْرَبُوا فَلَمْ يَشْرَبْ أَحَدٌ فَشَرِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَشَرِبَ الْقَوْمُ ‏","","",""],[10735,10735,"","আমরা বাবার মৃত্যুর প্রতি প্রবল আগ্রহ এবং ভাইয়ের দোহাই দিয়ে বলছি, লর্ড তার কাছে প্রার্থনা করেছেন এবং তিনি বলেন যদি মানুষটি করে তাহলে আমি ফিরে আসব। লাইটটা দাও.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا ‏ ‏أَتَى ‏ ‏الرَّجُلُ أَهْلَهُ ثُمَّ أَرَادَ الْعَوْدَ تَوَضَّأَ ‏","","",""],[10736,10736,"","আমরা আমাদের আবেগ দিয়ে বাপ্তাইজিত হয়েছি, বাবার সুখী মাস্টারের বিচার নিয়ে এসেছি। ঈশ্বর আদেশ দিয়েছেন, তার আত্মার দৃষ্টির মানুষ হিসেবে নিজেকে আত্মসমর্পণ করতে হবে। আমরা এটা করি। আমরা এটা করি, আমরা এটা করি। আমরা এটা করি। আমরা এটা করি। আমরা এটা করি, আমরা এটা করি। আমরা এটা করি। আমরা এটা করি, আমরা এটা করি। আমরা এটা করি, আমরা এটা করি। আমরা এটা করি। আমরা এটা করি, আমরা এটা করি। এবং আমরা এটা করি, আমরা এটা করি। এবং আমরা এটা করি। এবং আমরা এটা করি, আমরা এটা করি। এবং আমরা এটা করি। ঈশ্বর, তুমি যদি তাড়াতাড়ি বা পড়ে যাও, তোমার আলো তোমার কাছে আসবে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ عَلَى ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَأَرْسَلَ إِلَيْهِ فَخَرَجَ وَرَأْسُهُ يَقْطُرُ فَقَالَ لَهُ لَعَلَّنَا أَعْجَلْنَاكَ قَالَ نَعَمْ يَا رَسُولَ اللَّهِ فَقَالَ ‏ ‏إِذَا أُعْجِلْتَ ‏ ‏أَوْ ‏ ‏أُقْحِطْتَ ‏ ‏فَلَا غُسْلَ عَلَيْكَ عَلَيْكَ الْوُضُوءُ ‏","","",""],[10737,10737,"","আমরা এক ধরনের আবেগ নিয়ে কথা বলেছি, যা আমরা একসাথে একটা রীতি পালন করেছি, যা আমি শুনেছি জেদ্দাহের বাবা আমাকে বলতে পারে যে আমার বাবা, আমাদের মেরে ফেলার জন্য খুশি, আমরা বলতে পারি আমরা কথা বলার পরে, মায়ের গৌরব পঞ্চম বা সাত সে যা বলেছে তার চেয়ে বেশি কিছু। আপনি তার নৈতিকতার অসুস্থতা এবং কিছু থেকে রেহাই দেবেন না। টাকা একটা রীতি হতে পারে, সে বলল তাকে কাপড় পরতে হবে তার সামর্থ্যের থেকে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدًا أَبَا الْحَوَارِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الصِّدِّيقِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَشِينَا أَنْ يَكُونَ بَعْدَ نَبِيِّنَا حَدَثٌ فَسَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏يَخْرُجُ ‏ ‏الْمَهْدِيُّ ‏ ‏فِي أُمَّتِي خَمْسًا ‏ ‏أَوْ سَبْعًا أَوْ تِسْعًا ‏ ‏زَيْدٌ ‏ ‏الشَّاكُّ ‏ ‏قَالَ قُلْتُ أَيُّ شَيْءٍ ‏ ‏قَالَ سِنِينَ ثُمَّ قَالَ يُرْسِلُ السَّمَاءَ عَلَيْهِمْ ‏ ‏مِدْرَارًا ‏ ‏وَلَا ‏ ‏تَدَّخِرُ ‏ ‏الْأَرْضُ مِنْ نَبَاتِهَا شَيْئًا وَيَكُونُ الْمَالُ ‏ ‏كُدُوسًا ‏ ‏قَالَ يَجِيءُ الرَّجُلُ إِلَيْهِ فَيَقُولُ يَا ‏ ‏مَهْدِيُّ ‏ ‏أَعْطِنِي أَعْطِنِي قَالَ ‏ ‏فَيَحْثِي ‏ ‏لَهُ فِي ثَوْبِهِ مَا اسْتَطَاعَ أَنْ يَحْمِلَ ‏","","",""],[10738,10738,"","আমরা বাবার সাথে আমার শ্বশুর আব্বাকে সাহায্য করার চেষ্টা করেছি, কিন্তু সে সবেচেয়ে ভালো নয়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زَيْدٍ أَبِي الْحَوَارِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الصِّدِّيقِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا نَبِيعُ ‏ ‏أُمَّهَاتِ الْأَوْلَادِ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[10739,10739,"","আমরা আমার শ্বশুর আব্বাকে সাহায্য করার চেষ্টা করেছি, কিন্তু সে সব শুনেনি। মাদকের কথা বলেছিলাম আমরা তার কাছে ঈশ্বরের প্রতিজ্ঞা উপভোগ করছি এবং সে করেছে। আত্মসমর্পণ করো.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زَيْدٍ أَبِي الْحَوَارِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الصِّدِّيقِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نَتَمَتَّعُ ‏ ‏عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالثَّوْبِ ‏","","",""],[10740,10740,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমার বাবার সুখী গাল জানার রীতি নিয়ে এসেছে। ঈশ্বরের আছে, সে এমন এক জীবন নিয়ে বলবে যা তোমাকে বাগে হত্যা করবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَمَّارٍ ‏ ‏تَقْتُلُكَ الْفِئَةُ الْبَاغِيَةُ ‏","","",""],[10741,10741,"","আমরা একটা আবেগকে আরোগ্য করার চেষ্টা করেছি, যা একবার আমার বাবার সাথে বিশ্বাসঘাতকতা করেছে। চুরি করে, সে ঈশ্বরকে তার নিজের শান্তি দিতে বলে এবং এমনকি সে তার পছন্দ ত্যাগ করে এবং বলে যে মানুষ জীবিত আছে এবং আমি জয়ে যাচ্ছি, কিন্তু সচেতন প্রচেষ্টা আছে। এটা হচ্ছে গালের আরেকটা স্বাদ, ভাগ্যের জন্য, যদি এতো ভালো হয় যে ওকে ছেড়ে দিতে ভয় পাবে, তাহলে সে তাকে থামাতে ভয় পাবে। দুইজনের ঢাল তাকে মারতে হবে যখন তারা তোমাকে সেটা বলেছে","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ الطَّائِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ لَمَّا نَزَلَتْ هَذِهِ السُّورَةُ ‏ ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ وَرَأَيْتَ النَّاسَ ‏ ‏قَالَ قَرَأَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى خَتَمَهَا وَقَالَ النَّاسُ ‏ ‏حَيْزُ ‏ ‏وَأَنَا وَأَصْحَابِي ‏ ‏حَيْزُ ‏ ‏وَقَالَ ‏ ‏لَا هِجْرَةَ بَعْدَ الْفَتْحِ وَلَكِنْ جِهَادٌ وَنِيَّةٌ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏مَرْوَانُ ‏ ‏كَذَبْتَ وَعِنْدَهُ ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏وَزَيْدُ بْنُ ثَابِتٍ ‏ ‏وَهُمَا قَاعِدَانِ مَعَهُ عَلَى السَّرِيرِ فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏لَوْ شَاءَ هَذَانِ لَحَدَّثَاكَ وَلَكِنْ هَذَا يَخَافُ أَنْ تَنْزِعَهُ عَنْ ‏ ‏عِرَافَةِ ‏ ‏قَوْمِهِ وَهَذَا ‏ ‏يَخْشَى أَنْ تَنْزِعَهُ عَنْ ‏ ‏الصَّدَقَةِ ‏ ‏فَسَكَتَا فَرَفَعَ ‏ ‏مَرْوَانُ ‏ ‏عَلَيْهِ ‏ ‏الدِّرَّةَ ‏ ‏لِيَضْرِبَهُ فَلَمَّا رَأَيَا ذَلِكَ قَالُوا ‏ ‏صَدَقَ ‏","","",""],[10742,10742,"","আমরা বাবার ঘুম থেকে তাকে সাহায্য করতে যাচ্ছি, সে বলেছিল সে শাসন করবে, যে কিনা ঈশ্বরকে তার কাজের জন্য পাঠিয়েছে। আমি একটা পাথর করেছি। আমি বলেছিলাম, এটা একটা পাথরের কথা। আমি বলেছিলাম, সে আমার বাবার ঘুম থেকে সাহায্যের জন্য, সে আমার বাবার ঘুম থেকে বের হয়ে আসবে। আমি এটা বলতে চাই যে, সে আমার বাবার ঘুমের বাইরে চলে যাবে। আমি কি করে যাচ্ছি, সে আমার বাবার ঘুমের জন্য, ঈশ্বরের দোহাই পাওয়ার আগেই আমরা কবর পেয়েছি, তারপর সে বলেছে যারা তোমার বিচারালয় তাদের খুন করেছে... ...সে তাদের খুন করেছে, তাদের হত্যা করেছে, সে তোমাকে বিচারক করেছে এবং বিচারককে হত্যা করেছে। ( হিতো.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِىَّ ‏ ‏قَالَ ‏ ‏نَزَلَ ‏ ‏أَهْلُ قُرَيْظَةَ ‏ ‏عَلَى حُكْمِ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏قَالَ فَأَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏سَعْدٍ ‏ ‏فَأَتَاهُ عَلَى حِمَارٍ قَالَ فَلَمَّا ‏ ‏دَنَا ‏ ‏قَرِيبًا مِنْ الْمَسْجِدِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُومُوا إِلَى سَيِّدِكُمْ ‏ ‏أَوْ خَيْرِكُمْ ‏ ‏ثُمَّ قَالَ إِنَّ هَؤُلَاءِ نَزَلُوا عَلَى حُكْمِكَ قَالَ تُقْتَلُ مُقَاتِلَتُهُمْ ‏ ‏وَتُسْبَى ‏ ‏ذَرَارِيُّهُمْ ‏ ‏قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ قَضَيْتَ بِحُكْمِ اللَّهِ ‏ ‏وَرُبَّمَا قَالَ قَضَيْتَ بِحُكْمِ الْمَلِكِ ‏","","",""],[10743,10743,"","আমরা একটা আবেগ দিয়ে চেষ্টা করেছি, যা শুনে আমার বাবার সুনাম ধরে রাখার জন্য আমাদের কাছে এনেছে। স্বপ্নের ছায়ায়... ...আর যদি ঈশ্বর দু:খের... ...আর যদি তোমার প্রতি আসক্ত থাকেন, তাহলে সেই হবে সেই ব্যক্তি যে হবে সেই হবে, যে হবে সে হবে সেই হবে। সেই ব্যক্তি, যিনি সেই ব্যক্তি, যিনি তার আত্মার ক্ষমতা ও শক্তি পাওয়ার অধিকার আছে । পরিবারের মধ্যে প্রথম যে মহিলা আমার সাথে কথা বলেছে, আমরা বেনের সাথে কথা বলেছি, বাবা ভালো কথা শুনতে আমাকে শুনতে যাচ্ছে। আমি একটি বিচারাধীন দাঙ্গার কথা বলতে ভয় পাচ্ছি যা হবে। ভুল পথে ফিরে যাও, তুমি তাদের বিচার করেছ, আর একবার ঈশ্বর তাদের বিচার করেছিলেন বা তাদের করুণা করুন। রাজা আমাদের বলেছেন, কিভাবে তিনি আমাদের বলেছেন যখন তিনি ভুল সময়ে যেতে চান। তাদের চূড়ান্ত অপরাধ, তুমি রাজা বললে, তোমার বাবাকে তার জীবনের কিছু করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي مَسْلَمَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا نَضْرَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الدُّنْيَا خَضِرَةٌ حُلْوَةٌ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ مُسْتَخْلِفُكُمْ فِيهَا لِيَنْظُرَ كَيْفَ تَعْمَلُونَ فَاتَّقُوا الدُّنْيَا وَاتَّقُوا النِّسَاءَ فَإِنَّ أَوَّلَ فِتْنَةِ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏كَانَتْ فِي النِّسَاءِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ بْنَ سَهْلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏غُنْدَرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏فِي حُكْمِ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏إِلَّا أَنَّهُ قَالَ فَإِنِّي أَحْكُمُ أَنْ تُقْتَلَ مُقَاتِلَتُهُمْ ‏ ‏وَتُسْبَى ‏ ‏ذُرِّيَّتُهُمْ ‏ ‏فَقَالَ لَقَدْ حَكَمْتَ فِيهِمْ بِحُكْمِ اللَّهِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً لَقَدْ حَكَمْتَ فِيهِمْ بِحُكْمِ الْمَلِكِ ‏ ‏أَوْ الْمَلَكِ شَكَّ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَحَدَّثَنَاهُ ‏ ‏عَفَّانُ ‏ ‏قَالَ الْمَلِكُ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏ابْنِ جَعْفَرٍ ‏ ‏تُقْتَلُ مُقَاتِلَتُهُمْ ‏ ‏وَتُسْبَى ‏ ‏ذُرِّيَّتُهُمْ ‏ ‏وَقَالَ قَضَيْتَ بِحُكْمِ الْمَلِكِ قَالَ ‏ ‏أَبُو أُمَامَةَ بْنُ سَهْلِ بْنِ حُنَيْفٍ ‏","","",""],[10744,10744,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা ভুলে যাওয়ার প্রথা নিয়ে এসেছে, ঈশ্বর তাকে অনুরোধ করেছেন পরিবর্তন করে বলা অথবা কথা বলা বন্ধ করে দিতে। আমরা তার ব্যাপারে সব কথা বলেছি। আমরা জানি, তিনি আসলে একজন দাসের নাম উল্লেখ করেছেন। ভাই, আমাদের ভাই ভাই, আমরা তার কথা ভুলে গেছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏مَعْبَدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ سُئِلَ عَنْ ‏ ‏الْعَزْلِ ‏ ‏أَوْ قَالَ فِي ‏ ‏الْعَزْلِ ‏ ‏لَا عَلَيْكُمْ أَنْ لَا تَفْعَلُوا ذَلِكَ فَإِنَّمَا هُوَ الْقَدَرُ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَنْبَأَنَا ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏مَعْبَدٍ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[10745,10745,"","আমি মানুষ পছন্দ করি, ঈশ্বর ভাল এবং এটা ভাল. এবং আমি একটি সাহসী মায়ের দ্বারা নির্যাতন তাকে খুঁজে পাওয়া.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏فُضَيْلٌ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَحَبَّ النَّاسِ إِلَى اللَّهِ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ وَأَقْرَبَهُمْ مِنْهُ مَجْلِسًا إِمَامٌ عَادِلٌ وَإِنَّ أَبْغَضَ النَّاسِ إِلَى اللَّهِ يَوْمَ الْقِيَامَةِ وَأَشَدَّهُ عَذَابًا إِمَامٌ ‏ ‏جَائِرٌ ‏","","",""],[10746,10746,"","আমরা আমার বাবার সুখী সন্তান ঈশ্বরকে বাঁচাতে চেষ্টা করা. তারা কেন ঈশ্বরের ইচ্ছা হারালেন যে তারা একটি ভাঙ্গা গর্ব এবং আপনার মন প্রদর্শিত হবে এবং আমরা আপনার মন প্রদর্শন করতে পারি না ক্যাপ্টেনরা নীরব থেকে আছেন আর তাদেরকে আংটি থেকে টেনে আনা হচ্ছে, আর অন্ধকার থেকে উঠে আসছে. তুমি যা বলেছ সব থেকে দুঃখের বিষয় হল, তুমি অনেক ছদ্মবেশে কথা বলবে আর তারপর তারা মিথ্যা বলে, যদি সে এটা পান করবে যতক্ষণ না সে তার কাজিনকে তলোয়ার দিয়ে মেরে ফেলবে তিনি বলেছিলেন যে আমরা অনেক অসুস্থ হয়ে পড়ব । তোমরা দুজন প্রেমিক তাদের ভালোবাসো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَرُوبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَمَّنْ ‏ ‏لَقِيَ الْوَفْدَ ‏ ‏وَذَكَرَ ‏ ‏أَبَا نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ ‏ ‏وَفْدَ عَبْدِ الْقَيْسِ ‏ ‏لَمَّا قَدِمُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا إِنَّا حَيٌّ مِنْ ‏ ‏رَبِيعَةَ ‏ ‏وَبَيْنَنَا وَبَيْنَكَ كُفَّارُ ‏ ‏مُضَرَ ‏ ‏وَلَسْنَا نَسْتَطِيعُ أَنْ نَأْتِيَكَ إِلَّا فِي أَشْهُرِ الْحُرُمِ فَمُرْنَا بِأَمْرٍ إِذَا نَحْنُ أَخَذْنَا بِهِ دَخَلْنَا الْجَنَّةَ وَنَأْمُرُ بِهِ ‏ ‏أَوْ ‏ ‏نَدْعُو ‏ ‏مَنْ وَرَاءَنَا فَقَالَ آمُرُكُمْ بِأَرْبَعٍ وَأَنْهَاكُمْ عَنْ أَرْبَعٍ ‏ ‏اعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا فَهَذَا لَيْسَ مِنْ الْأَرْبَعِ وَأَقِيمُوا الصَّلَاةَ وَآتَوْا الزَّكَاةَ وَصُومُوا رَمَضَانَ وَأَعْطُوا مِنْ الْغَنَائِمِ الْخُمُسَ وَأَنْهَاكُمْ عَنْ أَرْبَعٍ عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏قَالُوا وَمَا عِلْمُكَ بِالنَّقِيرِ قَالَ ‏ ‏جِذْعٌ ‏ ‏يُنْقَرُ ثُمَّ يُلْقُونَ فِيهِ مِنْ ‏ ‏الْقُطَيْعَاءِ ‏ ‏أَوْ الثَّمَرِ وَالْمَاءِ حَتَّى إِذَا سَكَنَ غَلَيَانُهُ شَرِبْتُمُوهُ حَتَّى إِنَّ أَحَدَكُمْ لَيَضْرِبُ ابْنَ عَمِّهِ بِالسَّيْفِ وَفِي الْقَوْمِ رَجُلٌ أَصَابَتْهُ جِرَاحَةٌ مِنْ ذَلِكَ فَجَعَلْتُ أُخَبِّئُهَا حَيَاءً مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا فَمَا تَأْمُرُنَا أَنْ نَشْرَبَ قَالَ فِي ‏ ‏الْأَسْقِيَةِ ‏ ‏الَّتِي ‏ ‏يُلَاثُ ‏ ‏عَلَى أَفْوَاهِهَا قَالُوا إِنَّ أَرْضَنَا أَرْضٌ كَثِيرَةُ ‏ ‏الْجُرْذَانِ ‏ ‏لَا تَبْقَى فِيهَا ‏ ‏أَسْقِيَةُ ‏ ‏الْأُدُمِ ‏ ‏قَالَ وَإِنْ أَكَلَتْهُ ‏ ‏الْجُرْذَانُ ‏ ‏مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏وَقَالَ ‏ ‏لِأَشَجِّ عَبْدِ الْقَيْسِ ‏ ‏إِنَّ فِيكَ ‏ ‏خُلَّتَيْنِ ‏ ‏يُحِبُّهُمَا اللَّهُ عَزَّ وَجَلَّ ‏ ‏الْحِلْمُ ‏ ‏وَالْأَنَاةُ ‏","","",""],[10747,10747,"","আমি আমার বাবাকে হত্যা করতে পেরে খুশি হব বলে বলেছিলাম । তিনি ভুল করেছেন বলে তাকে বলতে হবে, ঈশ্বর তার বাবা বা তার সাথে কথা বলবেন। আমরা তিন দিন পর এটা পছন্দ করি, তারপর আমরা খেতে থাকব এবং খেতে থাকব। আমরা বের হব.","‏ ‏حَدَّثَنَا ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏زَيْنَبُ ‏ ‏عَنْ ‏ ‏أَبِي سِعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ لُحُومِ الْأَضَاحِيِّ فَوْقَ ثَلَاثَةِ أَيَّامٍ فَقَالَ فَقَدِمَ ‏ ‏قَتَادَةُ بْنُ النُّعْمَانِ ‏ ‏أَخُو ‏ ‏أَبِي سَعِيدٍ ‏ ‏لِأُمِّهِ فَقَرَّبُوا إِلَيْهِ مِنْ ‏ ‏قَدِيدِ ‏ ‏الْأَضْحَى فَقَالَ كَأَنَّ هَذَا مِنْ ‏ ‏قَدِيدِ ‏ ‏الْأَضْحَى قَالُوا نَعَمْ فَقَالَ أَلَيْسَ قَدْ نَهَى عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ لَهُ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَوَقَدْ حَدَثَ فِيهِ أَمْرٌ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏نَهَى أَنْ نَحْبِسَهُ فَوْقَ ثَلَاثَةِ أَيَّامٍ ثُمَّ رَخَّصَ لَنَا أَنْ نَأْكُلَ وَنَدَّخِرَ ‏","","",""],[10748,10748,"","আমার বাবা আমাকে বলেছিলেন যে সে অজ্ঞান হয়ে গেছে, আমার বাবা তাকে যা বলেছে তা দিয়েছে, তার সাথে লড়াই করতে হবে না হয় হতাশ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏زَيْنَبُ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏حَرَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بَيْنَ ‏ ‏لَابَتَيْ ‏ ‏الْمَدِينَةِ ‏ ‏أَنْ ‏ ‏يُعْضَدَ ‏ ‏شَجَرُهَا أَوْ ‏ ‏يُخْبَطَ ‏","","",""],[10749,10749,"","আমার বাবা আমার সঙ্গে কথা বলেছিলেন বলে আমি খুশি হয়েছিলাম যে আমার বাবা আমার সঙ্গে কথা বলেছেন । ঈশ্বরের দোহাই প্রার্থনা করছে, সে আত্মসমর্পণ করেছে এবং বলছে চাঁদ তার হৃদয়ে গৌরব বয়ে এনেছে। আমি তাকে তোমার কথা বলতে চাই, এটাই হচ্ছে ঈশ্বরের দোহাইর্তির জন্য।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أُنَيْسِ بْنِ أَبِي يَحْيَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ ‏ ‏يَقُولُ ‏ ‏اخْتَلَفَ رَجُلَانِ ‏ ‏أَوْ ‏ ‏امْتَرَيَا ‏ ‏رَجُلٌ مَنْ ‏ ‏بَنِي خُدْرَةَ ‏ ‏وَرَجُلٌ مَنْ ‏ ‏بَنِي عَمْرِو بْنِ عَوْفٍ ‏ ‏فِي الْمَسْجِدِ الَّذِي أُسِّسَ عَلَى التَّقْوَى قَالَ ‏ ‏الْخُدْرِيُّ هُوَ ‏ ‏مَسْجِدُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏الْعَمْرِيُّ هُوَ ‏ ‏مَسْجِدُ قُبَاءَ ‏ ‏فَأَتَيَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَاهُ عَنْ ذَلِكَ فَقَالَ هُوَ ‏ ‏هَذَا الْمَسْجِدُ ‏ ‏لِمَسْجِدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ فِي ذَاكَ خَيْرٌ كَثِيرٌ ‏ ‏يَعْنِي ‏ ‏مَسْجِدَ قُبَاءَ ‏","","",""],[10750,10750,"","আমরা একটি গালের ছেলে কথা বলেছি, যে আমার বাবার খুশির জন্য লড়াই করতে বলেছে, তার কাছে প্রার্থনা করেছে এবং তাকে কারাগারের দাত এর কাছে আত্মসমর্পণ করেছে... একদম শেষ জায়গা।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏دَاوُدَ السَّرَّاجِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا لَمْ يَلْبَسْهُ فِي الْآخِرَةِ ‏","","",""],[10751,10751,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তিনি মেষতুল্য মেষদের কাছে ফিরে গিয়ে বিজয়ীদের স্মরণ করে বলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏الْمُثَنَّي ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي عِيسَى الْأُسْوَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عُودُوا الْمَرِيضَ وَامْشُوا مَعَ الْجَنَائِزِ تُذَكِّرْكُمْ الْآخِرَةَ ‏","","",""],[10752,10752,"","ঈশ্বর যখন আমাদের কাছ থেকে যা চান, সেই বিষয়ে আমরা আপনাদের টাকাপয়সা নিয়ে কথা বলতাম কিন্তু ঈশ্বরের দয়া আমার ছেলের প্রতি করুণা ছিল ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏تَعْدِلُ ‏ ‏أَوْ تُعْدَلُ ‏ ‏بِثُلُثِ الْقُرْآنِ ‏","","",""],[10753,10753,"","আমরা একটা বালতির কথা বলেছিলাম যার অর্থ আমার সুখী বাবার মদ খাওয়ার কথা ছিল না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏دَاوُدَ يَعْنِي ابْنَ قَيْسٍ ‏ ‏عَنْ ‏ ‏عِيَاضٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏لَمْ تَزَلْ تُخْرَجُ زَكَاةُ الْفِطْرِ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَاعٌ ‏ ‏مِنْ تَمْرٍ أَوْ شَعِيرٍ أَوْ ‏ ‏أَقِطٍ ‏ ‏أَوْ زَبِيبٍ ‏","","",""],[10754,10754,"","আমি আমার ভাইয়ের জাদু দেখে ফিরে গিয়েছিলাম । একবার ঈশ্বরের পথে, কোনো হতাশ প্রার্থনা না করে, তিনি একটা সভাতে অনেক কিছু শুনেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏زَيْنَبُ ابْنَةُ كَعْبِ بْنِ عُجْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَأَيْتَ هَذِهِ الْأَمْرَاضَ الَّتِي تُصِيبُنَا مَا لَنَا بِهَا قَالَ كَفَّارَاتٌ قَالَ أَبِي وَإِنْ قَلَّتْ قَالَ وَإِنْ شَوْكَةً فَمَا فَوْقَهَا ‏ ‏قَالَ ‏ ‏فَدَعَا ‏ ‏أَبِي ‏ ‏عَلَى نَفْسِهِ أَنْ لَا يُفَارِقَهُ ‏ ‏الْوَعْكُ ‏ ‏حَتَّى يَمُوتَ فِي أَنْ لَا يَشْغَلَهُ عَنْ حَجٍّ وَلَا عُمْرَةٍ وَلَا جِهَادٍ فِي سَبِيلِ اللَّهِ وَلَا صَلَاةٍ مَكْتُوبَةٍ فِي جَمَاعَةٍ فَمَا مَسَّهُ إِنْسَانٌ إِلَّا وَجَدَ حَرَّهُ حَتَّى مَاتَ ‏","","",""],[10755,10755,"","বাবা কি বলেছে সে বলেছে, আমি তোমাকে দেখে খুব খুশি হয়েছি, প্রফেসরের সাথে ফিরে যেতে","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو نَضْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اهْتَزَّ الْعَرْشُ لِمَوْتِ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏","","",""],[10756,10756,"","আমরা এক ছেলের কথা বলেছিলাম, যে একবার বলেছিল যে, আমাকে বাবার সুখী মাস্টারের সাথে যুদ্ধ করতে হবে। ভুল লোকের সামনে আসার আগে, আর তারপর তোমাদের মধ্যে একজন যদি এটা আশা করতে চায় তাহলে তার প্রার্থনাটা করবে। তার বাম বা তার গোপন অবস্থা নিয়ে মাথা ঘামানোর অধিকার নেই। জলদি, সে তার জামাতে থাকে আর তোমাকে নষ্ট করে দেয়।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عِيَاضُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُعْجِبُهُ ‏ ‏الْعَرَاجِينُ ‏ ‏أَنْ يُمْسِكَهَا بِيَدِهِ فَدَخَلَ الْمَسْجِدَ ذَاتَ يَوْمٍ وَفِي يَدِهِ وَاحِدٌ مِنْهَا فَرَأَى ‏ ‏نُخَامَاتٍ ‏ ‏فِي قِبْلَةِ الْمَسْجِدِ ‏ ‏فَحَتَّهُنَّ ‏ ‏بِهِ حَتَّى أَنْقَاهُنَّ ثُمَّ أَقْبَلَ عَلَى النَّاسِ مُغْضَبًا فَقَالَ ‏ ‏أَيُحِبُّ أَحَدُكُمْ أَنْ يَسْتَقْبِلَهُ رَجُلٌ فَيَبْصُقَ فِي وَجْهِهِ إِنَّ أَحَدَكُمْ إِذَا قَامَ إِلَى الصَّلَاةِ فَإِنَّمَا يَسْتَقْبِلُ رَبَّهُ عَزَّ وَجَلَّ وَالْمَلَكُ عَنْ يَمِينِهِ فَلَا يَبْصُقْ بَيْنَ يَدَيْهِ وَلَا عَنْ يَمِينِهِ وَلْيَبْصُقْ تَحْتَ قَدَمِهِ الْيُسْرَى ‏ ‏أَوْ عَنْ يَسَارِهِ ‏ ‏فَإِنْ عَجِلَتْ بِهِ ‏ ‏بَادِرَةٌ ‏ ‏فَلْيَقُلْ هَكَذَا وَرَدَّ بَعْضَهُ عَلَى بَعْضٍ ‏ ‏وَتَفَلَ ‏ ‏يَحْيَى ‏ ‏فِي ثَوْبِهِ وَدَلَكَهُ ‏","","",""],[10757,10757,"","আমাদের আলোচনা নিয়ে কথা বলেছিলাম, কিন্তু প্রভু বলেছিলেন তিনি আমার সাথে কথা বলেছেন। তিনি আমাদের সাথে কথা বলেছেন, বছরের পর থেকে আমরা আমার বাবার সুখী সেবা থেকে ফিরে এসেছি। তিনি আসবেন। ভাগ্যের রাতের জন্য আমরা ঈশ্বরকে জিজ্ঞেস করতে শিখতে পারব... ...আর তৃষ্ণা দূর করতেও তাকে সাহায্য করেছি. তারপর আমি তাকে ভুলে গেলাম, আমি ভালো পানিতে খুঁজে পেলাম যে আমি আমার সাথে বিরতি করার চেষ্টা করছি। তার গুজবটা আমার কাছে আর সে বিষে আক্রান্ত হবে। আমি তাকে প্রার্থনা করতে যাচ্ছি, আমরা যেতে চাই।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏تَذَاكَرْنَا لَيْلَةَ الْقَدْرِ فَقَالَ بَعْضُ الْقَوْمِ إِنَّهَا تَدُورُ مِنْ السَّنَةِ فَمَشَيْنَا إِلَى ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قُلْتُ يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ لَيْلَةَ الْقَدْرِ قَالَ نَعَمْ ‏ ‏اعْتَكَفَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَشْرَ الْوَسَطَ مِنْ رَمَضَانَ وَاعْتَكَفْنَا مَعَهُ فَلَمَّا أَصْبَحْنَا صَبِيحَةَ عِشْرِينَ رَجَعَ وَرَجَعْنَا مَعَهُ وَأُرِيَ لَيْلَةَ الْقَدْرِ ثُمَّ أُنْسِيَهَا فَقَالَ ‏ ‏إِنِّي رَأَيْتُ لَيْلَةَ الْقَدْرِ ثُمَّ أُنْسِيتُهَا ‏ ‏فَأُرَانِي أَسْجُدُ فِي مَاءٍ وَطِينٍ فَمَنْ ‏ ‏اعْتَكَفَ ‏ ‏مَعِي فَلْيَرْجِعْ إِلَى ‏ ‏مُعْتَكَفِهِ ‏ ‏ابْتَغُوهَا فِي الْعَشْرِ الْأَوَاخِرِ فِي ‏ ‏الْوَتْرِ ‏ ‏مِنْهَا وَهَاجَتْ عَلَيْنَا السَّمَاءُ آخِرَ تِلْكَ الْعَشِيَّةِ وَكَانَ نِصْفُ الْمَسْجِدِ ‏ ‏عَرِيشًا ‏ ‏مِنْ جَرِيدٍ ‏ ‏فَوَكَفَ ‏ ‏فَوَالَّذِي هُوَ أَكْرَمَهُ وَأَنْزَلَ عَلَيْهِ الْكِتَابَ لَرَأَيْتُهُ صَلَّى بِنَا صَلَاةَ الْمَغْرِبِ لَيْلَةَ إِحْدَى وَعِشْرِينَ وَإِنَّ جَبْهَتَهُ ‏ ‏وَأَرْنَبَةَ ‏ ‏أَنْفِهِ لَفِي الْمَاءِ وَالطِّينِ ‏","","",""],[10758,10758,"","আমি বলেছিলাম যে, আপনি আপনার বাবাকে যে - বিষয়টা শুনেছিলেন, তা খুঁজে পেতে আমি আপনার বাবাকে কীভাবে শুনতে পেয়েছিলাম । ঈশ্বর কি তার কিছু মহিলাকে দিয়ে দিয়েছেন, \"ঈশ্বর, আমার সাথে কি ভালো আছে?\" তিনি বললেন, তিনি এখানে এসেছেন যে আমি তাকে হারিয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الْخَرَّاطِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏مَرَّ بِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي سَعِيدٍ الْخُدْرِيُّ ‏ ‏فَقُلْتُ لَهُ كَيْفَ سَمِعْتَ أَبَاكَ يَقُولُ فِي الْمَسْجِدِ الَّذِي أُسِّسَ عَلَى التَّقْوَى ‏ ‏قَالَ قَالَ ‏ ‏أَبِي ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِ بَعْضِ نِسَائِهِ فَقُلْتُ يَا رَسُولَ اللَّهِ أَيُّ الْمَسْجِدَيْنِ الَّذِي أُسِّسَ عَلَى التَّقْوَى فَأَخَذَ كَفًّا مِنْ حَصًى فَضَرَبَ بِهِ الْأَرْضَ قَالَ ‏ ‏هُوَ هَذَا ‏ ‏مَسْجِدُ الْمَدِينَةِ ‏ ‏قَالَ فَقُلْتُ لَهُ أَتَشْهَدُ لَسَمِعْتَ أَبَاكَ هَكَذَا يَذْكُرُهُ ‏","","",""],[10759,10759,"","আমরা নাম নিয়ে কথা বলেছি, কিন্তু সে আমাকে আমার ভাইয়ের নাম দিতে চাচ্ছে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমি যা করছি তা আত্মসমর্পণ করে যাচ্ছি। ঈশ্বর তাঁর পরিকল্পনাগুলো জয় করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا أَصَابَ الْمُسْلِمَ مِنْ مَرَضٍ وَلَا ‏ ‏وَصَبٍ ‏ ‏وَلَا حَزَنٍ حَتَّى الْهَمَّ يُهِمُّهُ إِلَّا يُكَفِّرُ اللَّهُ عَزَّ وَجَلَّ عَنْهُ مِنْ خَطَايَاهُ ‏","","",""],[10760,10760,"","আমরা বাবার ছেলের কথা বলেছিলাম আমার ভাইয়ের জাদু নিয়ে কথা বলতে। লর্ড তার কাছে প্রার্থনা করল আর সে আত্মসমর্পণ করবে যদি সে তোমার নিজের কোন কাজে পড়ে যায়।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَقَعَ الذُّبَابُ فِي طَعَامِ أَحَدِكُمْ ‏ ‏فَامْقُلُوهُ ‏","","",""],[10761,10761,"","আমার ছেলের অকারণে আমার বাবার মৃত্যু নিয়ে আমরা কথা বলেছি, ঈশ্বর আত্মসমর্পণ করেছেন যদি তারা তৃতীয়জন হয় তাদের দোষারোপ করে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَشُعْبَةُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانُوا ثَلَاثَةً فَلْيَؤُمَّهُمْ أَحَدُهُمْ وَأَحَقُّهُمْ بِالْإِمَامَةِ أَقْرَؤُهُمْ ‏","","",""],[10762,10762,"","ঈশ্বর তাকে আদেশ দিয়েছেন এবং শেষ দশ বা দু - বার বিক্রি করার জন্য দুই বছর পর্যন্ত আত্মসমর্পণ করবেন । তিনি সেই ব্যক্তিদের ভালোবাসেন, যারা অনুগত এবং অনুগত নয় ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏حُنَيْنٍ ‏ ‏لِسَبْعَ عَشْرَةَ ‏ ‏أَوْ ثَمَانِ عَشْرَةَ ‏ ‏مَضَتْ مِنْ رَمَضَانَ ‏ ‏فَصَامَ صَائِمُونَ وَأَفْطَرَ آخَرُونَ وَلَمْ يَعِبْ هَؤُلَاءِ عَلَى هَؤُلَاءِ وَلَا هَؤُلَاءِ عَلَى هَؤُلَاءِ ‏","","",""],[10763,10763,"","ঈশ্বর তাকে আদেশ দিয়েছেন এবং আত্মসমর্পণ করবেন বলে আপনি প্রতারণা বা লোকেদের এক বাসা হয়ে যাবেন, এমন লোকেদের কাছে আসবেন, যারা হবে এমন ব্যক্তি । মিথ্যে, তারা মিথ্যা বলে, আর তারাই তাদের কাজ করেছে, সে আমার আর আমি তার কাছ থেকে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ أَبِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَكُونُ أُمَرَاءُ ‏ ‏تَغْشَاهُمْ غَوَاشٍ ‏ ‏أَوْ حَوَاشٍ ‏ ‏مِنْ النَّاسِ يَظْلِمُونَ وَيَكْذِبُونَ فَمَنْ دَخَلَ عَلَيْهِمْ فَصَدَّقَهُمْ بِكَذِبِهِمْ وَأَعَانَهُمْ عَلَى ظُلْمِهِمْ فَلَيْسَ مِنِّي وَلَسْتُ مِنْهُ وَمَنْ لَمْ يَدْخُلْ عَلَيْهِمْ وَيُصَدِّقْهُمْ بِكَذِبِهِمْ وَيُعِنْهُمْ عَلَى ظُلْمِهِمْ فَهُوَ مِنِّي وَأَنَا مِنْهُ ‏","","",""],[10764,10764,"","আমার ভাই খুশি হওয়ার পর আমি আমার ছেলের সাথে কথা বলেছি। ঈশ্বর আদেশ দিয়েছেন যে, আমি এক ছেলেকে রাজার মৃত্যু জয় করতে পারব। ঈশ্বর এটা করেছেন এবং তিনি একটি প্রাণ দিয়েছেন। বন্ধুত্ব।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلَ ‏ ‏ابْنَ صَائِدٍ ‏ ‏عَنْ تُرْبَةِ الْجَنَّةِ فَقَالَ ‏ ‏دَرْمَكَةٌ ‏ ‏بَيْضَاءُ مِسْكٌ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ ‏","","",""],[10765,10765,"","ঈশ্বর আমাদের যে টোপগুলো দিয়েছেন, সেগুলো নিয়ে আমরা যে - বাধাগুলো পেয়েছি, সেগুলো নিয়ে আমি সাহায্য করার চেষ্টা করেছি । তিনি বলেছিলেন, ঈশ্বর তার জন্য প্রার্থনা করেন এবং তার বন্ধুত্বের জন্য তাকে সাহায্য করেন ।","‏ ‏رَحِمَهُ اللَّهُ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلَ ‏ ‏ابْنَ صَائِدٍ ‏ ‏عَنْ تُرْبَةِ الْجَنَّةِ فَقَالَ ‏ ‏دَرْمَكَةٌ ‏ ‏بَيْضَاءُ مِسْكٌ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ ‏","","",""],[10766,10766,"","আমরা আমার বাবার আনন্দের সমাপ্তি নিয়ে কথা বলেছি, ঈশ্বর বলে গেছেন, যদি সে সেটা দেখে ফেলে তাহলে সে সেটা করেছে কিনা, তারপর যে তার পিছু পিছু নিয়েছে, সে তার জন্য প্রস্তুত হবে। খেল।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا رَأَيْتُمْ الْجَنَازَةَ فَقُومُوا ‏ ‏لَهَا ‏ ‏فَمَنْ اتَّبَعَهَا فَلَا يَقْعُدْ حَتَّى تُوضَعَ ‏","","",""],[10767,10767,"","আমার মা দু - বার তাকে হত্যা করার বা তাকে হত্যা করার সময় কয়েকবার ভেঙে ফেলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَوْفٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْتَرِقُ أُمَّتِي فِرْقَتَيْنِ ‏ ‏فَيَتَمَرَّقُ ‏ ‏بَيْنَهُمَا ‏ ‏مَارِقَةٌ ‏ ‏يَقْتُلُهَا أَوْلَى الطَّائِفَتَيْنِ بِالْحَقِّ ‏","","",""],[10768,10768,"","আমরা একটি মহান সময়ের সুখী পুত্র কথা বলেছি যখন আমরা বাবাকে ভালো বিশ্বাসী মানুষের কাছে সাহায্য করার চেষ্টা করেছি। এবং ছেলেটা তার কাছে প্রার্থনা করে এবং প্রভু ও তার কাছে প্রার্থনা করে। ঈশ্বর তাকে তা দিতে এবং আশীর্বাদ করতে দেন, যাতে তিনি সেটা ছেড়ে দেন এবং এরপর তৃতীয় রিং নম্বরে প্রবেশ করতে দেন । তারা সিংহাসনের সামনে তাকে দুটো কাপড় দিয়ে দিয়েছিল আর তারপর বলেছিল যে তারা তাদের মধ্যে বিশ্বাস করে । তুমি তাকে বন্ধ করে দিলে, তুমি বলেছিলে তুমি তাকে হারিয়ে ফেলবে, তারপর তুমি তাকে মেরে ফেলবে, তুমি এটা করতে যাচ্ছো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏عِيَاضٌ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏دَخَلَ رَجُلٌ الْمَسْجِدَ يَوْمَ الْجُمُعَةِ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ فَدَعَاهُ فَأَمَرَهُ أَنْ يُصَلِّيَ رَكْعَتَيْنِ ثُمَّ دَخَلَ الْجُمُعَةَ الثَّانِيَةَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ فَدَعَاهُ فَأَمَرَهُ ثُمَّ دَخَلَ الْجُمُعَةَ الثَّالِثَةَ ‏ ‏فَأَمَرَهُ أَنْ يُصَلِّيَ رَكْعَتَيْنِ ثُمَّ قَالَ تَصَدَّقُوا فَفَعَلُوا فَأَعْطَاهُ ثَوْبَيْنِ مِمَّا تَصَدَّقُوا ثُمَّ قَالَ تَصَدَّقُوا فَأَلْقَى أَحَدَ ثَوْبَيْهِ ‏ ‏فَانْتَهَرَهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَرِهَ مَا صَنَعَ ثُمَّ قَالَ انْظُرُوا إِلَى هَذَا فَإِنَّهُ دَخَلَ الْمَسْجِدَ فِي هَيْئَةٍ ‏ ‏بَذَّةٍ ‏ ‏فَدَعَوْتُهُ فَرَجَوْتُ أَنْ تُعْطُوا لَهُ فَتَصَدَّقُوا عَلَيْهِ وَتَكْسُوهُ فَلَمْ تَفْعَلُوا فَقُلْتُ تَصَدَّقُوا فَتَصَدَّقُوا فَأَعْطَيْتُهُ ثَوْبَيْنِ مِمَّا تَصَدَّقُوا ثُمَّ قُلْتُ تَصَدَّقُوا فَأَلْقَى أَحَدَ ثَوْبَيْهِ خُذْ ثَوْبَكَ وَانْتَهَرَهُ ‏","","",""],[10769,10769,"","আমরা বাবার ছেলের কথা বলেছিলাম আমার ছেলের মৃত্যুর পর সূর্য চলে যাওয়ার পর ক্ষমতা নিয়ে। সে প্রার্থনা করে কিভাবে তার সময় তিনি তার সময় কি ঘটেছে তার প্রার্থনা করলেন। আমার বাবার সাহায্য ছাড়া বাবা আর আপনার কলমে ভয় পেয়ে বা হাঁটু গেড়ে বসেন","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏حُبِسْنَا يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏عَنْ الصَّلَوَاتِ حَتَّى كَانَ بَعْدَ الْمَغْرِبِ ‏ ‏هَوِيًّا ‏ ‏وَذَلِكَ قَبْلَ أَنْ يَنْزِلَ فِي الْقِتَالِ مَا نَزَلَ فَلَمَّا كُفِينَا الْقِتَالَ وَذَلِكَ قَوْلُهُ ‏ { ‏وَكَفَى اللَّهُ الْمُؤْمِنِينَ الْقِتَالَ وَكَانَ اللَّهُ قَوِيًّا عَزِيزًا ‏} ‏أَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِلَالًا ‏ ‏فَأَقَامَ الظُّهْرَ فَصَلَّاهَا كَمَا يُصَلِّيهَا فِي وَقْتِهَا ثُمَّ أَقَامَ الْعَصْرَ فَصَلَّاهَا كَمَا يُصَلِّيهَا فِي وَقْتِهَا ثُمَّ أَقَامَ الْمَغْرِبَ فَصَلَّاهَا كَمَا يُصَلِّيهَا فِي وَقْتِهَا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏فَذَكَرَهُ بِإِسْنَادِهِ وَمَعْنَاهُ وَزَادَ فِيهِ قَالَ وَذَلِكَ قَبْلَ أَنْ يَنْزِلَ صَلَاةَ الْخَوْفِ ‏ { ‏فَرِجَالًا أَوْ رُكْبَانًا ‏}","","",""],[10770,10770,"","অন্যদিন আমার ভাই চলে যাওয়ার পর আমরা খুশির সাথে কথা বলেছি। ভয় পাবে এবং অন্যরা ভয় পাবে, আগুন মারা যাবে, বা মানুষ বেঁচে থাকবে না, অথবা মানুষ পাপ করবে না। কখনো ছেলেরা হত্যা করে এবং আগুন জ্বালিয়ে আগুন লাগে, অথবা আগুন লাগে, নাকি আগুনের মধ্যে ফেলে দেয়? তার সময় থেকে আমি বলবো তোমার কল্পনা আর তোমার মৃত্যু হবেই। সে বলবে, \"ঈশ্বর, আমি তাকে গাছের মধ্যে পরিণত করব, আর তারপর সে তার জন্য অপেক্ষা করবে।\" আর তৃতীয়টি বলবে, প্রভু, আমি বলছি, আমি তোমার কল্পনার মধ্যে আছি। আমি জানি, \"আমি জানি, তোমার মৃত্যু হবে না\" এবং তোমার মৃত্যু হবে না। আর তোমার মৃত্যু হবে না। আর তোমার মৃত্যু হবে না।\" যে ব ্ যক ্ তি ভয় করে , সে-ই হবে , যে ব ্ যক ্ তি হবে , সে ব ্ যতিরেকে এবং যে ব ্ যক ্ তি হবে সে-ই হবে ক ্ ষতি । সে-ই হবে যে , যে ব ্ যক ্ তি হবে , যে ব ্ যক ্ তি তার জন ্ যে উত ্ তম হবে । রাজা হোন, তিনি মানুষের দিকে তাকিয়ে শোনেন এবং তাদের কণ্ঠ শোনেন যে আল্লাহ আমাকে সুখী এবং সুখী, সৃষ্টিকর্তা তাদের আত্মসমর্পণ করতে হবে, তিনি বলেন যে তারা হয়তো প্রবেশ করতে পারে। যে কিনা বিশ্বের রাজা হবে তার মৃত্যু ঘটাতে অপরাধ, আমরা ঋণ শোধ করছি এবং দশ বার চেষ্টা করে চেষ্টা করছি প্রভু তাঁর কাছে প্রার্থনা করেছেন এবং বলেন যে, লোকেরা তাঁর মনের দেয়ালে প্রবেশ করবে এবং ঈশ্বরের কাছে প্রার্থনা করবে । আমি শুনেছি বাবা আমার বাবার কথা শুনে খুশি, সুখী দাস, ঈশ্বরের কাছে প্রার্থনা করুন, ঈশ্বরের কাছে প্রার্থনা করুন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ غِيَاثٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏يُعْرَضُ النَّاسُ عَلَى جِسْرِ جَهَنَّمَ ‏ ‏وَعَلَيْهِ ‏ ‏حَسَكٌ ‏ ‏وَكَلَالِيبُ ‏ ‏وَخَطَاطِيفُ ‏ ‏تَخْطَفُ النَّاسَ قَالَ فَيَمُرُّ النَّاسُ مِثْلَ الْبَرْقِ وَآخَرُونَ مِثْلَ الرِّيحِ وَآخَرُونَ مِثْلَ الْفَرَسِ الْمُجِدِّ وَآخَرُونَ يَسْعَوْنَ سَعْيًا وَآخَرُونَ يَمْشُونَ مَشْيًا وَآخَرُونَ يَحْبُونَ حَبْوًا وَآخَرُونَ يَزْحَفُونَ زَحْفًا فَأَمَّا أَهْلُ النَّارِ فَلَا يَمُوتُونَ وَلَا يَحْيَوْنَ وَأَمَّا نَاسٌ فَيُؤْخَذُونَ بِذُنُوبِهِمْ فَيُحْرَقُونَ فَيَكُونُونَ فَحْمًا ثُمَّ يَأْذَنُ اللَّهُ فِي ‏ ‏الشَّفَاعَةِ ‏ ‏فَيُوجَدُونَ ‏ ‏ضِبَارَاتٍ ‏ ‏ضِبَارَاتٍ ‏ ‏فَيُقْذَفُونَ عَلَى نَهَرٍ فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبَّةُ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ رَأَيْتُمْ ‏ ‏الصَّبْغَاءَ ‏ ‏فَقَالَ وَعَلَى النَّارِ ثَلَاثُ شَجَرَاتٍ فَتَخْرُجُ ‏ ‏أَوْ يَخْرُجُ ‏ ‏رَجُلٌ مِنْ النَّارِ فَيَكُونُ عَلَى شَفَتِهَا فَيَقُولُ يَا رَبِّ اصْرِفْ وَجْهِي عَنْهَا قَالَ فَيَقُولُ ‏ ‏وَعَهْدِكَ وَذِمَّتِكَ لَا تَسْأَلُنِي غَيْرَهَا قَالَ فَيَرَى شَجَرَةً فَيَقُولُ يَا رَبِّ ‏ ‏أَدْنِنِي ‏ ‏مِنْ هَذِهِ الشَّجَرَةِ أَسْتَظِلُّ بِظِلِّهَا وَآكُلُ مِنْ ثَمَرَتِهَا قَالَ فَيَقُولُ وَعَهْدِكَ وَذِمَّتِكَ لَا تَسْأَلُنِي غَيْرَهَا قَالَ فَيَرَى شَجَرَةً أُخْرَى أَحْسَنَ مِنْهَا فَيَقُولُ يَا رَبِّ حَوِّلْنِي إِلَى هَذِهِ الشَّجَرَةِ فَأَسْتَظِلَّ بِظِلِّهَا وَآكُلَ مِنْ ثَمَرَتِهَا فَيَقُولُ وَعَهْدِكَ وَذِمَّتِكَ لَا تَسْأَلُنِي غَيْرَهَا قَالَ فَيَرَى الثَّالِثَةَ فَيَقُولُ يَا رَبِّ حَوِّلْنِي إِلَى هَذِهِ الشَّجَرَةِ أَسْتَظِلُّ بِظِلِّهَا وَآكُلُ مِنْ ثَمَرَتِهَا قَالَ وَعَهْدِكَ وَذِمَّتِكَ لَا تَسْأَلُنِي غَيْرَهَا قَالَ فَيَرَى سَوَادَ النَّاسِ وَيَسْمَعُ ‏ ‏أَصْوَاتَهُمْ فَيَقُولُ رَبِّ أَدْخِلْنِي الْجَنَّةَ قَالَ فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَرَجُلٌ ‏ ‏آخَرُ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اخْتَلَفَا فَقَالَ أَحَدُهُمَا فَيَدْخُلُ الْجَنَّةَ ‏ ‏فَيُعْطَى الدُّنْيَا وَمِثْلَهَا مَعَهَا وَقَالَ الْآخَرُ يُدْخَلُ الْجَنَّةَ ‏ ‏فَيُعْطَى الدُّنْيَا وَعَشَرَةَ أَمْثَالِهَا ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ غِيَاثٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَمُرُّ النَّاسُ عَلَى جِسْرِ جَهَنَّمَ فَذَكَرَهُ قَالَ بِجَنْبَتَيْهِ مَلَائِكَةٌ يَقُولُونَ اللَّهُمَّ سَلِّمْ سَلِّمْ وَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا رَأَيْتُمْ ‏ ‏الصَّبْغَاءَ شَجَرَةٌ تَنْبُتُ فِي ‏ ‏الْغُثَاءِ ‏ ‏وَقَالَ وَأَمَّا أَهْلُ النَّارِ الَّذِينَ هُمْ أَهْلُهَا فَذَكَرَ مَعْنَاهُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ غِيَاثٍ ‏ ‏وَأَمْلَاهُ عَلَيَّ قَالَ سَمِعْتُ ‏ ‏أَبَا نَضْرَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّفَاعَةَ ‏ ‏فَقَالَ إِنَّ النَّاسَ يُعْرَضُونَ عَلَى جِسْرِ جَهَنَّمَ وَعَلَيْهِ ‏ ‏حَسَكٌ ‏ ‏وَكَلَالِيبُ ‏ ‏يَخْطَفُ النَّاسَ وَبِجَنْبَتَيْهِ الْمَلَائِكَةُ يَقُولُونَ اللَّهُمَّ سَلِّمْ سَلِّمْ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[10771,10771,"","আমি আমার বাবার সাথে কথা বলতে তোমাকে সাহায্য করেছি যে তিনি চলে গেছেন বলে আমি আনন্দিত আপনি শুনেছেন যে তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন যার জন্য তিনি শেষ করেছেন বাতাসে লাফ দিয়ে, এক নিঃশ্বাসে সে তোমার ছেলেকে বলেছিল, সে তাকে হারানোর কথা বলছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏حَدَّثَنِي ‏ ‏أَيُّوبُ بْنُ حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُثَنَّى ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏مَرْوَانَ ‏ ‏فَدَخَلَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَقَالَ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ النَّفْخِ فِي الشَّرَابِ قَالَ نَعَمْ فَقَالَ رَجُلٌ إِنِّي لَا ‏ ‏أُرْوَى مِنْ نَفَسٍ وَاحِدٍ قَالَ أَبِنْهُ عَنْكَ ثُمَّ تَنَفَّسْ قَالَ أَرَى فِيهِ ‏ ‏الْقَذَاةَ ‏ ‏قَالَ ‏ ‏فَأَهْرِقْهَا ‏","","",""],[10772,10772,"","সেই সময়ে, আমি আমার পরিবারের সঙ্গে বাইবেল অধ্যয়ন করতে শুরু করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْعَزْلِ ‏ ‏قَالَ ‏ ‏اصْنَعُوا مَا بَدَا لَكُمْ فَإِنْ قَدَّرَ اللَّهُ شَيْئًا كَانَ ‏","","",""],[10773,10773,"","কেন পঞ্চম জন আমাদের থাকার জন্য পঞ্চম বারের মতো পঞ্চম বাধা দিয়েছিল?","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قُلْنَا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا حُرِّمَتْ الْخَمْرُ ‏ ‏إِنَّ عِنْدَنَا خَمْرًا لِيَتِيمٍ لَنَا فَأَمَرَنَا ‏ ‏فَأَهْرَقْنَاهَا ‏","","",""],[10774,10774,"","আমি আমার বাবার কথা বলেছিলাম যে তাকে খুঁজে বের করার চেষ্টা করছে ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَهْلَ الدَّرَجَاتِ الْعُلَى لَيَرَوْنَ مَنْ فَوْقَهُمْ كَمَا تَرَوْنَ الْكَوْكَبَ الدُّرِّيَّ فِي أُفُقِ السَّمَاءِ وَإِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏مِنْهُمْ وَأَنْعَمَا ‏","","",""],[10775,10775,"","আমরা কথা বলেছিলাম, আমার বাবা কিভাবে ঈশ্বরের শাসন করতে পারলে খুশি ছিলেন, সে টাওয়ার থেকে বের হয়ে আসতে এবং তার মাথা দেখতেও পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ذَكْوَانَ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى مَنْزِلَ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَخَرَجَ وَرَأْسُهُ يَقْطُرُ قَالَ لَعَلَّنَا أَعْجَلْنَاكَ قَالَ ‏ ‏إِذَا أُعْجِلْتَ ‏ ‏أَوْ ‏ ‏أُقْحِطْتَ ‏ ‏فَلَيْسَ عَلَيْكَ غُسْلٌ ‏","","",""],[10776,10776,"","ঈশ্বর নিজেকে আত্মসমর্পণ করেছেন কেন একজন ব্যক্তি মারা যেতে পারত । তোমাকে আর তোমার বসের পিছনে আসতে নিষেধ করে না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي يَحْيَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏قَالَ لَا تُوقِدُوا نَارًا بِلَيْلٍ قَالَ فَلَمَّا كَانَ بَعْدَ ذَاكَ قَالَ ‏ ‏أَوْقِدُوا وَاصْطَنِعُوا فَإِنَّهُ لَا ‏ ‏يُدْرِكُ ‏ ‏قَوْمٌ بَعْدَكُمْ ‏ ‏صَاعَكُمْ ‏ ‏وَلَا ‏ ‏مُدَّكُمْ ‏","","",""],[10777,10777,"","আমরা আমার মৃত বাবা একটি ছেলে হওয়া সম্পর্কে কথা বলেছি অথবা আমি মনে করি মানুষ মনে হয় আপনি শুনতে যাচ্ছে না. তিনি বললেন অথবা তিনি বললেন ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তিনি আমার প্রভু এবং আমি প্রভু ও প্রভু হইবে, নগরের মধ্যে বিবাদ হইল, আর আমরা তোমার সহিত সঙ্গে আছি, আর সে বলল, যখন আমি তোমার সহিত জন্মিয়াছি, সে আমাকে বলল, আমার উপরে পোষাক পরিহিত ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏لَقِيَنِي ‏ ‏ابْنُ صَائِدٍ ‏ ‏فَقَالَ عُدَّ النَّاسَ يَقُولُونَ ‏ ‏أَوْ أَحْسِبُ النَّاسَ يَقُولُونَ ‏ ‏وَأَنْتُمْ يَا ‏ ‏أَصْحَابَ ‏ ‏مُحَمَّدٍ ‏ ‏أَلَيْسَ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَوْ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ يَهُودِيٌّ وَأَنَا مُسْلِمٌ وَإِنَّهُ أَعْوَرُ وَأَنَا صَحِيحٌ وَلَا يَأْتِي ‏ ‏مَكَّةَ ‏ ‏وَلَا ‏ ‏الْمَدِينَةَ ‏ ‏وَقَدْ حَجَجْتُ وَأَنَا مَعَكَ الْآنَ ‏ ‏بِالْمَدِينَةِ ‏ ‏وَلَا يُولَدُ لَهُ وَقَدْ وُلِدَ لِي ثُمَّ قَالَ مَعَ ذَاكَ إِنِّي لَأَعْلَمُ أَيْنَ وُلِدَ وَمَتَى يَخْرُجُ وَأَيْنَ هُوَ قَالَ فَلَبَّسَ عَلَيَّ ‏","","",""],[10778,10778,"","আমরা বাবার নিস্পারসিসের সাথে ঘুমের ব্যাপারে কথা বলেছি, সে ঈশ্বরকে জিজ্ঞেস করলো, সে তাকে জিজ্ঞেস করলো, সে ঘুমোবে না আর সে এমন ভাবে ঘুমাবে না যা হয়তো ভালো তার চেহারা হারিয়ে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ أَبِي عَيَّاشٍ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَصُومُ عَبْدٌ يَوْمًا فِي سَبِيلِ اللَّهِ إِلَّا بَاعَدَ اللَّهُ بِذَلِكَ الْيَوْمِ النَّارَ عَنْ وَجْهِهِ سَبْعِينَ خَرِيفًا ‏","","",""],[10779,10779,"","বাবার ছেলের কথা বলেছিলাম বাবার নাম বিক্রি করার চেষ্টা করেছি। ঈশ্বরের দোহাই ছিল আর আমি এটা পেয়েছি যে আমি হয়ত তাদের একজনের মধ্যে ছেড়ে যেতে পারব। আমি ক্লান্ত আর ক্লান্ত হয়ে গেছি। একা থাকার জন্য.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ يَعْنِي ابْنَ أَبِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي قَدْ تَرَكْتُ فِيكُمْ ‏ ‏الثَّقَلَيْنِ ‏ ‏أَحَدُهُمَا أَكْبَرُ مِنْ الْآخَرِ كِتَابُ اللَّهِ عَزَّ وَجَلَّ حَبْلٌ مَمْدُودٌ مِنْ السَّمَاءِ إِلَى الْأَرْضِ ‏ ‏وَعِتْرَتِي ‏ ‏أَهْلُ بَيْتِي أَلَا إِنَّهُمَا لَنْ يَفْتَرِقَا حَتَّى يَرِدَا عَلَيَّ الْحَوْضَ ‏","","",""],[10780,10780,"","আমি আমার সাথে বসলাম ডার্ক ওয়ান বলেছিল যে আমি ছেলেটিকে খুঁজে বের করতে চেয়েছিলাম. আমার মা, সাত বছর বা দু বছর সাধুর জীবনের ছোট্ট একটা মুহূর্ত... ...অথবা প্রতারণা দ্বারা পূর্ণ হবে","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى يَعْنِي الْجُهَنِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدًا الْعَمِّيَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الصِّدِّيقِ النَّاجِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكُونُ مِنْ أُمَّتِي ‏ ‏الْمَهْدِيُّ ‏ ‏فَإِنْ طَالَ عُمْرُهُ أَوْ قَصُرَ عُمْرُهُ عَاشَ سَبْعَ سِنِينَ أَوْ ثَمَانِ سِنِينَ أَوْ تِسْعَ سِنِينَ يَمْلَأُ الْأَرْضَ قِسْطًا وَعَدْلًا وَتُخْرِجُ الْأَرْضُ نَبَاتَهَا وَتُمْطِرُ السَّمَاءُ قَطْرَهَا ‏","","",""],[10781,10781,"","আমরা আমাদের চেয়ে ভাল দৌড়ের ব্যাপারে কথা বলেছি। সে ঈশ্বরের কাছে প্রার্থনা করলো। সে যদি তার কাছে প্রার্থনা করতো, সে পৌঁছে দিত যে তিনি সিঁড়ি দিয়ে যেতে পারতেন। আকাশ থেকে আমি ক্লান্ত হয়ে গেছি এবং আমার বাবা অনেক বেশী এবং আমার বাবা অনেক বেশী সময় ধরে আমি তাদের সাথে আছি আর আমি জানি তারা কি।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏حَدَّثَنَا ‏ ‏عَطِيَّةُ بْنُ سَعْدٍ ‏ ‏بِبَابِ هَذَا الْمَسْجِدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَهْلَ الدَّرَجَاتِ الْعُلَى ‏ ‏لَيَرَاهُمْ مَنْ تَحْتَهُمْ كَمَا تَرَوْنَ النَّجْمَ الطَّالِعَ فِي الْأُفُقِ مِنْ آفَاقِ السَّمَاءِ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏مِنْهُمْ وَأَنْعَمَا ‏","","",""],[10782,10782,"","আমি কথা বলেছি, ঈশ্বর কীভাবে আমাকে রক্ষা করতে সক্ষম ছিলেন। আমার বাবা, ঈশ্বরকে বলতে পেরে খুশি যে ঈশ্বর তার সবচেয়ে ভালো মানুষ আর আমি তোমাদের একজন হিসেবে মুক্তি দেবো। তিনি বলেছেন, তিনি আমাকে বলেছেন, কীভাবে তিনি আমাকে রক্ষা করতে পারেন। যা তুমি অস্বীকার করতে পারো নি... ...সে দেখেছে যে সে তাকে খুন করতে ভয় পেয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ مَعْمَرٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏نَهَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَحَدَكُمْ لَيُسْأَلُ يَوْمَ الْقِيَامَةِ حَتَّى يَكُونَ فِيمَا يُسْأَلُ عَنْهُ أَنْ يُقَالَ ‏ ‏مَا مَنَعَكَ أَنْ تُنْكِرَ الْمُنْكَرَ إِذْ رَأَيْتَهُ قَالَ فَمَنْ لَقَّنَهُ اللَّهُ حُجَّتَهُ قَالَ رَبِّ رَجَوْتُكَ وَخِفْتُ النَّاسَ ‏","","",""],[10783,10783,"","আমার ভাইয়ের ভালো কাজ নিয়ে কথা বলেছি, আমি তার মুখটা ধরে নেই, সে মারা যায়নি যতক্ষণ না লোকটি তাকে যেতে বলছে, ততক্ষণ পর্যন্ত সে মারা যায় নি। তারপর সে তোমাকে এমন কিছু থেকে বের করে দিল যা তারা তাকে আবার তাকে নিয়ে গিয়েছিল। যখন সে তোমাকে দেখেছে.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏صَيْفِيٍّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏وَجَدَ رَجُلٌ فِي مَنْزِلِهِ حَيَّةً فَأَخَذَ رُمْحَهُ فَشَكَّهَا فِيهِ فَلَمْ تَمُتْ الْحَيَّةُ حَتَّى مَاتَ الرَّجُلُ فَأُخْبِرَ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ مَعَكُمْ ‏ ‏عَوَامِرَ ‏ ‏فَإِذَا رَأَيْتُمْ مِنْهُمْ شَيْئًا ‏ ‏فَحَرِّجُوا ‏ ‏عَلَيْهِ ثَلَاثًا فَإِنْ رَأَيْتُمُوهُ بَعْدَ ذَلِكَ فَاقْتُلُوهُ ‏","","",""],[10784,10784,"","আমার বাবা ঈশ্বরের কাছে তার কাছে পাঠানোয় খুশি হন, যিনি তার কাছে এসেছেন । আমি যদি তাকে জিজ্ঞেস করি যে, তিনি তাকে হারিয়ে ফেলবেন না, তাহলে তিনি বলেছিলেন, ঈশ্বর তাকে হারিয়ে ফেলবেন না । ঈশ্বর তাকে উপস্থিত করবেন, যেমন তার আরেকটা গাছ, অন্ধকার ছায়া এবং জল থাকবে । সে তার মাথা থেকে মদ খাবে আর বলবে যে এটা করতে হবে, ঈশ্বর কি আমাকে অপরাধ খুঁজে পেতে হবে, ঈশ্বর নরকে গিয়ে জাহান্নামের দিকে যাচ্ছেন। তিনি বলবেন আমি দুর্দশার পথে কি পেতে যাচ্ছি। এটাই তিনি ঈশ্বরের কাছে বলেছেন। আর তিনি বিশ্বাস করেন যে তিনি ঈশ্বরকে মনে রাখবেন, তিনি কে এবং আপনার জন্য। আমি তাকে স্বর্গে যেতে দেব এবং স্বর্গে প্রবেশ করব, অথবা তাকে প্রবেশ করব। মাঝে মাঝে আমি আপনাকে আমার কাছে বলতে চাই না যে আমি যা দান করি তা হচ্ছে আমি দান করি এবং আমি সাহস করি। ওর ব্রেইন এখন আমাদের স্বাধীন করার উপায়।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ أَبِي الْعَيَّاشِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ ‏ ‏أَدْنَى ‏ ‏أَهْلِ الْجَنَّةِ مَنْزِلَةً رَجُلٌ صَرَفَ اللَّهُ وَجْهَهُ عَنْ النَّارِ قِبَلَ الْجَنَّةِ وَمَثَّلَ لَهُ شَجَرَةً ذَاتَ ظِلٍّ فَقَالَ أَيْ رَبِّ قَدِّمْنِي إِلَى هَذِهِ الشَّجَرَةِ فَأَكُونَ فِي ظِلِّهَا فَقَالَ اللَّهُ ‏ ‏هَلْ عَسَيْتَ إِنْ فَعَلْتُ أَنْ تَسْأَلَنِي غَيْرَهَا قَالَ لَا وَعِزَّتِكَ فَقَدَّمَهُ اللَّهُ إِلَيْهَا وَمَثَّلَ لَهُ شَجَرَةً ذَاتَ ظِلٍّ وَثَمَرٍ فَقَالَ أَيْ رَبِّ قَدِّمْنِي إِلَى هَذِهِ الشَّجَرَةِ أَكُونُ فِي ظِلِّهَا وَآكُلُ مِنْ ثَمَرِهَا فَقَالَ اللَّهُ لَهُ هَلْ عَسَيْتَ إِنْ أَعْطَيْتُكَ ذَلِكَ أَنْ تَسْأَلَنِي غَيْرَهُ فَيَقُولُ لَا وَعِزَّتِكَ فَيُقَدِّمُهُ اللَّهُ إِلَيْهَا فَتُمَثَّلُ لَهُ شَجَرَةٌ أُخْرَى ذَاتُ ظِلٍّ وَثَمَرٍ وَمَاءٍ فَيَقُولُ أَيْ رَبِّ قَدِّمْنِي إِلَى هَذِهِ الشَّجَرَةِ أَكُونُ فِي ظِلِّهَا وَآكُلُ مِنْ ثَمَرِهَا وَأَشْرَبُ مِنْ مَائِهَا فَيَقُولُ لَهُ هَلْ عَسَيْتَ إِنْ فَعَلْتُ أَنْ تَسْأَلَنِي غَيْرَهُ فَيَقُولُ لَا وَعِزَّتِكَ لَا أَسْأَلُكَ غَيْرَهُ فَيُقَدِّمُهُ اللَّهُ إِلَيْهَا فَيَبْرُزُ لَهُ بَابُ الْجَنَّةِ فَيَقُولُ أَيْ رَبِّ قَدِّمْنِي إِلَى بَابِ الْجَنَّةِ فَأَكُونَ تَحْتَ ‏ ‏نِجَافِ ‏ ‏الْجَنَّةِ وَأَنْظُرَ إِلَى أَهْلِهَا فَيُقَدِّمُهُ اللَّهُ إِلَيْهَا فَيَرَى أَهْلَ الْجَنَّةِ وَمَا فِيهَا فَيَقُولُ أَيْ رَبِّ أَدْخِلْنِي الْجَنَّةَ قَالَ فَيُدْخِلُهُ اللَّهُ الْجَنَّةَ قَالَ فَإِذَا دَخَلَ الْجَنَّةَ قَالَ هَذَا لِي قَالَ فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ لَهُ تَمَنَّ فَيَتَمَنَّى وَيُذَكِّرُهُ اللَّهُ سَلْ مِنْ كَذَا وَكَذَا حَتَّى إِذَا انْقَطَعَتْ بِهِ الْأَمَانِيُّ قَالَ اللَّهُ عَزَّ وَجَلَّ هُوَ لَكَ وَعَشَرَةُ أَمْثَالِهِ قَالَ ثُمَّ يَدْخُلُ الْجَنَّةَ يَدْخُلُ عَلَيْهِ زَوْجَتَاهُ مِنْ الْحُورِ الْعِينِ فَيَقُولَانِ لَهُ الْحَمْدُ لِلَّهِ الَّذِي أَحْيَاكَ لَنَا وَأَحْيَانَا لَكَ فَيَقُولُ مَا أُعْطِيَ أَحَدٌ مِثْلَ مَا أُعْطِيتُ قَالَ ‏ ‏وَأَدْنَى ‏ ‏أَهْلِ النَّارِ عَذَابًا يُنْعَلُ مَنْ نَارٍ بِنَعْلَيْنِ يَغْلِي دِمَاغُهُ مِنْ حَرَارَةِ نَعْلَيْهِ ‏","","",""],[10785,10785,"","ঈশ্বরের দোহাই দিয়ে কথা বলেছি, ঈশ্বর আমার কাছে প্রার্থনা করেছেন তিনি আত্মসমর্পণ করেছেন আর তাকে গ্রাস করতে আর ষড়যন্ত্র করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ عَمْرٍو الْكَلْبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُحَجَّنَّ ‏ ‏الْبَيْتُ ‏ ‏وَلَيُعْتَمَرَنَّ بَعْدَ خُرُوجِ ‏ ‏يَأْجُوجَ ‏ ‏وَمَأْجُوجَ ‏","","",""],[10786,10786,"","আমরা আমার আত্মার সবচেয়ে ভালো কথা বলেছি আর তারপর শুধু স্বপ্নই হবে প্রভুর সুখের মাস্টারের জন্য। সে এমন একজন যার জন্য নিজেকে আত্মসমর্পণ করতে এসেছে। এত শক্তিশালী হয়ে ওর সাথে হেঁটে হেঁটে গেল, ওর কাছে গাড়িও একটা।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى الْأَنْصَارِيِّ ‏ ‏وَأَبُو سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يُوسُفَ بْنِ عَبْدِ اللَّهِ بْنِ سَلَامٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ جَاءَ إِلَى جَنَازَةٍ فَمَشَى مَعَهَا مِنْ أَهْلِهَا حَتَّى يُصَلَّى عَلَيْهَا فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏وَمَنْ انْتَظَرَ حَتَّى تُدْفَنَ ‏ ‏أَوْ يُفْرَغَ مِنْهَا ‏ ‏فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[10787,10787,"","আমরা দুজন সালমামন তৈরি করেছি, আমি বলতে চাই, ঈশ্বরের ছেলের ভালবাসার অভ্যাস আছে, লর্ড তার জন্য প্রার্থনা করে বললেন যে এই বেমানান করা হবে।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏عِمْرَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيُحَجَّنَّ هَذَا ‏ ‏الْبَيْتُ ‏ ‏وَلَيُعْتَمَرَنَّ بَعْدَ خُرُوجِ ‏ ‏يَأْجُوجَ ‏ ‏وَمَأْجُوجَ ‏","","",""],[10788,10788,"","আমরা দুটো উপায় নিয়ে কথা বলেছি, আমরা ঈশ্বরের সর্বোচ্চ, কুত্তির ছেলে, আমার বাবার জন্য এই কথা বলে খুশি যে আমার নবী তার জন্য প্রার্থনা করেছেন এবং তিনি তার জন্য প্রার্থনা করেছেন। আমাকে জিজ্ঞেস করা হয়েছে যে আমি সুখী হব সেই ব্যক্তি যে হতে পারে সেই হবে সেই ব্যক্তি, যে হবে সেই হবে সেই ব্যক্তি, যে হবে সেই ব্যক্তি, যে হবে সেই ব্যক্তি। সে-ই হবে সেই ব্যক্তি যে হবে হবে, সে হবে একজন যে হবে হবে সেই হবে, সে হবে একজন যে হবে। সবচেয়ে খুশি হল আমি তোমার সাথে কখনো কথা বলিনি, পরে বলবো অথবা বলবো যে আমার মনে হয় যে আমার শত্রুকে বদলে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ أَبِي عَيَّاشٍ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَأَقُولُ أَصْحَابِي أَصْحَابِي فَقِيلَ إِنَّكَ لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ قَالَ فَأَقُولُ بُعْدًا بُعْدًا ‏ ‏أَوْ قَالَ ‏ ‏سُحْقًا ‏ ‏سُحْقًا ‏ ‏لِمَنْ بَدَّلَ بَعْدِي ‏","","",""],[10789,10789,"","আমরা কথা বলেছি আমার বাবা কিভাবে সুখী, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তিনি একটি জীবন বলতেন যে বেগুনি বমির আঘাতে আপনি মারা গেছেন।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَمَّارٍ ‏ ‏تَقْتُلُكَ ‏ ‏الْفِئَةُ ‏ ‏الْبَاغِيَةُ ‏","","",""],[10790,10790,"","ঈশ্বর তার কাছে প্রার্থনা করেছিলেন এবং তাকে সেই ব্যক্তিকে তার ঘরে ঢুকতে দিতে বলেছিলেন । পর্দা ছাড়া পাগল.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ ‏ ‏مَنَّانٌ ‏ ‏وَلَا ‏ ‏عَاقٌّ ‏ ‏وَلَا مُدْمِنُ خَمْرٍ ‏","","",""],[10791,10791,"","আমরা আমাদের সবচেয়ে ভালো ভাইয়ের বাপ্তিস্মের কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি বললেন যে আপনার একটি অন্তরের সাথে হাত মিলিয়ে আপনার টাকা ভরে যাবে এবং পরে ঋণ শোধ করা হবে। ভগ্নাংশ আর বদলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏مَطَرٌ ‏ ‏وَالْمُعَلَّى ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تُمْلَأُ الْأَرْضُ ظُلْمًا ‏ ‏وَجَوْرًا ‏ ‏ثُمَّ يَخْرُجُ رَجُلٌ مِنْ ‏ ‏عِتْرَتِي ‏ ‏يَمْلِكُ سَبْعًا أَوْ تِسْعًا فَيَمْلَأُ الْأَرْضَ قِسْطًا وَعَدْلًا ‏","","",""],[10792,10792,"","ঈশ্বর আমার বাবাকে এই কাজের জন্য দিয়েছেন । আমার দাস, আমি তোমাকে যেতে বলছি, আর আশা করি মানুষ শেষ হবে,","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏وَعَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جُحَادَةَ ‏ ‏حَدَّثَنِي ‏ ‏الْوَلِيدُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْبَهِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكُونُ عَلَيْكُمْ أُمَرَاءُ تَطْمَئِنُّ إِلَيْهِمْ الْقُلُوبُ وَتَلِينُ لَهُمْ الْجُلُودُ ثُمَّ يَكُونُ عَلَيْكُمْ أُمَرَاءُ تَشْمَئِزُّ مِنْهُمْ الْقُلُوبُ وَتَقْشَعِرُّ مِنْهُمْ الْجُلُودُ فَقَالَ رَجُلٌ أَنُقَاتِلُهُمْ يَا رَسُولَ اللَّهِ قَالَ لَا مَا أَقَامُوا الصَّلَاةَ ‏","","",""],[10793,10793,"","আমরা আমার বাবার সাথে যা ঘটেছে তার কথা বলেছি কিন্তু আমি সুখী হতে চাই, কৌশলটা হচ্ছে তাকে শান্তি আনতে, যা তাকে আদেশ করে এবং হত্যা করে তুমি, কিন্তু সে তোমাকে মেরে ফেলতে হবে, ঈশ্বরের নাম হল তোমাকে সব থেকে দূরে ফেলে দিবে... ...যা থেকে তোমাকে কষ্ট দেয়... ...আর তোমাকে ঈশ্বরের নামে ডাকা যায়.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ صُهَيْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ اشْتَكَيْتَ يَا ‏ ‏مُحَمَّدُ ‏ ‏قَالَ نَعَمْ قَالَ ‏ ‏بِسْمِ اللَّهِ ‏ ‏أَرْقِيكَ مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ مِنْ شَرِّ كُلِّ نَفْسٍ وَعَيْنٍ ‏ ‏يَشْفِيكَ بِسْمِ اللَّهِ ‏ ‏أَرْقِيكَ ‏","","",""],[10794,10794,"","আমরা ঈশ্বরের ছেলের সাথে কথা বলেছি, যে কিনা আমার নিজের চেহারার কথা বলেছে। প্রার্থনা করে আমরা দু'জন ফিরে এসেছি।","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُفْطِرُ يَوْمَ الْفِطْرِ قَبْلَ أَنْ يَخْرُجَ وَكَانَ لَا ‏ ‏يُصَلِّي قَبْلَ الصَّلَاةِ فَإِذَا قَضَى صَلَاتَهُ صَلَّى رَكْعَتَيْنِ ‏","","",""],[10795,10795,"","আমরা বাবার কাছে আমার বাবার কাছে ফিরে আসার মহানতার কথা বলেছি, ঈশ্বর আদেশ দিয়েছেন আর তিনি বলবেন আমি যদি তোমাকে ধোঁকা দেই তাহলে তার আলো ফিরে আসবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَاضِرُ بْنُ الْمُوَرِّعِ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏غَشِيَ ‏ ‏أَحَدُكُمْ أَهْلَهُ ثُمَّ أَرَادَ أَنْ يَعُودَ فَلْيَتَوَضَّأْ وُضُوءَهُ لِلصَّلَاةِ ‏","","",""],[10796,10796,"","আমরা বাবার কোলে যাবার কথা বলেছিলাম আর তোমাকে খুন করার চেষ্টা করেছি। একটা নির্দিষ্ট স্বপ্ন দিয়ে কাজ করেছি, তুমি মারা যাচ্ছ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ وَهْبٍ ‏ ‏وَأَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي ‏ ‏سَبْيِ ‏ ‏أَوْطَاسٍ ‏ ‏لَا ‏ ‏يَقَعُ ‏ ‏عَلَى حَامِلٍ حَتَّى تَضَعَ وَغَيْرِ حَامِلٍ حَتَّى تَحِيضَ حَيْضَةً ‏","","",""],[10797,10797,"","আমরা হারোণের সাথে কথা বলেছি আর আমি শুনেছি আমি অ্যারনের সাথে কথা বলেছি। বাবার খুশির দাসের পক্ষ থেকে বলছি যে আমরা ঈশ্বরের অনুগ্রহ। তিনি তার সাথে ছিলেন এবং তার সাথে আছেন। তুমি ঐ বদমাশটা ঘুরিয়ে দেবে... ...সে বলেছিল হয়তো ভেসে গেছে, লর্ড।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏و سَمِعْت ‏ ‏أَنَا مِنْ ‏ ‏هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ بْنِ مُسَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْسِمُ شَيْئًا أَقْبَلَ رَجُلٌ ‏ ‏فَأَكَبَّ ‏ ‏عَلَيْهِ فَطَعَنَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعُرْجُونٍ ‏ ‏كَانَ مَعَهُ فَجُرِحَ بِوَجْهِهِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَعَالَ ‏ ‏فَاسْتَقِدْ ‏ ‏قَالَ قَدْ عَفَوْتُ يَا رَسُولَ اللَّهِ ‏","","",""],[10798,10798,"","আমরা একটা মোসাস বালকর কথা বলেছি যে আমার ভাইকে সাহায্য করছে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমি যদি মহিমার মধ্যে আত্মসমর্পণ করবো, এটা নয়। এটা আমার ভাই আমাকে সাহায্য করেছে। আমি যদি তার জন্য প্রার্থনা করি, আমি তাকে ছেড়ে দেব। আমি যদি তার কাছে প্রার্থনা করি, আমি আমার ভাই-বাবার জন্য প্রার্থনা করি, আমি তাকে ছেড়ে দেব। কিন্তু আমি যদি আমার জীবনের জন্য প্রার্থনা করি, এটা আমার জীবনের জন্য একটা উদ্দেশ্য হবে। কিন্তু আমি যদি আমার জীবনের জন্য একটা উদ্দেশ্য ছিল না। কিন্তু আমি আমার জীবনের জন্য প্রার্থনা করি, এটা আমার জীবনের জন্য একটা কঠিন কাজ হবে। কিন্তু আমি যদি আমি আমার জীবনের জন্য না করি, তাহলে আমি আমার বাবা-মা'র জন্য কাজ করতে পারি। কিন্তু আমি আমার বাবা-মা'র কাছে ফিরে আসব। আমি আমার বাবা-মাদার কাছে প্রার্থনা করি। কিন্তু আমি যদি আমার বাবা-মা'র কাছে ফিরে যাই, আমি তাকে ছেড়ে দেব। কিন্তু আমি আমার বাবা-মাদারীতালির জন্য প্রার্থনা করি, আমি আমার বাবা-মাদারি করতে পারি।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏دَرَّاجٌ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ أَنَّ أَحَدَكُمْ يَعْمَلُ فِي صَخْرَةٍ صَمَّاءَ لَيْسَ لَهَا بَابٌ وَلَا ‏ ‏كُوَّةٌ ‏ ‏لَخَرَجَ عَمَلُهُ لِلنَّاسِ كَائِنًا مَا كَانَ ‏","","",""],[10799,10799,"","ঈশ্বরের দোহাই দেয়া হয়েছে আর যদি আমি ঈশ্বরের বালতি হই, আমি মোটা মানুষ।","‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ أَنَّ دَلْوًا مِنْ ‏ ‏غَسَّاقٍ ‏ ‏يُهَرَاقُ ‏ ‏فِي الدُّنْيَا لَأَنْتَنَ أَهْلَ الدُّنْيَا ‏","","",""],[10800,10800,"","ঈশ্বরের দোহাই তাকে উদ্ধার করতে হবে এবং সে বলবে সে সব শেষ হয়ে গেছে।","‏ ‏وَعَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَأْكُلُ التُّرَابُ كُلَّ شَيْءٍ مِنْ الْإِنْسَانِ إِلَّا ‏ ‏عَجْبَ ‏ ‏ذَنَبِهِ قِيلَ وَمِثْلُ مَا هُوَ يَا رَسُولَ اللَّهِ قَالَ مِثْلُ حَبَّةِ ‏ ‏خَرْدَلٍ ‏ ‏مِنْهُ تَنْبُتُونَ ‏","","",""]];
